window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0138", [{"word":"mythological","ipa_uk":"/mɪˈθɒlədʒɪkl/","ipa_us":"/mɪˈθɑːlədʒɪkl/","definition_zh":"神话的；神话中的；神话学的；被讲述得超乎常人的；虚构的","definition_en":"belonging to or found in myths, or concerned with the study of myths","core_image":"洞壁上用赭石画出半人半兽的轮廓，火把从下方照上去，影子比真人还高","scene":"展厅的墙面上画着一只半人半兽的怪兽，讲解员正指着它讲古老的来历。The guide explains the mythological creature painted across the exhibition wall.","sceneCN":"这里 mythological 指「出自神话、属于神话世界的」（第 1 个义项：存在于神话叙事中而非现实里）；句意为讲解员解说展墙上一只神话中的怪兽。可辨识物件：展墙、半人半兽纹样、射灯、讲解牌。","pos":[{"tag":"adj.","zh":"神话的；神话中的；神话学的；传说化的"}],"collocations":[{"phrase":"mythological figure","zh":"神话人物"},{"phrase":"mythological creature","zh":"神话生物"},{"phrase":"mythological tradition","zh":"神话传统"},{"phrase":"mythological theme","zh":"神话主题"},{"phrase":"mythological allusion","zh":"神话典故"},{"phrase":"mythological significance","zh":"神话层面的意义"}],"forms":[{"label":"原级","form":"mythological"},{"label":"比较级","form":"more mythological"},{"label":"最高级","form":"most mythological"},{"label":"副词","form":"mythologically"},{"label":"名词（神话学）","form":"mythology"},{"label":"名词（神话）","form":"myth"}],"derivatives":[{"word":"myth","pos":"n.","zh":"基础词 myth 去掉学科形容词后缀 -logical 后剩下的名词核心，语义由「属于神话」收窄为「一则神话故事」"},{"word":"mythology","pos":"n.","zh":"基础词 myth + 希腊 -logia（「讲述、研究」）→ 由「神话故事」偏移为「神话的整体汇集与研究」"},{"word":"mythic","pos":"adj.","zh":"基础词 myth + -ic（形容词后缀）→ 由「神话」偏移为「具有神话性质的、传奇般的」"},{"word":"mythical","pos":"adj.","zh":"基础词 myth + -ical（形容词后缀）→ 侧重「只存在于神话中、并不真实」"},{"word":"mythologize","pos":"v.","zh":"mythology + -ize（动词后缀）→ 由「神话」偏移为「把某人某事讲成神话」"},{"word":"mythologization","pos":"n.","zh":"mythologize + -ation（动作名词后缀）→ 偏移为「被神话化的过程」"},{"word":"mythographer","pos":"n.","zh":"希腊 mythographos（mythos + graphein「书写」）→ 偏移为「收集并记录神话的人」"},{"word":"mythologist","pos":"n.","zh":"mythology + -ist（人名词后缀）→ 偏移为「研究神话的学者」"}],"senses":[{"no":"01","title":"Existing in myth","titleCN":"神话中的，出自神话叙事的","definition":"existing in or belonging to a myth rather than to recorded history","definitionCN":"存在于神话之中、属于神话而非有记载的历史","example":"The labyrinth was guarded by a mythological beast.","exampleCN":"那座迷宫由一只神话中的怪兽看守。","why":"mythos named a told story, and -logical marks whatever belongs to that stock of stories, so the adjective first means found in the tales.","whyCN":"mythos 指「被讲述的故事」，-logical 标记属于这类故事的东西，因此这个形容词首先表示「出现在被讲述的故事里」。"},{"no":"02","title":"Belonging to the mythic world","titleCN":"属于整个神话世界的","definition":"belonging to the whole imagined world of gods, heroes and monsters described by a culture's myths","definitionCN":"属于一个文化的神话所描绘的整个神、英雄与怪兽的想象世界","example":"Mythological geography placed the gods on a peak no climber could reach.","exampleCN":"神话地理把众神安置在一座无人能登顶的山峰上。","why":"once a culture holds many tales, the adjective covers the shared world they describe, not just a single story.","whyCN":"一个文化一旦拥有许多故事，这个形容词就覆盖它们共同描绘的那个世界，而不只是某一则故事。"},{"no":"03","title":"Relating to the study of myths","titleCN":"神话学的，研究神话的","definition":"concerned with the scholarly collection, classification and comparison of myths","definitionCN":"涉及对神话的学术收集、分类与比较","example":"Mythological research compared flood stories from six continents.","exampleCN":"神话学研究比较了六个大洲的洪水故事。","why":"the -logia element means telling or study, so the adjective also names the academic approach to myths.","whyCN":"-logia 这一成分意为「讲述、研究」，所以这个形容词也指对神话的学术研究取向。"},{"no":"04","title":"Legendary in scale","titleCN":"传说化的，被讲得超乎常人的","definition":"described in the exaggerated terms of legend, so that the person or deed is larger than life","definitionCN":"以传说的夸张口吻描述，使人或事迹超出真实尺度","example":"His mythological stamina carried him through three days without sleep.","exampleCN":"他被传得神乎其神的体力让他三天不睡也撑了下来。","why":"storytellers enlarge a real person until the tale fits the shape of myth, and the adjective follows that enlargement.","whyCN":"讲述者会把真实人物放大，直到故事符合神话的形状，这个形容词也随之指这种放大。"},{"no":"05","title":"Fictitious, not real","titleCN":"虚构的，并不存在的","definition":"existing only in imagination; invented and without basis in fact","definitionCN":"只存在于想象中；编造而无事实依据","example":"The danger turned out to be mythological, invented to frighten the newcomers.","exampleCN":"那个危险后来证明是虚构的，只是为了吓唬新来的人而编出来的。","why":"since myths are stories, calling something mythological can deny it any place in the real world.","whyCN":"既然神话是故事，把某物称作 mythological 就可以否认它在现实世界里有一席之地。"},{"no":"06","title":"Explaining an origin","titleCN":"解释起源的","definition":"describing how a natural thing, a custom or a place first came to be","definitionCN":"说明某种自然物、习俗或地方最初如何形成","example":"The mythological account of fire traced it to a stolen ember.","exampleCN":"关于火的神话式说法把火追溯到一粒被偷走的余烬。","why":"many myths exist precisely to explain origins, so the adjective marks narratives whose purpose is explanation.","whyCN":"许多神话正是为了解释起源而存在，因此这个形容词标出以解释为目的的叙事。"},{"no":"07","title":"Symbolic and archetypal","titleCN":"象征性的，原型式的","definition":"carrying the symbolic weight of an archetype rather than literal factual detail","definitionCN":"承载原型的象征分量，而非字面的事实细节","example":"The mythological mother figure appears in every version of the tale.","exampleCN":"这个神话式的母亲形象出现在故事的每一个版本里。","why":"myth speaks in symbols, so what is called mythological often means what carries that symbolic charge.","whyCN":"神话以象征说话，因此被称为 mythological 的往往指承载这种象征分量的东西。"},{"no":"08","title":"As a subject in art","titleCN":"神话题材的（艺术用语）","definition":"used of painting, music or literature that takes myths as its subject matter","definitionCN":"用于以神话为题材的绘画、音乐或文学","example":"The mythological frescoes cover the west wall of the chapel.","exampleCN":"教堂西墙上满是神话题材的壁画。","why":"the adjective here labels a category of subject in the arts, not a claim about what exists.","whyCN":"这里的形容词在艺术中标记的是一个题材类别，而不是对存在与否的断言。"}],"etymology":{"intro":{"en":"Mythological is built on Greek mythos 'word, speech, story' plus the suffix -logia 'telling, study', and reached English through Late Latin mythologicus and French mythologique. Dates are approximate.","cn":"mythological 由希腊 mythos「言说、故事」加后缀 -logia「讲述、研究」构成，经晚期拉丁 mythologicus 与法语 mythologique 进入英语。年代均为约数。"},"items":[{"era":"GREEK MYTHOS","en":"Mythos meant 'word, speech, tale'. Its deeper origin is not established: no Indo-European source has been demonstrated, and the often suggested link with a verb of speaking is a hypothesis rather than a proven derivation.","cn":"mythos 意为「言语、讲述、故事」。其更早来源未得到证明：没有任何印欧语来源被证实；常有人把它与某个「说」的动词联系起来，那只是假说，并非已证实的派生。"},{"era":"GREEK MYTHOLOGIA","en":"Mythos plus -logia, from logos 'word, account', produced mythologia 'the telling of tales, legend'. The compound names both the activity of narrating and the body of tales told.","cn":"mythos 加 -logia（来自 logos「言说、道理」）构成 mythologia「讲故事、传说」，既指叙述活动，也指被讲述的那一批故事。"},{"era":"GREEK MYTHOLOGIKOS","en":"The adjective mythologikos described a person skilled in telling tales, and later what belongs to tales of gods and heroes.","cn":"形容词 mythologikos 最初形容擅长讲故事的人，后来指属于神与英雄故事的东西。"},{"era":"LATE LATIN","en":"Late Latin mythologicus was formed directly on the Greek adjective; it is a borrowed learned word, not an inherited Latin relative.","cn":"晚期拉丁 mythologicus 直接依希腊形容词构成；它是借入的学术词，而非拉丁语固有同族词。"},{"era":"FRENCH AND ENGLISH","en":"French mythologique passed into English as mythological in the seventeenth century, first in the sense of relating to myths and their study.","cn":"法语 mythologique 在十七世纪进入英语成为 mythological，最初指与神话及其研究相关。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Greek origin of mythos is unsettled and the exact first English date is not recorded, so any older form offered for mythos is a reconstructed form rather than attested evidence.","cn":"来源不确定：mythos 在希腊语之前的来源无定论，英语首见的确切年代也没有记录，因此凡为 mythos 给出的更早形式均属重构形式，而非有书证的材料。"}]},"similar":{"note":{"en":"Group one holds the myth family and its closest story-words, which are constantly swapped; group two holds words that deny reality or carry symbolic meaning.","cn":"第一组是 myth 词族及其最近的故事类词，最易互相替换出错；第二组是否认现实或承载象征意义的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mythic","ipa":"/ˈmɪθɪk/","tag":"story-shaped","definition":"Of or like myth, often used of a person or event raised to legendary stature; it leans toward the symbolic rather than toward one particular tale.","definitionCN":"属于或类似神话的，常用于被抬到传奇地位的人或事件；侧重象征性，而非某一则具体故事。"},{"word":"mythical","ipa":"/ˈmɪθɪkl/","tag":"not real","definition":"Chiefly means imagined or fictitious; it overlaps mythic but pushes harder toward 'does not exist'.","definitionCN":"主要指想象中或虚构的；与 mythic 有重叠，但更强调「并不存在」。"},{"word":"myth","ipa":"/mɪθ/","tag":"the story itself","definition":"The noun names a traditional tale or a widely believed falsehood; the adjective describes what such a tale contains, the noun names the tale.","definitionCN":"名词指传统故事或广为相信的谬见；形容词描述这类故事里的东西，名词则指故事本身。"},{"word":"mythology","ipa":"/mɪˈθɒlədʒi/","tag":"the collection","definition":"A body of myths, or the study of them; it names the whole set, while mythological describes what belongs to it.","definitionCN":"指神话的整体汇集或对神话的研究；它命名整套，而 mythological 描述属于这套的东西。"},{"word":"legend","ipa":"/ˈledʒənd/","tag":"different genre","definition":"A story about a human hero, usually with a historical kernel; myth concerns gods and origins, so the two are not interchangeable.","definitionCN":"关于人类英雄的故事，通常有一点历史内核；神话关注神与起源，二者不能互换。"}]},{"heading":"NEAR MEANING","entries":[{"word":"fabulous","ipa":"/ˈfæbjələs/","tag":"fable-based","definition":"From fabula 'story': belonging to fable, hence incredible; it stresses the unbelievable rather than the sacred.","definitionCN":"来自 fabula「故事」：属于寓言的，因而难以置信；它强调不可信，而非神圣性。"},{"word":"fictitious","ipa":"/fɪkˈtɪʃəs/","tag":"invented","definition":"Plainly 'made up'; it denies reality without implying any sacred or explanatory function.","definitionCN":"直白地表示「编造的」；它否认现实性，但不含神圣或解释功能。"},{"word":"apocryphal","ipa":"/əˈpɒkrɪfl/","tag":"doubtful authenticity","definition":"Said of a story that circulates as true but is probably not; it targets credibility rather than genre.","definitionCN":"指以真实之名流传、却很可能不真的故事；它针对可信度，而非文类。"},{"word":"symbolic","ipa":"/sɪmˈbɒlɪk/","tag":"standing for something","definition":"Carrying a meaning beyond the literal; myths are symbolic, but a symbolic gesture need not come from any myth.","definitionCN":"承载字面之外的意义；神话是象征性的，但象征性的举动未必出自神话。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real fixed phrases and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实固定搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mythos 'story' + -logical 'pertaining to': pertaining to told stories.","cn":"mythos「故事」+ -logical「与……相关」：与被人讲述的故事相关。"},{"en":"The family runs myth, mythic, mythical, mythology, mythologist, mythologize.","cn":"同族词包括 myth、mythic、mythical、mythology、mythologist、mythologize。"},{"en":"Fixed phrases mark the everyday uses: mythological figure, mythological creature, mythological theme.","cn":"固定搭配标出日常用法：神话人物、神话生物、神话主题。"},{"en":"The same -logia element appears in theology, biology and geology, each naming a field of telling or study.","cn":"同一个 -logia 成分出现在 theology、biology 与 geology 中，都指某个讲述或研究的领域。"},{"en":"The story stock also yields mythographer and mythography, words for collecting and writing down myths.","cn":"同一批故事还衍生出 mythographer 与 mythography，指收集并记录神话的人与工作。"}],"abstract":[{"en":"Picture a stone wall lit from below, where every painted figure casts a shadow taller than a person.","cn":"想象一面被下方火光照亮的石壁，上面每个画出的形象都投下比人更高的影子。"},{"en":"Picture a map that marks a mountain where gods live, yet shows no path leading there.","cn":"想象一张地图，标着神居住的山，却没有画出任何一条通到那里的路。"},{"en":"Picture a man retold so many times that the telling has made him a head taller than he was.","cn":"想象一个人被反复讲述，讲到后来他比本人高出了一个头。"}]},"examples":[{"en":"The mosaic shows a mythological hunt in which a goddess stops the arrows in midair.","cn":"这幅镶嵌画描绘一场神话中的狩猎，一位女神让箭停在半空。"},{"en":"Scholars treat the flood narrative as mythological rather than as a weather report.","cn":"学者把那则洪水叙事当作神话来看，而不是当作气象记录。"},{"en":"His reputed speed on the field has become almost mythological among local fans.","cn":"他在球场上传说般的速度，在当地球迷中几乎已成神话。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「myth（神话）+ 连接元音 + logical（学科形容词后缀）」——属于神话那一类 → 神话的、神话中的","word":"mythological"},"root":"希腊 mythos「言说、故事」+ -logia（来自 logos「言说、道理」）「讲述、研究」；mythos 更早来源不确定。英语 mythological 经晚期拉丁 mythologicus 与法语 mythologique 进入。","sensesIntro":{"en":"Eight senses follow one movement: a told story first fills a whole imagined world, then becomes an object of study, then lends its exaggerated scale and its unreality to ordinary speech, and finally becomes a subject category in art.","cn":"八个义项沿一个走向展开：被讲述的故事先撑起一整个想象世界，再成为研究对象，随后把夸张的尺度与「不真实」借给日常语言，最后成为艺术中的一个题材类别。"},"semanticMap":{"core":{"en":"CORE IMAGE: a story told about gods, and the shadow it casts over the real world.","cn":"核心意象：一则关于神的故事，以及它投在现实世界上的影子。"},"chain":["TOLD STORY","SHARED MYTH WORLD","STUDY OF STORIES","LARGER THAN LIFE","NOT REAL","SYMBOLIC SUBJECT"],"branches":[{"senses":"01 · 02","en":"THE STORY AND ITS WORLD: one tale first, then the whole imagined geography that holds all the tales together.","cn":"故事与其世界：先是一则故事，再是容纳全部故事的整个想象地理。"},{"senses":"03","en":"THE STUDY: the -logia element turns the tales into objects that can be collected, compared and classified.","cn":"研究：-logia 这一成分把这些故事变成可收集、可比较、可分类的对象。"},{"senses":"04 · 05","en":"SCALE AND REALITY: telling enlarges a figure, and calling something mythological can also be a way of denying that it exists.","cn":"尺度与真实：讲述会放大人物，而称之为神话也可以是在否认它存在。"},{"senses":"06","en":"EXPLANATION: a story that answers where fire, seasons or customs first came from.","cn":"解释：回答火、季节或习俗最初从何而来的故事。"},{"senses":"07 · 08","en":"SYMBOL AND SUBJECT: the archetype carries meaning, and the arts take myths as a category of subject matter.","cn":"象征与题材：原型承载意义，艺术则把神话当作一个题材类别。"}]},"affixes":{"intro":{"en":"Mythological can be read in parts: a Greek noun for a told story, a linking vowel, and a suffix that names a field of study.","cn":"mythological 可以按部分读出：一个指「被讲述的故事」的希腊名词、一个连接元音，以及一个指研究领域的后缀。"},"latinIntro":{"en":"There is no inherited Latin family here. The stock is Greek: mythos reached Latin only as a borrowed noun, and mythologicus is a Late Latin adjective shaped on the Greek model, so no genuine Latin cognate exists.","cn":"这里没有拉丁语固有词族。其来源是希腊语：mythos 只作为借词进入拉丁语，mythologicus 是依希腊范式构成的晚期拉丁形容词，因此不存在真正的拉丁同族词。"},"items":[{"word":"myth-","structure":"Greek mythos (noun, 'word, speech, story')","meaning":"a told story","meaningCN":"被讲述的故事","example":"The root carries the idea of something spoken aloud.","exampleCN":"这个词根带着「被大声讲出来」的意思。"},{"word":"-o-","structure":"linking vowel between Greek elements","meaning":"joins two Greek parts","meaningCN":"连接两个希腊语成分","example":"The vowel keeps the compound pronounceable.","exampleCN":"这个元音让复合词读得顺口。"},{"word":"-logical","structure":"-logikos (Greek adjective suffix, from logos 'word, account')","meaning":"pertaining to a field of study","meaningCN":"与某研究领域相关的","example":"The suffix turns a subject into an adjective.","exampleCN":"这个后缀把一个学科变成形容词。"},{"word":"mythology","structure":"myth + -ology (study, collection)","meaning":"a body of myths or their study","meaningCN":"神话的汇集或对神话的研究","example":"The mythology of the region survives in song.","exampleCN":"该地区的神话靠歌谣留存下来。"},{"word":"mythic","structure":"myth + -ic (adjective suffix)","meaning":"of the nature of myth","meaningCN":"具有神话性质的","example":"The battle took on a mythic colour.","exampleCN":"那场战斗带上了一层神话色彩。"},{"word":"mythical","structure":"myth + -ical (adjective suffix)","meaning":"existing only in myth","meaningCN":"只存在于神话中的","example":"The mythical island appears on old charts.","exampleCN":"那座神话中的岛屿出现在旧海图上。"},{"word":"mythologize","structure":"mythology + -ize (verb suffix)","meaning":"to turn into myth","meaningCN":"把……讲成神话","example":"Later writers mythologized the general's retreat.","exampleCN":"后来的作家把这位将军的撤退写成了神话。"},{"word":"mythologization","structure":"mythologize + -ation (action noun)","meaning":"the process of becoming myth","meaningCN":"被神话化的过程","example":"The mythologization of the frontier took a generation.","exampleCN":"边疆被神话化用了一代人的时间。"},{"word":"mythographer","structure":"Greek mythographos (mythos + graphein 'to write')","meaning":"a collector and writer of myths","meaningCN":"收集并记录神话的人","example":"The mythographer listed three versions of the birth story.","exampleCN":"这位神话记录者列出了这个诞生故事的三个版本。"},{"word":"mythologist","structure":"mythology + -ist (person suffix)","meaning":"a scholar of myths","meaningCN":"研究神话的学者","example":"The mythologist traced the motif across languages.","exampleCN":"这位神话学者跨越语言追踪了这个母题。"}],"latinEntries":[]}},{"word":"myth","ipa_uk":"/mɪθ/","ipa_us":"/mɪθ/","definition_zh":"神话；神话故事；神话体系；广为相信的谬见；虚构的人或事；编造的托词","definition_en":"a traditional story about gods or origins, or a widely believed but false idea","core_image":"夜里的火堆旁，老人用手比划着天与地如何分开，听的人明知不是真的却仍点头","scene":"火堆旁，老人把陶罐放在膝上，向围坐的孩子讲起天和地最初如何分开。An old storyteller recounts the myth of how sky and earth were separated.","sceneCN":"这里 myth 指「关于神或世界起源的传统故事」（第 1 个义项：世代相传的神话叙事）；句意为一位老讲述者讲述天与地如何分开的神话。可辨识物件：火堆、陶罐、围坐的孩子、夜色。","pos":[{"tag":"n.","zh":"神话；神话故事；神话体系；谬见；虚构的人或事"}],"collocations":[{"phrase":"ancient myth","zh":"古老神话"},{"phrase":"Greek myth","zh":"希腊神话"},{"phrase":"popular myth","zh":"流行的错误说法"},{"phrase":"explode a myth","zh":"破除一个谬见"},{"phrase":"myth and legend","zh":"神话与传说"},{"phrase":"the myth of progress","zh":"关于进步的虚妄信念"}],"forms":[{"label":"单数","form":"myth"},{"label":"复数","form":"myths"},{"label":"形容词（神话的）","form":"mythic"},{"label":"形容词（神话学的）","form":"mythological"},{"label":"名词（神话体系、神话学）","form":"mythology"},{"label":"动词（把……神话化）","form":"mythologize"}],"derivatives":[{"word":"mythic","pos":"adj.","zh":"基础词 myth + -ic（形容词后缀）→ 由「神话故事」偏移为「具有神话气质的、传奇般的」"},{"word":"mythical","pos":"adj.","zh":"基础词 myth + -ical（形容词后缀）→ 偏移为「只存在于神话中、虚构的」"},{"word":"mythology","pos":"n.","zh":"基础词 myth + 希腊 -logia（「讲述、研究」）→ 由「一则故事」偏移为「神话的整体汇集与研究」"},{"word":"mythologist","pos":"n.","zh":"mythology + -ist（人名词后缀）→ 偏移为「研究神话的学者」"},{"word":"mythologize","pos":"v.","zh":"mythology + -ize（动词后缀）→ 由「神话」偏移为「把某人某事讲成神话」"},{"word":"mythologization","pos":"n.","zh":"mythologize + -ation（动作名词后缀）→ 偏移为「被讲成神话的过程」"},{"word":"mythmaker","pos":"n.","zh":"myth + maker（英语复合，表制造者）→ 偏移为「编造神话或制造流行谬见的人」"}],"senses":[{"no":"01","title":"A traditional tale of gods","titleCN":"关于神与起源的传统故事","definition":"a traditional story, usually concerning gods or the origin of the world, passed on by a community","definitionCN":"通常在讲神或世界起源、由群体世代相传的传统故事","example":"The myth tells how the first fire was carried down from the mountain.","exampleCN":"这则神话讲的是最初的火如何从山上被带下来。","why":"the Greek noun meant a thing spoken aloud, so a myth is first of all a story that a community keeps telling.","whyCN":"这个希腊名词原指被大声讲出来的东西，所以神话首先是一个群体不断讲述的故事。"},{"no":"02","title":"A body of myths","titleCN":"神话的整体汇集","definition":"the whole collection of such stories belonging to one culture or subject","definitionCN":"属于某一文化或主题的这类故事的整体汇集","example":"The myth of the region is preserved mainly in oral chant.","exampleCN":"该地区的神话主要靠口头吟唱保存。","why":"the singular noun can stand for a whole tradition, the way a library name stands for all its books.","whyCN":"单数名词可以代表整个传统，就像一座图书馆的名字代表它的全部藏书。"},{"no":"03","title":"A widely believed falsehood","titleCN":"广为相信的错误说法","definition":"an idea that many people accept as true although it has been shown to be false","definitionCN":"许多人信以为真、但已被证明为假的说法","example":"It is a myth that we use only a tenth of the brain.","exampleCN":"「人只用了大脑的十分之一」是一种谬见。","why":"a story that everyone repeats can harden into something people treat as fact, and English extended the same noun to that kind of false belief.","whyCN":"一个被所有人反复讲述的故事会硬化成人们当作事实的东西，英语便把同一个名词扩展到这类错误信念上。"},{"no":"04","title":"A fabricated person or thing","titleCN":"虚构的人或物","definition":"a person or thing that exists only in imagination or in a story","definitionCN":"只存在于想象或故事中的人或物","example":"The feared pirate turned out to be a myth invented by the port's guides.","exampleCN":"那个令人惧怕的海盗后来证明是港口导游编出来的虚构人物。","why":"a figure that exists only because it is talked about is the same product as a story, with a face attached.","whyCN":"一个只因为被谈论才存在的人物，与一个故事是同一种产物，只是给它安上了一张脸。"},{"no":"05","title":"A made-up excuse","titleCN":"编造的托词","definition":"an invented account offered to explain or excuse something","definitionCN":"为解释或开脱某事而编出来的说法","example":"His story about a delayed train was pure myth.","exampleCN":"他那套火车误点的说法纯属编造。","why":"an excuse is a short story offered in place of the facts, so the same noun serves when the telling is deliberate.","whyCN":"托词是一则用来代替事实的短故事，因此当讲述是故意为之，同一个名词就派上了用场。"},{"no":"06","title":"A category of narrative","titleCN":"神话作为叙事类型（学术用语）","definition":"the class of narrative that scholars set apart from legend, folktale and history","definitionCN":"学者用来与传说、民间故事和历史相区分的那类叙事","example":"In this discipline, myth is defined by its concern with origins, not by its being false.","exampleCN":"在这门学科里，神话是由它关注起源来定义的，而不是由它虚假来定义的。","why":"scholars needed a neutral label for the genre, so the noun was kept but stripped of the everyday judgement that a myth is simply untrue.","whyCN":"学者需要给这一文类一个中性的标签，于是保留了这个名词，却去掉了日常语言里「神话就是假的」那层判断。"},{"no":"07","title":"A legendary figure","titleCN":"传奇式人物，被神化的偶像","definition":"a person who has been talked about so much that the telling has replaced the person","definitionCN":"被谈论得太多、以致讲述取代了本人的人物","example":"By the end of his career the boxer had become a myth in his own city.","exampleCN":"到职业生涯末期，这位拳手在自己城市里已经成了一个传奇。","why":"when the telling grows larger than the person, the story takes over the identity, and the noun names the figure that remains.","whyCN":"当讲述大过本人，故事便接管了这个身份，名词所指的就是剩下的那个形象。"},{"no":"08","title":"A story a society tells itself","titleCN":"社会讲给自己的叙事","definition":"a shared narrative that a society uses to explain or justify its own arrangements","definitionCN":"一个社会用来解释或为自己制度辩护的共同叙事","example":"The frontier myth still shapes how the country explains its history.","exampleCN":"边疆神话至今仍在塑造这个国家解释自身历史的方式。","why":"the abstract sense keeps the story element but shifts the function: the tale now explains the tellers to themselves.","whyCN":"抽象义保留了故事成分，却换了功能：故事现在用来向讲述者自己解释他们自身。"}],"etymology":{"intro":{"en":"Myth comes from Greek mythos 'word, speech, story', borrowed into Late Latin and then into modern languages; English took it through French in the nineteenth century. Dates are approximate.","cn":"myth 来自希腊 mythos「言语、讲述、故事」，先借入晚期拉丁，再进入近代诸语言；英语经法语在十九世纪引入。年代均为约数。"},"items":[{"era":"GREEK MYTHOS","en":"Mythos covered 'word, speech, thing said, tale'. It could mean a public pronouncement as much as a narrative, so speech and story were one idea.","cn":"mythos 涵盖「言语、讲述、所说之事、故事」，既可指公开宣告，也可指叙事，说话与故事在当时是一个概念。"},{"era":"GREEK PHILOSOPHY","en":"Philosophers set mythos against logos, the reasoned account, and from that contrast mythos acquired the overtone of an unproved story.","cn":"哲学家把 mythos 与 logos（理性论证）对立起来，自此 mythos 带上「未经证明的故事」这一色彩。"},{"era":"LATE LATIN MYTHOS","en":"Late Latin took mythos as a learned borrowing; it was not an inherited Latin noun and had no Latin relatives of its own.","cn":"晚期拉丁把 mythos 作为学术借词吸收；它不是拉丁语固有名词，也没有自身的拉丁同族词。"},{"era":"FRENCH MYTHE","en":"French mythe carried the learned word into modern use, and English myth followed in the nineteenth century.","cn":"法语 mythe 把这个学术词带入近代用法，英语的 myth 随后在十九世纪出现。"},{"era":"FALSE-BELIEF SENSE","en":"In the nineteenth and twentieth centuries the noun widened from sacred tales to any widely repeated falsehood, a sense now commoner than the original one.","cn":"在十九与二十世纪，这个名词从神圣故事扩展到任何被广泛重复的错误说法，这一义项如今比原义更常用。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of mythos before Greek is not established, and no Indo-European source has been demonstrated; any older form proposed for it is a reconstructed form.","cn":"来源不确定：mythos 在希腊语之前的来源未得到证明，也没有任何印欧语来源被证实；凡为它提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates myth from the story genres it is confused with; group two holds the everyday words for untrue or unproved accounts.","cn":"第一组把 myth 与常被混淆的故事文类分开；第二组是表示「不实、未经证明」的日常词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"legend","ipa":"/ˈledʒənd/","tag":"human hero","definition":"A story about a human hero, often attached to a real place or person; myth deals with gods and origins, legend keeps a historical foothold.","definitionCN":"关于人类英雄的故事，常附着于真实地点或人物；神话处理神与起源，传说则保留历史落脚点。"},{"word":"folktale","ipa":"/ˈfəʊlkteɪl/","tag":"common people","definition":"A story told among ordinary people, often for entertainment or moral instruction; it lacks the sacred and explanatory role of myth.","definitionCN":"在普通民众间讲述的故事，多用于娱乐或教化；它没有神话那种神圣与解释的作用。"},{"word":"fable","ipa":"/ˈfeɪbl/","tag":"lesson story","definition":"A short invented story, often with animals, that points to a moral; it is openly fictional and didactic.","definitionCN":"常以动物为主角的短小虚构故事，指向一条道理；它公开承认虚构并带训诫性。"},{"word":"mythology","ipa":"/mɪˈθɒlədʒi/","tag":"the whole set","definition":"A collection of myths or the study of them; myth is one story, mythology is the set or the discipline.","definitionCN":"神话的汇集或对神话的研究；myth 是一则故事，mythology 是整套或这门学科。"},{"word":"mythos","ipa":"/ˈmɪθɒs/","tag":"borrowed term","definition":"The Greek word itself, used in English for the underlying pattern of a myth or for a group's shared story-world.","definitionCN":"希腊原词本身，在英语中用来指一则神话的底层模式，或一个群体共享的故事世界。"}]},{"heading":"NEAR MEANING","entries":[{"word":"misconception","ipa":"/ˌmɪskənˈsepʃn/","tag":"wrong idea","definition":"A mistaken understanding held by many people; it names the error plainly, without the story image that myth carries.","definitionCN":"许多人持有的错误理解；它直白地指错误，不含 myth 所带的故事意象。"},{"word":"falsehood","ipa":"/ˈfɔːlshʊd/","tag":"untrue statement","definition":"A statement that is not true, whether or not anyone believes it; myth adds wide acceptance.","definitionCN":"不真实的陈述，无论是否有人相信；myth 则多了「被广泛接受」这一层。"},{"word":"fabrication","ipa":"/ˌfæbrɪˈkeɪʃn/","tag":"deliberate invention","definition":"Something invented on purpose to deceive; it implies intent, while a myth's false sense often implies only repetition.","definitionCN":"为欺骗而故意编造的东西；它含故意，而 myth 的谬见义常只含反复流传。"},{"word":"belief","ipa":"/bɪˈliːf/","tag":"what is held true","definition":"The state of holding something as true; a myth may become a belief, but belief itself says nothing about stories.","definitionCN":"把某事当作真的状态；神话可以变成信念，但 belief 本身与故事无关。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real Greek elements, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的希腊语成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek mythos 'a thing said': a myth is literally something a community keeps saying aloud.","cn":"希腊 mythos「被说出的东西」：神话字面上就是一个群体不断大声讲的东西。"},{"en":"The family runs myth, mythic, mythical, mythology, mythologist, mythologize.","cn":"同族词包括 myth、mythic、mythical、mythology、mythologist、mythologize。"},{"en":"Fixed phrases mark both senses: ancient myth, Greek myth, and the myth of progress.","cn":"固定搭配标出两层意思：古老神话、希腊神话，以及关于进步的虚妄信念。"},{"en":"Greek kept mythos and logos as a pair: story against reasoned account.","cn":"希腊语把 mythos 与 logos 当作一对：故事对理性论证。"},{"en":"The academic use says myth concerns origins, so a myth can be true to its tellers and still be a myth.","cn":"学术用法说神话关注起源，因此一则神话对讲述者可以为真，却仍然是神话。"}],"abstract":[{"en":"Picture a sentence that gets heavier each time it is repeated, until it can no longer be lifted.","cn":"想象一句话每被重复一次就重一点，最后重得抬不起来。"},{"en":"Picture a portrait repainted by every visitor until the original face is gone.","cn":"想象一幅肖像被每位来客添改，最后原来的脸已经不见了。"},{"en":"Picture a map drawn from memory and then used as if it were the ground itself.","cn":"想象一张凭记忆画的地图，后来被当成地面本身来使用。"}]},"examples":[{"en":"The myth explains why the river turns salt where it meets the sea.","cn":"这则神话解释了那条河为什么在人海处变咸。"},{"en":"It is a myth that older workers cannot learn new software.","cn":"「年长的员工学不会新软件」是一种谬见。"},{"en":"The film turns a minor local trader into a myth of resistance.","cn":"这部影片把一个微不足道的本地商人塑造成了抵抗的传奇。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「myth（音近『秘思』）」——被反复讲述、越传越神秘的那套说法 → 神话；也指广为相信的谬见","word":"myth"},"root":"希腊 mythos「言语、讲述、故事」，先作学术借词进入晚期拉丁，再经法语进入英语；mythos 更早来源不确定，无已证实的印欧语来源。","sensesIntro":{"en":"Eight senses follow one gesture: something gets told and retold, and the retelling first makes a sacred story, then a whole story-world, then a false belief, an invented person, an excuse, a genre label, a legendary figure, and finally a society's account of itself.","cn":"八个义项沿一个动作展开：某件事被讲了又讲，这反复讲述先造出神圣故事，再造出整套故事世界，随后造出谬见、虚构人物、托词、文类标签、传奇人物，最后造出一个社会对自身的解释。"},"semanticMap":{"core":{"en":"CORE IMAGE: a tale retold around a fire until the retelling stands where the fact used to be.","cn":"核心意象：火堆旁被一遍遍重讲的故事，讲到后来，重讲本身站在了事实原来的位置上。"},"chain":["TOLD TALE","WHOLE STORY WORLD","REPEATED FALSEHOOD","INVENTED BEING","GENRE LABEL","SOCIAL SELF-STORY"],"branches":[{"senses":"01 · 02","en":"THE TALE AND THE SET: one story first, then the whole body of stories a culture keeps.","cn":"故事与整套：先是一则故事，再是一个文化保存的整批故事。"},{"senses":"03 · 05","en":"REPETITION WITHOUT PROOF: an often-repeated tale turns into a false belief, and an invented account becomes an excuse.","cn":"无凭据的重复：被反复讲述的故事变成错误信念，编出来的说法变成托词。"},{"senses":"04 · 07","en":"PERSONS MADE OF TALK: a thing or a person can be wholly produced by the telling.","cn":"由讲述造出的人与物：一件东西或一个人可以完全由讲述生产出来。"},{"senses":"06","en":"A NEUTRAL GENRE LABEL: scholars keep the noun but drop the judgement that a myth must be false.","cn":"中性的文类标签：学者保留这个名词，却去掉「神话必然虚假」这一判断。"},{"senses":"08","en":"THE STORY A SOCIETY TELLS ITSELF: the tale now explains the tellers to themselves.","cn":"社会讲给自己的故事：故事此时用来向讲述者解释他们自身。"}]},"affixes":{"intro":{"en":"Myth is a bare Greek noun in English, but it builds a large family through suffixes that name studies, qualities, persons and processes.","cn":"myth 在英语里是一个光裸的希腊名词，但它通过指学科、性质、人物与过程的后缀建起一个很大的词族。"},"latinIntro":{"en":"No Latin family stands behind myth. Latin took mythos only as a Greek loanword, so there is no inherited Latin cognate to list.","cn":"myth 背后没有拉丁词族。拉丁语只把 mythos 当作希腊借词吸收，因此没有可列的拉丁固有同族词。"},"items":[{"word":"myth","structure":"Greek mythos (noun, 'word, story')","meaning":"a told story","meaningCN":"被讲述的故事","example":"The myth survived in three versions.","exampleCN":"这则神话以三个版本留存下来。"},{"word":"-ic","structure":"-ikos (Greek adjective suffix)","meaning":"having the nature of","meaningCN":"具有……性质的","example":"The suffix turns the noun into a quality word.","exampleCN":"这个后缀把名词变成性质词。"},{"word":"-ical","structure":"-ikos via Latin -icus (adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The longer suffix sounds more formal.","exampleCN":"较长的后缀听起来更正式。"},{"word":"mythic","structure":"myth + -ic","meaning":"of myth-like stature","meaningCN":"具有神话般地位的","example":"The striker became a mythic name.","exampleCN":"这位前锋成了神话般的名字。"},{"word":"mythical","structure":"myth + -ical","meaning":"existing only in story","meaningCN":"只存在于故事中的","example":"A mythical harbour appears on the old chart.","exampleCN":"旧海图上出现一个神话中的港口。"},{"word":"mythology","structure":"myth + -ology (study, collection)","meaning":"the set of myths or their study","meaningCN":"神话的整体或对神话的研究","example":"She teaches the mythology of northern Europe.","exampleCN":"她教授北欧神话。"},{"word":"mythologist","structure":"mythology + -ist (person suffix)","meaning":"one who studies myths","meaningCN":"研究神话的人","example":"The mythologist catalogued the variants.","exampleCN":"这位神话学者编目了各种异文。"},{"word":"mythologize","structure":"mythology + -ize (verb suffix)","meaning":"to make into myth","meaningCN":"使成为神话","example":"Memoirists mythologize their own youth.","exampleCN":"回忆录作者会把自己的青年时代写成神话。"},{"word":"mythologization","structure":"mythologize + -ation (action noun)","meaning":"the act of myth-making","meaningCN":"神话化的行为","example":"The mythologization of the founder began at his funeral.","exampleCN":"对创始人的神话化从他的葬礼就开始了。"},{"word":"mythmaker","structure":"myth + maker (English compound)","meaning":"one who invents myths or false beliefs","meaningCN":"编造神话或谬见的人","example":"Every age has its mythmakers.","exampleCN":"每个时代都有自己的神话制造者。"}],"latinEntries":[]}},{"word":"belief","ipa_uk":"/bɪˈliːf/","ipa_us":"/bɪˈliːf/","definition_zh":"相信；信念；信仰；看法；信任；置信程度","definition_en":"the state of accepting something as true, or a thing so accepted","core_image":"一个人在没有扶手的地方迈出一步，脚下并没有看见实地，却先把重量交了出去","scene":"病房外的走廊上，家属握着旧照片，说病人一定会醒过来。Her belief that her brother would recover never faltered.","sceneCN":"这里 belief 指「对某件事将会如此的坚定相信」（第 1 个义项：把某件尚未实现的事当作真）；句意为她相信弟弟一定会康复，这份相信从未动摇。可辨识物件：走廊、旧照片、长椅、病房门。","pos":[{"tag":"n.","zh":"相信；信念；信仰；看法；信任"}],"collocations":[{"phrase":"belief in","zh":"对……的相信"},{"phrase":"religious belief","zh":"宗教信仰"},{"phrase":"hold a belief","zh":"持有某种信念"},{"phrase":"contrary to popular belief","zh":"与普遍看法相反"},{"phrase":"belief system","zh":"信念体系"},{"phrase":"strengthen a belief","zh":"加强某种信念"}],"forms":[{"label":"单数","form":"belief"},{"label":"复数","form":"beliefs"},{"label":"动词（相信）","form":"believe"},{"label":"名词（信徒）","form":"believer"},{"label":"形容词（可信的）","form":"believable"},{"label":"形容词（难以置信的）","form":"unbelievable"}],"derivatives":[{"word":"believe","pos":"v.","zh":"基础动词 believe（古英语 beliefan）先于名词存在，名词由「相信」这一动作偏移为「所相信的内容」"},{"word":"believer","pos":"n.","zh":"believe + -er（施事后缀）→ 由「相信」偏移为「持信仰的人」"},{"word":"believable","pos":"adj.","zh":"believe + -able（可……的形容词后缀）→ 偏移为「值得相信的」"},{"word":"unbelievable","pos":"adj.","zh":"un-（否定前缀）+ believable → 偏移为「难以相信的」"},{"word":"disbelief","pos":"n.","zh":"dis-（反义前缀）+ belief → 由「相信」偏移为「拒绝相信」"},{"word":"unbelief","pos":"n.","zh":"un-（否定前缀）+ belief → 多用于宗教语境，指「没有信仰」"},{"word":"believing","pos":"adj.","zh":"believe + -ing（现在分词作定语）→ 偏移为「相信的、信教的」"}],"senses":[{"no":"01","title":"Acceptance that something is true","titleCN":"相信某事为真","definition":"the state of accepting a statement or fact as true, even without proof","definitionCN":"把某个说法或事实当作真的接受下来，即使没有证据","example":"Her belief that her brother would recover never faltered.","exampleCN":"她相信弟弟会康复，这份信念从未动摇。","why":"the Old English verb meant to hold something dear, and holding it dear grew into holding it true.","whyCN":"古英语的动词原指「把某物看得珍贵」，看重它便逐渐变成「把它当作真的」。"},{"no":"02","title":"Religious faith","titleCN":"宗教信仰","definition":"trust in a divine power or acceptance of a religion's teachings","definitionCN":"对神明的信赖，或对某宗教教义的接受","example":"Her belief gave her something to hold on to during the trial.","exampleCN":"她的信仰在艰难时期给了她可以抓住的东西。","why":"the same holding-true applies to what cannot be checked at all, and religion became the clearest home for that sense.","whyCN":"同样一种「当作真的」，用在完全无法验证的事情上，宗教便成了这一义项最清楚的归宿。"},{"no":"03","title":"An opinion","titleCN":"看法，观点","definition":"a view or judgement held about something, weaker than full certainty","definitionCN":"对某事持有的看法或判断，确定性弱于完全确信","example":"It is my belief that the plan will cost more than promised.","exampleCN":"我认为这个计划的花费会超过承诺的数字。","why":"an opinion is the same holding of something as true, only with the holder openly allowing that others may think otherwise.","whyCN":"看法是同一种把某事当作真的持有，只是持有者公开承认别人可能有别的想法。"},{"no":"04","title":"Trust in a person","titleCN":"对人的信任","definition":"confidence that a person is honest or reliable","definitionCN":"相信某人诚实或可靠","example":"The team's belief in its captain kept it together.","exampleCN":"队伍对队长的信任让它没有散掉。","why":"trusting a person is the same gesture as accepting a fact: you put weight on something you cannot fully verify.","whyCN":"信任一个人与接受一个事实是同一个动作：你把重量放在无法完全验证的东西上。"},{"no":"05","title":"Belief in effectiveness","titleCN":"对某种做法有效的相信","definition":"confidence that a method, remedy or policy will work","definitionCN":"相信某种方法、疗法或政策会奏效","example":"Public belief in the vaccine rose after the trial results.","exampleCN":"试验结果公布后，公众对这种疫苗的信任上升了。","why":"confidence that a remedy works is the same trust, only placed in a method rather than in a person.","whyCN":"相信某种疗法有效是同一种信任，只是把信任放在方法上，而不是放在人身上。"},{"no":"06","title":"An article of a creed","titleCN":"信条中的一条","definition":"one item in a set of doctrines that a group formally holds","definitionCN":"某群体正式持有的一套教义中的一条","example":"The council debated whether the belief could be stated more simply.","exampleCN":"会议争论这条信条能否表述得更简单。","why":"a doctrine is a belief that a community has fixed in words and handed on as one item on a list.","whyCN":"信条是一个群体用文字固定下来、并作为清单上一条传递下去的信念。"},{"no":"07","title":"Degree of confidence","titleCN":"置信程度（统计学、心理学用语）","definition":"the strength assigned to a judgement, as in a prior belief in a statistical model","definitionCN":"赋予某个判断的强度，如统计模型中的先验信念","example":"The model updates its prior belief after each new observation.","exampleCN":"模型在每次新观测后更新它的先验信念。","why":"once belief is treated as a quantity, it can be strong or weak, and technical fields measure it instead of debating it.","whyCN":"一旦信念被当作一个量，它就有强弱之分，技术领域于是去测量它，而不是去争论它。"},{"no":"08","title":"Acceptance without evidence","titleCN":"无证据的相信","definition":"the act of accepting something as true although the evidence is absent or contrary","definitionCN":"在证据缺失或相反的情况下仍把某事当作真的","example":"His belief in the rumour survived every correction.","exampleCN":"他对那则谣言的相信挺过了每一次更正。","why":"the word can name the act of holding on precisely when proof is missing, which is why it is often used with a critical tone.","whyCN":"这个词可以专指在证据缺席时仍然坚持，因此常带批评口吻。"}],"etymology":{"intro":{"en":"Belief is native English: an Old English noun formed beside the verb beliefan 'to believe', from a Germanic root meaning 'to hold dear, to approve'. It has no Latin relatives. Dates are approximate.","cn":"belief 是英语本族词：古英语名词，与动词 beliefan「相信」并生，来自意为「看重、认可」的日耳曼词根。它没有拉丁同族词。年代均为约数。"},"items":[{"era":"GERMANIC ROOT","en":"The Germanic stock *ga-laubon is generally thought to mean 'to hold dear, to approve of', built on a root *laub- 'pleasing, permitted'.","cn":"一般认为，日耳曼词根 *ga-laubon 意为「看重、认可」，由 *laub-「令人喜欢的、被允许的」构成。"},{"era":"OLD ENGLISH BELIEFAN","en":"Old English beliefan meant 'to believe, to trust'. The noun belief was formed beside it, so the noun and the verb grew up together.","cn":"古英语 beliefan 意为「相信、信赖」，名词 belief 与之并生，名词与动词是一起长成的。"},{"era":"MEANING OF HOLDING DEAR","en":"The step from 'to hold dear' to 'to hold true' is a general path in many languages: what one values, one also credits.","cn":"从「看重」到「当作真的」是许多语言共有的路径：人看重的东西，也就愿意采信。"},{"era":"MIDDLE ENGLISH","en":"Middle English kept both the religious sense and the everyday sense of an opinion, and the plural beliefs came to name a set of held tenets.","cn":"中古英语同时保留宗教义与「看法」的日常义，复数 beliefs 逐渐指所持的一套信条。"},{"era":"MODERN TECHNICAL USE","en":"From the twentieth century psychology and statistics used belief for a measurable degree of confidence, giving the word a technical sense alongside the ordinary one.","cn":"二十世纪起，心理学与统计学用 belief 指可测量的置信程度，使这个词在日常义之外又多了一个技术义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact form and meaning of the earliest Germanic root are reconstructed, not attested, and the precise date of the noun's first appearance is not recorded.","cn":"来源不确定：最早日耳曼词根的确切形式与含义属重构形式，并无书证；名词首见的确切年代也没有记录。"}]},"similar":{"note":{"en":"Group one separates belief from the words for knowledge, trust and opinion that sit next to it; group two holds the words for the contents of belief.","cn":"第一组把 belief 与旁边的知识、信任、意见类词分开；第二组是表示信念内容的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"believe","ipa":"/bɪˈliːv/","tag":"the verb","definition":"The verb 'to accept as true'; belief is the noun for the state or the content, so one believes and holds a belief.","definitionCN":"动词「相信」；belief 是状态或内容的名词，因此动词说「相信」，名词说「信念」。"},{"word":"beloved","ipa":"/bɪˈlʌvɪd/","tag":"held dear","definition":"From the same stock in its older sense 'held dear'; it keeps the affection meaning that belief long ago left behind.","definitionCN":"同出这个词根，保留其旧义「被珍爱的」；它守住了 belief 早已丢开的那层情感义。"},{"word":"unbeliever","ipa":"/ˌʌnbɪˈliːvə/","tag":"person without faith","definition":"A person who does not accept a given faith; it names the person, where belief names the state.","definitionCN":"不接受某种信仰的人；它指人，而 belief 指状态。"},{"word":"beliefs","ipa":"/bɪˈliːfs/","tag":"the plural set","definition":"The plural usually means a set of tenets held together, not several separate acts of believing.","definitionCN":"复数通常指放在一起的一套信条，而不是几次彼此分离的相信行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"faith","ipa":"/feɪθ/","tag":"trust without proof","definition":"Trust that goes beyond evidence, especially in religion; belief can be a plain opinion, faith cannot.","definitionCN":"超出证据的信任，尤指宗教上的；belief 可以只是普通看法，faith 不能。"},{"word":"conviction","ipa":"/kənˈvɪkʃn/","tag":"firmly held","definition":"A belief held with great firmness and defended actively; it is stronger and more combative than belief.","definitionCN":"坚定持有并主动捍卫的信念；比 belief 更强、更好斗。"},{"word":"opinion","ipa":"/əˈpɪnjən/","tag":"a view","definition":"A judgement openly presented as one view among others; belief can be quietly held and need not be argued.","definitionCN":"作为诸种看法之一公开提出的判断；belief 可以默默持有，不必争辩。"},{"word":"assumption","ipa":"/əˈsʌmpʃn/","tag":"taken for granted","definition":"Something accepted as true in order to reason onward, often without notice; belief is more conscious.","definitionCN":"为了继续推理而当作真的东西，常未被察觉；belief 更有意识。"},{"word":"knowledge","ipa":"/ˈnɒlɪdʒ/","tag":"justified","definition":"Accepted as true with adequate grounds; belief needs no such grounds, which is the classic contrast between the two.","definitionCN":"在有充分依据的情况下被当作真；belief 不需要这种依据，这正是二者的经典对照。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Germanic root, the real verb pair and real fixed phrases, not invented rhymes.","cn":"正常联想：真实的日耳曼词根、真实的动名配对与真实固定搭配，而非编造的顺口溜。"},"normal":[{"en":"The older sense was 'to hold dear': what you hold dear, you also hold true.","cn":"旧义是「看重」：你看重的东西，你也会当作真的。"},{"en":"Verb and noun are a pair: believe something, hold a belief.","cn":"动词与名词成对：动词说「相信某事」，名词说「持有一个信念」。"},{"en":"The family runs believe, believer, believable, unbelievable, disbelief, unbelief.","cn":"同族词包括 believe、believer、believable、unbelievable、disbelief、unbelief。"},{"en":"Fixed phrases mark the range: belief in, religious belief, contrary to popular belief.","cn":"固定搭配标出范围：对……的相信、宗教信仰、与普遍看法相反。"},{"en":"The phrase belief system names the whole set, which is the next word in this batch.","cn":"belief system 这一说法指整套信念，正是本批的下一个词。"}],"abstract":[{"en":"Picture a foot stepping onto a bridge whose planks cannot be seen through the fog.","cn":"想象一只脚踩上桥板，而雾里根本看不见那些桥板。"},{"en":"Picture a hand holding a coin it has never weighed, simply because it was handed over.","cn":"想象一只手攥着一枚从未称过的硬币，只因为它是别人递过来的。"},{"en":"Picture a lamp left burning in a room where nobody has checked the oil.","cn":"想象一盏灯在没人检查过油的房间里一直亮着。"}]},"examples":[{"en":"Belief that the earth was flat once needed no defence.","cn":"曾经，相信大地是平的这件事根本不需要辩护。"},{"en":"His belief in the method grew as each trial succeeded.","cn":"随着每次试验成功，他对这套方法的信心增强了。"},{"en":"Contrary to popular belief, the desert is full of life at night.","cn":"与普遍看法相反，沙漠在夜里充满生命。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「be（成为）+ lieve（音近 leave 留下）」——把某句话留在心里、当成真的 → 相信、信念","word":"belief"},"root":"古英语 beliefan「相信」及其并生名词 belief，来自日耳曼 *ga-laubon「看重、认可」，由 *laub-「令人喜欢的、被允许的」构成；无拉丁同族词。","sensesIntro":{"en":"Eight senses follow one gesture: weight is placed on something not fully seen, and that gesture is then applied to facts, to gods, to opinions, to people, to methods, to creed items, to measurable confidence, and finally to holding on when evidence is missing.","cn":"八个义项沿一个动作展开：把重量放在没有完全看见的东西上，这个动作再依次用于事实、神明、看法、他人、方法、信条、可测量的置信，最后用于证据缺席时仍然坚持。"},"semanticMap":{"core":{"en":"CORE IMAGE: a step taken onto ground that the eye has not yet confirmed.","cn":"核心意象：在眼睛还没确认的地方先迈出一步。"},"chain":["HOLD AS TRUE","HOLD AS SACRED","HOLD AS OPINION","HOLD AS TRUST","HOLD AS DOCTRINE","HOLD WITHOUT PROOF"],"branches":[{"senses":"01 · 08","en":"THE BASIC GESTURE: accepting as true, whether evidence is thin or wholly absent.","cn":"基本动作：把某事当作真的，不论证据薄弱还是完全没有。"},{"senses":"02 · 06","en":"THE SACRED SET: faith in the divine, and the single articles that a community states formally.","cn":"神圣的一套：对神的信仰，以及群体正式表述的一条条信条。"},{"senses":"03","en":"THE SOFTER FORM: an opinion is the same holding, only with less weight claimed for it.","cn":"较软的形式：看法是同一种持有，只是声明的分量更轻。"},{"senses":"04 · 05","en":"TRUST PLACED IN OTHERS: confidence in a person or in a method that has not yet proved itself.","cn":"放在他处的信任：对一个人、或对尚未证明自身的方法的信心。"},{"senses":"07","en":"MEASURED CONFIDENCE: technical fields turn the state into a quantity with strength and weakness.","cn":"可测量的置信：技术领域把这种状态变成一个可强可弱的量。"}]},"affixes":{"intro":{"en":"Belief is a native noun, so its parts are Germanic rather than Latin: a prefix that once meant 'together', a root meaning 'pleasing', and a noun ending.","cn":"belief 是本族名词，其成分属日耳曼语而非拉丁语：一个曾表「共同」的前缀、一个意为「令人喜欢」的词根，以及一个名词词尾。"},"latinIntro":{"en":"There is no Latin family behind belief. Latin expressed the same idea with credere and fides, which are different roots and not relatives of the English word.","cn":"belief 背后没有拉丁词族。拉丁语用 credere 与 fides 表达同一概念，那是另外的词根，并非这个英语词的同族。"},"items":[{"word":"be-","structure":"Germanic *bi- (prefix, 'about, around')","meaning":"around, thoroughly","meaningCN":"围绕、彻底","example":"The prefix intensifies the root rather than reversing it.","exampleCN":"这个前缀强化词根，而不是反转词根。"},{"word":"lief","structure":"Old English leof (adjective, 'dear, pleasing')","meaning":"dear, welcome","meaningCN":"珍贵的、受欢迎的","example":"The old adjective survives in the word beloved.","exampleCN":"这个古老形容词还活在 beloved 一词里。"},{"word":"-f","structure":"Old English noun ending of belief","meaning":"turns the state into a noun","meaningCN":"把状态固定为名词","example":"The ending marks a thing rather than an action.","exampleCN":"这个词尾标记的是一件事，而不是一个动作。"},{"word":"believe","structure":"be- + lief (verb form)","meaning":"to hold as true","meaningCN":"把……当作真的","example":"Few believed the forecast at first.","exampleCN":"起初很少有人相信那则预报。"},{"word":"believer","structure":"believe + -er (person suffix)","meaning":"one who believes","meaningCN":"相信的人","example":"Believers gathered before dawn.","exampleCN":"信众在天亮前聚集。"},{"word":"believable","structure":"believe + -able (can be)","meaning":"able to be believed","meaningCN":"可信的","example":"The excuse sounded barely believable.","exampleCN":"那个借口听起来几乎不可信。"},{"word":"unbelievable","structure":"un- + believable","meaning":"too strange to believe","meaningCN":"难以相信的","example":"The heat was unbelievable.","exampleCN":"那股热浪令人难以置信。"},{"word":"disbelief","structure":"dis- + belief","meaning":"refusal to believe","meaningCN":"拒绝相信","example":"She stared in disbelief at the empty shelf.","exampleCN":"她不敢相信地盯着空货架。"},{"word":"unbelief","structure":"un- + belief","meaning":"absence of religious faith","meaningCN":"没有宗教信仰","example":"The sermon addressed unbelief directly.","exampleCN":"这篇布道直接谈到不信的问题。"}],"latinEntries":[]}},{"word":"belief system","ipa_uk":"/bɪˈliːf ˈsɪstəm/","ipa_us":"/bɪˈliːf ˈsɪstəm/","definition_zh":"信念体系；一套相互关联的信仰与看法；宗教教义体系；意识形态","definition_en":"an organized set of beliefs that a person or a group holds and uses to explain the world","core_image":"屋架的柱、梁与斜撑互相扣住，抽掉其中一根，整片屋顶就塌下来","scene":"展柜里并排放着经卷、念珠和祭祀陶器，说明牌把它们归在同一套观念之下。The exhibit shows how a belief system organizes ritual, law and daily habit.","sceneCN":"这里 belief system 指「一套彼此关联、共同支撑世界观的信念」（第 1 个义项：成体系的信念集合）；句意为展览说明这套信念体系如何组织仪式、律法与日常习惯。可辨识物件：经卷、念珠、陶器、说明牌。","pos":[{"tag":"n.","zh":"信念体系；成套的信仰与看法（可数，复数 belief systems）"}],"collocations":[{"phrase":"shared belief system","zh":"共同持有的信念体系"},{"phrase":"religious belief system","zh":"宗教信念体系"},{"phrase":"dominant belief system","zh":"占主导地位的信念体系"},{"phrase":"challenge a belief system","zh":"挑战一套信念体系"},{"phrase":"coherent belief system","zh":"自洽的信念体系"},{"phrase":"the belief system of a culture","zh":"一个文化的信念体系"}],"forms":[{"label":"单数","form":"belief system"},{"label":"复数","form":"belief systems"},{"label":"定语用法","form":"belief-system"},{"label":"前项名词（信念）","form":"belief"},{"label":"后项名词（体系）","form":"system"},{"label":"同义学术说法","form":"value system"}],"derivatives":[{"word":"belief","pos":"n.","zh":"基础词 belief 作复合词前项，由「相信」这一状态偏移为「体系中的一条信念」"},{"word":"system","pos":"n.","zh":"希腊 systema「组合起来的整体」进入英语，作复合词后项，偏移为「有组织的整体」"},{"word":"systemic","pos":"adj.","zh":"system + -ic（形容词后缀）→ 由「体系」偏移为「波及整个体系的」"},{"word":"systematic","pos":"adj.","zh":"system + -atic（形容词后缀）→ 偏移为「有步骤、成方法的」"},{"word":"systematize","pos":"v.","zh":"systematic + -ize（动词后缀）→ 偏移为「把零散材料整理成体系」"},{"word":"systematization","pos":"n.","zh":"systematize + -ation（动作名词后缀）→ 偏移为「体系化的过程」"},{"word":"believer","pos":"n.","zh":"believe + -er（施事后缀）→ 偏移为「在这套体系中信从的人」"}],"senses":[{"no":"01","title":"An organized set of beliefs","titleCN":"成套关联的信念集合","definition":"a set of beliefs that are linked together so that each supports the others","definitionCN":"一组彼此连接、互相支撑的信念","example":"The exhibit shows how a belief system organizes ritual, law and daily habit.","exampleCN":"展览展示了一套信念体系如何组织仪式、律法与日常习惯。","why":"system names a whole whose parts hold each other up, so a belief system is not a list of opinions but a structure.","whyCN":"system 指各部分互相撑持的整体，因此信念体系不是一张意见清单，而是一个结构。"},{"no":"02","title":"A religion's doctrinal whole","titleCN":"宗教的教义整体","definition":"the complete body of doctrine, story and practice that a religion holds together","definitionCN":"某一宗教把教义、故事与实践合在一起的整体","example":"Missionaries had to learn the whole belief system before preaching.","exampleCN":"传教士必须先弄懂整套教义体系才能布道。","why":"religions are the clearest case of beliefs that must fit together, so the phrase is used most often for them.","whyCN":"宗教是最典型的「信念必须彼此契合」的例子，因此这个说法最常用于宗教。"},{"no":"03","title":"A culture's shared worldview","titleCN":"一个文化共享的世界观","definition":"the common assumptions a culture makes about what exists and what matters","definitionCN":"一个文化对「存在什么、什么重要」的共同预设","example":"Rice farming shaped a belief system centred on water and cooperation.","exampleCN":"水稻种植塑造了一套以水与合作为中心的信念体系。","why":"a culture's assumptions cluster the same way, so anthropologists borrowed the phrase for the whole cluster.","whyCN":"一个文化的预设也以同样的方式聚成簇，人类学者便把这一说法借去指整个簇。"},{"no":"04","title":"A personal framework","titleCN":"个人解释生活的框架","definition":"an individual's settled set of assumptions used to interpret events","definitionCN":"个人用来解释事件的一套稳定预设","example":"Trauma can shake a person's entire belief system.","exampleCN":"创伤可能动摇一个人整套的信念框架。","why":"the phrase applies to one mind as easily as to a group, because coherence is needed at either scale.","whyCN":"这个说法同样适用于单个头脑，因为无论规模大小都需要自洽。"},{"no":"05","title":"A political ideology","titleCN":"意识形态","definition":"a connected set of political beliefs that justifies a programme of action","definitionCN":"为一套行动纲领提供理由的、彼此关联的政治信念","example":"The party's belief system left little room for compromise.","exampleCN":"这个政党的意识形态几乎没有留下妥协的余地。","why":"ideologies are belief systems built for action, so the phrase often carries a critical edge in politics.","whyCN":"意识形态是为行动而建的信念体系，因此这个说法在政治语境中常带批评意味。"},{"no":"06","title":"A philosophical system","titleCN":"哲学体系","definition":"a reasoned structure of principles that hangs together as a whole","definitionCN":"由原理构成、整体自洽的论证结构","example":"His belief system rested on three unproved premises.","exampleCN":"他的哲学体系建立在三个未加证明的前提上。","why":"philosophy builds exactly the kind of interlocking whole that the word system names.","whyCN":"哲学所建的正是 system 一词所指的那种互相扣合的整体。"},{"no":"07","title":"A coping framework","titleCN":"心理应对的解释框架","definition":"the assumptions a person uses to make painful events bearable and meaningful","definitionCN":"个人用来让痛苦事件变得可承受、有意义的预设","example":"Her belief system gave the illness a place she could live with.","exampleCN":"她的信念框架给这场病安排了一个她能与之共处的位置。","why":"psychology found that people need a coherent frame to endure loss, and reused the phrase for that frame.","whyCN":"心理学发现人需要一个自洽的框架才能承受失去，便把这个说法再次用于那个框架。"},{"no":"08","title":"An institutionalized creed","titleCN":"制度化的信条与实践","definition":"beliefs that an institution has fixed in texts, offices and routines","definitionCN":"被机构固定进文本、职位与常规之中的信念","example":"The school's belief system survives in its entrance ceremony.","exampleCN":"这所学校的信念体系在它的入学典礼中留存下来。","why":"once beliefs are written into offices and calendars, the system outlives the believers who hold it.","whyCN":"一旦信念被写进职位与日程，这套体系就比持有它的个人活得更久。"}],"etymology":{"intro":{"en":"Belief system joins a native English noun for held truth to a Greek noun for an organized whole; the compound itself is a modern term of anthropology and psychology. Dates are approximate.","cn":"belief system 把指「所信之事」的英语本族名词，与指「有组织整体」的希腊名词组合起来；这个复合词本身是近代人类学与心理学的术语。年代均为约数。"},"items":[{"era":"OLD ENGLISH BELIEF","en":"Belief came from the Germanic stock *ga-laubon 'to hold dear, approve', which developed the sense 'to hold as true'.","cn":"belief 来自日耳曼词根 *ga-laubon「看重、认可」，由此发展出「当作真的」这一意思。"},{"era":"GREEK SYSTEMA","en":"Greek systema meant 'an organized whole', generally thought to be built on syn- 'together' plus histanai 'to cause to stand'.","cn":"希腊 systema 意为「有组织的整体」，一般认为由 syn-「一起」加 histanai「使站立」构成。"},{"era":"LATE LATIN SYSTEMA","en":"Late Latin took systema as a Greek loanword, and from it came the learned vocabulary of system in the modern languages.","cn":"晚期拉丁把 systema 作为希腊借词吸收，近代诸语言的 system 学术词汇由此而来。"},{"era":"FRENCH SYSTÈME","en":"French système carried the word into general use, where it came to mean any set of parts working as a whole.","cn":"法语 système 把这个词带入一般用法，指任何共同运作的一套部分。"},{"era":"MODERN COMPOUND","en":"Belief system appears as a compound in nineteenth and twentieth century writing on religion, anthropology and psychology.","cn":"belief system 作为复合词出现在十九与二十世纪关于宗教、人类学与心理学的著作中。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first use of the exact compound is not recorded, and the pre-Greek origin of systema is unsettled, so any earlier form proposed for it is a reconstructed form.","cn":"来源不确定：这个复合词的确切首见没有记录，systema 在希腊语之前的来源亦无定论，因此为它提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the compound from the single items and neighbouring set-words it is confused with; group two holds larger social and personal frames of reference.","cn":"第一组把这一复合词与单个信念及邻近的「成套」词分开；第二组是更大的社会与个人参照框架。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"belief","ipa":"/bɪˈliːf/","tag":"one item","definition":"A single thing held as true; a belief system is the structure that holds many such items together.","definitionCN":"单件被当作真的事；信念体系是把许多这样的条目撑在一起的结构。"},{"word":"value system","ipa":"/ˈvæljuː ˈsɪstəm/","tag":"what ought to be","definition":"A ranked set of moral preferences about right and wrong; it judges conduct, while a belief system explains what is.","definitionCN":"关于对错的一套有排序的道德偏好；它评判行为，而信念体系说明「是什么」。"},{"word":"worldview","ipa":"/ˈwɜːldvjuː/","tag":"how the world looks","definition":"A person's overall picture of reality; it is close to belief system but stresses the picture rather than the linked propositions.","definitionCN":"个人对现实的整体图景；与信念体系接近，但侧重图景本身，而非彼此连接的命题。"},{"word":"creed","ipa":"/kriːd/","tag":"stated formulas","definition":"The beliefs of a religion set out in formal statements; it is the written core of a belief system, not the whole living system.","definitionCN":"以正式条文列出的宗教信念；它是信念体系成文的核心，而不是整套活的体系。"},{"word":"doctrine","ipa":"/ˈdɒktrɪn/","tag":"taught body","definition":"A body of teaching handed down by an authority; it is what is taught, while a belief system is what is actually held.","definitionCN":"由权威传下的一套教导；它指被教的内容，而信念体系指实际被持有的内容。"}]},{"heading":"NEAR MEANING","entries":[{"word":"ideology","ipa":"/ˌaɪdiˈɒlədʒi/","tag":"political frame","definition":"A system of ideas that justifies political action; it is a belief system recruited for power.","definitionCN":"为政治行动提供理由的观念体系；可以说是被权力征用的信念体系。"},{"word":"religion","ipa":"/rɪˈlɪdʒən/","tag":"institution","definition":"An organized community, practice and doctrine; it includes a belief system but also buildings, offices and calendars.","definitionCN":"有组织的群体、实践与教义；它包含信念体系，也包含建筑、职位与日程。"},{"word":"philosophy","ipa":"/fəˈlɒsəfi/","tag":"reasoned inquiry","definition":"A reasoned account of existence and knowledge; it values argument, where a belief system may rest on authority.","definitionCN":"对存在与知识的论证性说明；它看重论证，而信念体系可能依靠权威。"},{"word":"mindset","ipa":"/ˈmaɪndset/","tag":"habitual attitude","definition":"A settled mental attitude that shapes how problems are met; it is looser and less codified than a belief system.","definitionCN":"塑造应对问题方式的稳定心态；比信念体系更松散，也更少成文。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves of the compound, its real set-phrases and its real relatives.","cn":"正常联想：这个复合词两个真实的部分、它真实的固定说法与真实同族词。"},"normal":[{"en":"belief + system: held truths plus a structure that makes them hold each other up.","cn":"belief 加 system：被持有的真，加上一个使它们彼此撑持的结构。"},{"en":"Greek syn- 'together' + histanai 'to stand' gives system: parts made to stand together.","cn":"希腊 syn-「一起」加 histanai「站立」构成 system：被使之一同站住的部分。"},{"en":"The family runs belief, believe, believer, system, systemic, systematic, systematize.","cn":"同族词包括 belief、believe、believer、system、systemic、systematic、systematize。"},{"en":"Fixed phrases mark the range: shared belief system, religious belief system, dominant belief system.","cn":"固定搭配标出范围：共同信念体系、宗教信念体系、主导信念体系。"},{"en":"Remove one supporting beam and the roof falls: that is what coherence means here.","cn":"抽掉一根承重的梁，屋顶就塌：这就是此处「自洽」的意思。"}],"abstract":[{"en":"Picture a roof held up by beams that lean on one another rather than on the ground.","cn":"想象一片屋顶由互相倚靠的梁撑起，而不是撑在地上。"},{"en":"Picture a key ring where every key opens a door that leads to the next key.","cn":"想象一串钥匙，每一把打开的门后都放着下一把。"},{"en":"Picture a sentence in which no word can be removed without the grammar collapsing.","cn":"想象一句话，去掉任何一个词，语法就整个垮掉。"}]},"examples":[{"en":"A belief system that cannot absorb contradiction eventually splits.","cn":"无法容纳矛盾的信念体系最终会分裂。"},{"en":"Fieldwork requires understanding a belief system from the inside.","cn":"田野调查要求从内部理解一套信念体系。"},{"en":"Two belief systems can share a practice and still disagree about why it matters.","cn":"两套信念体系可以共享同一种做法，却对它的意义意见相反。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「belief（信念）+ system（系统）」——许多条信念按系统扣在一起 → 信念体系","word":"belief system"},"root":"belief（古英语「看重、相信」，日耳曼 *ga-laubon）+ system（希腊 systema「有组织的整体」，一般认为由 syn-「一起」+ histanai「使站立」构成）。复合词为近代人类学与心理学术语。","sensesIntro":{"en":"Eight senses follow one structure: separate beliefs are made to lean on one another, and the same structure is then found in a religion, a culture, one mind, a political programme, a philosophy, a coping frame and finally in written institutions.","cn":"八个义项沿一个结构展开：零散的信念被安排成互相倚靠，随后这同一结构依次出现在宗教、文化、单个头脑、政治纲领、哲学、应对框架，最后落在成文的制度里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a frame whose parts hold each other up, so that removing one brings the whole down.","cn":"核心意象：一个各部分互相撑持的框架，抽掉一处，整体就塌。"},"chain":["LINKED BELIEFS","RELIGIOUS WHOLE","SHARED WORLDVIEW","PERSONAL FRAME","POLITICAL CREED","WRITTEN INSTITUTION"],"branches":[{"senses":"01","en":"THE STRUCTURE ITSELF: beliefs become a system only when each one supports the others.","cn":"结构本身：只有当每条信念都支撑其他信念时，它们才成为体系。"},{"senses":"02 · 06","en":"THE GREAT WHOLE: religion and philosophy are the two oldest examples of beliefs fitted into one coherent frame.","cn":"宏大的整体：宗教与哲学是把信念装进一个自洽框架的最古老两个例子。"},{"senses":"03 · 08","en":"FROM SHARED TO WRITTEN: a culture's assumptions become an institution's fixed texts and routines.","cn":"从共享到成文：文化的预设变成机构固定的文本与常规。"},{"senses":"04 · 07","en":"ONE MIND: the same frame is needed to interpret events and to bear what cannot be changed.","cn":"单个头脑：解释事件与承受不可改变之事，需要的是同一个框架。"},{"senses":"05","en":"BELIEFS RECRUITED FOR ACTION: an ideology is a system organized around a programme rather than around explanation.","cn":"为行动征用的信念：意识形态是围绕纲领、而非围绕解释组织起来的体系。"}]},"affixes":{"intro":{"en":"The compound can be read as two complete words, and each half brings its own family of suffixes and prefixes.","cn":"这个复合词可按两个完整的词读出，每一半都带来自己的后缀与前缀词族。"},"latinIntro":{"en":"Only the second half has a Latin trace: systema was a Greek noun borrowed into Late Latin, and it brought syn- and the root of histanai with it.","cn":"只有后半部分留有拉丁痕迹：systema 是借入晚期拉丁的希腊名词，并随之带来 syn- 与 histanai 的词根。"},"items":[{"word":"belief","structure":"be- + lief (Old English noun)","meaning":"a thing held as true","meaningCN":"被当作真的事","example":"The belief took root over generations.","exampleCN":"这条信念历经数代才扎下根。"},{"word":"-er","structure":"Old English agent suffix","meaning":"one who does","meaningCN":"做某事的人","example":"Believers met in the courtyard.","exampleCN":"信从者在院子里聚会。"},{"word":"system","structure":"Greek systema (organized whole)","meaning":"parts standing together","meaningCN":"一同站住的一套部分","example":"The system failed at its weakest joint.","exampleCN":"这套体系在最弱的一处接合点失效了。"},{"word":"syn-","structure":"Greek prefix syn- 'together'","meaning":"together, with","meaningCN":"一起、共同","example":"The prefix marks union rather than separation.","exampleCN":"这个前缀标记的是联合，而非分离。"},{"word":"histanai","structure":"Greek verb, 'to cause to stand'","meaning":"to set upright","meaningCN":"使站立、使立起","example":"The root supplies the standing in system.","exampleCN":"这个词根提供了 system 中「站立」的意思。"},{"word":"systemic","structure":"system + -ic","meaning":"affecting the whole","meaningCN":"影响整体的","example":"The failure was systemic, not local.","exampleCN":"这次失效是整体性的，不是局部的。"},{"word":"systematic","structure":"system + -atic","meaning":"done in ordered steps","meaningCN":"按步骤进行的","example":"They made a systematic survey of the district.","exampleCN":"他们对这个区做了系统的调查。"},{"word":"systematize","structure":"systematic + -ize","meaning":"to arrange into a system","meaningCN":"整理成体系","example":"He systematized the scattered notes.","exampleCN":"他把零散的笔记整理成了体系。"},{"word":"systematization","structure":"systematize + -ation","meaning":"the act of organizing into a system","meaningCN":"体系化的行为","example":"The systematization took two years.","exampleCN":"体系化的工作花了两年。"},{"word":"-ize","structure":"Greek -izein via Latin -izare (verb suffix)","meaning":"to make or become","meaningCN":"使成为","example":"The suffix turns a state into an action.","exampleCN":"这个后缀把状态变成动作。"}],"latinEntries":[{"word":"systema","structure":"systema, systematis (n., third declension, Greek loanword)","meaning":"an organized whole","meaningCN":"有组织的整体"},{"word":"systematicus","structure":"systematicus (adj., Late Latin, from Greek systematismos)","meaning":"arranged as a whole","meaningCN":"按整体安排的"}]}},{"word":"cultural identity","ipa_uk":"/ˈkʌltʃərəl aɪˈdentəti/","ipa_us":"/ˈkʌltʃərəl aɪˈdentəti/","definition_zh":"文化认同；文化身份；对自身文化归属的认知；群体共享的文化特征","definition_en":"the sense of belonging to a culture, or the set of traits by which a group recognizes itself","core_image":"一只旧木箱里放着祖母的头巾、家乡的香料袋和一张迁出地的车票","scene":"节日集市上，摊主一边包粽子一边教孩子说家乡话，围裙上绣着老屋的纹样。Language and food anchor her cultural identity.","sceneCN":"这里 cultural identity 指「对自身所属文化的归属感与自我认知」（第 1 个义项：个人确认自己属于某种文化）；句意为语言与食物把她的文化认同牢牢锚住。可辨识物件：粽子、围裙刺绣、集市摊位、孩子。","pos":[{"tag":"n.","zh":"文化认同；文化身份（多作不可数，指多重认同时可说 cultural identities）"}],"collocations":[{"phrase":"sense of cultural identity","zh":"文化认同感"},{"phrase":"cultural identity crisis","zh":"文化认同危机"},{"phrase":"preserve cultural identity","zh":"保持文化认同"},{"phrase":"national cultural identity","zh":"国家层面的文化认同"},{"phrase":"cultural identity formation","zh":"文化认同的形成"},{"phrase":"shared cultural identity","zh":"共享的文化认同"}],"forms":[{"label":"通常形式（不可数）","form":"cultural identity"},{"label":"复数（指多重认同）","form":"cultural identities"},{"label":"相关形容词（文化的）","form":"cultural"},{"label":"相关名词（文化）","form":"culture"},{"label":"相关名词（身份）","form":"identity"},{"label":"同义说法","form":"sense of cultural belonging"}],"derivatives":[{"word":"culture","pos":"n.","zh":"拉丁 cultura「耕作、培育」→ 由「耕作」偏移为「一个群体共同培育的生活方式」"},{"word":"cultural","pos":"adj.","zh":"culture + -al（形容词后缀）→ 偏移为「属于某种生活方式的」"},{"word":"culturally","pos":"adv.","zh":"cultural + -ly（副词后缀）→ 偏移为「从文化角度看」"},{"word":"identity","pos":"n.","zh":"晚期拉丁 identitas（来自 idem「同一」）→ 偏移为「使某物保持为自身的那种同一性」"},{"word":"identify","pos":"v.","zh":"identity + -ify（动词后缀）→ 偏移为「确认某物与自身同一」"},{"word":"identification","pos":"n.","zh":"identify + -ation（动作名词后缀）→ 偏移为「确认同一的过程」"},{"word":"identical","pos":"adj.","zh":"拉丁 idem「同一」+ -ical（形容词后缀）→ 偏移为「完全相同的」"}],"senses":[{"no":"01","title":"A sense of belonging","titleCN":"对某种文化的归属感","definition":"the feeling that one belongs to a particular culture and is formed by it","definitionCN":"感到自己属于某一文化、并由该文化塑造","example":"Language and food anchor her cultural identity.","exampleCN":"语言与食物把她的文化认同牢牢锚住。","why":"identity rests on the Latin word for 'the same', so the phrase names the culture one feels oneself to be the same as.","whyCN":"identity 出自拉丁语「同一」，因此这个说法指一个人感到自己与之相同的那种文化。"},{"no":"02","title":"A group's shared traits","titleCN":"群体共享的文化特征","definition":"the traits, habits and symbols by which a group is recognized and recognizes itself","definitionCN":"一个群体借以被辨认、也借以辨认自身的特征、习惯与符号","example":"The festival keeps a cultural identity that the schools no longer teach.","exampleCN":"这个节日保存着学校已不再教授的那套文化特征。","why":"the same phrase shifts from the feeling to the marks that produce the feeling.","whyCN":"同一个说法从「感受」转到「产生这种感受的标志」。"},{"no":"03","title":"Self-recognition of membership","titleCN":"对自身文化成员身份的确认","definition":"the act of placing oneself within a culture and accepting its claims on one","definitionCN":"把自己放进某一文化、并接受该文化对自己的要求","example":"Her cultural identity became explicit only after she moved abroad.","exampleCN":"她的文化认同直到移居国外后才变得明确。","why":"belonging is felt before it is chosen, but the phrase also names the act of consciously accepting a culture as one's own.","whyCN":"归属先于选择被感受到，但这个说法也指有意识地把某种文化接受为自己的那一动作。"},{"no":"04","title":"Identity retained in migration","titleCN":"移民与少数群体保留的认同","definition":"a culture kept alive by a community living inside a different majority culture","definitionCN":"一个生活在别的多数文化之中的群体所保持的文化","example":"The second generation negotiates a cultural identity between two homes.","exampleCN":"第二代人在两个家之间协商自己的文化认同。","why":"identity becomes visible when it is under pressure, which is why migration writing uses the phrase so often.","whyCN":"认同在受压时才显形，因此移民写作如此频繁地使用这个说法。"},{"no":"05","title":"National or ethnic identity","titleCN":"国家或民族层面的文化认同","definition":"a culture's identity treated as a collective possession of a nation or people","definitionCN":"被当作一个民族或人民集体财产的文化认同","example":"Museums were built to give the new state a cultural identity.","exampleCN":"博物馆的建立是为了给这个新国家一种文化认同。","why":"when a state needs legitimacy, it converts a culture into an identity it can represent.","whyCN":"当一个国家需要合法性时，它会把文化转成一种可以代表自己的认同。"},{"no":"06","title":"A political claim","titleCN":"作为政治诉求的文化认同","definition":"the assertion of a group's culture as a basis for rights, recognition or autonomy","definitionCN":"以某群体的文化作为权利、承认或自治依据的主张","example":"The movement turned cultural identity into a demand for legal status.","exampleCN":"这场运动把文化认同变成了对法律地位的要求。","why":"recognition is a political good, so identity can be argued for rather than merely felt.","whyCN":"被承认是一种政治利益，因此认同可以被论证，而不只是被感受。"},{"no":"07","title":"Markers and expressions","titleCN":"文化认同的表达形式","definition":"the visible carriers of identity, such as language, food, dress, music and ritual","definitionCN":"承载认同的可感形式，如语言、食物、服饰、音乐与仪式","example":"Dress became the most visible marker of cultural identity in the town.","exampleCN":"在小镇上，服饰成了文化认同最显眼的标记。","why":"identity needs something material to be seen in, and the phrase extends to those carriers.","whyCN":"认同需要有可感之物才能被看见，这个说法便扩展到那些承载物上。"},{"no":"08","title":"Identity rebuilt under globalization","titleCN":"全球化下重构的文化认同","definition":"a culture's self-definition revised while global flows mix and dilute local practice","definitionCN":"在全球流动混合并稀释本地实践时被重新定义的文化自我","example":"Young designers rebuild a cultural identity out of fragments their grandparents knew whole.","exampleCN":"年轻设计师用祖辈曾完整掌握的碎片重建一种文化认同。","why":"when practices are no longer inherited whole, identity becomes something assembled rather than received.","whyCN":"当实践不再被完整继承，认同就变成拼装出来的东西，而不是被接受下来的东西。"}],"etymology":{"intro":{"en":"Cultural identity joins cultura, Latin for cultivation, to identitas, Late Latin for sameness; the phrase itself is a twentieth-century term of sociology and cultural studies. Dates are approximate.","cn":"cultural identity 把拉丁语指「耕作培育」的 cultura 与晚期拉丁语指「同一」的 identitas 组合起来；这个说法本身是二十世纪社会学与文化研究的术语。年代均为约数。"},"items":[{"era":"LATIN CULTURA","en":"Cultura came from colere 'to till, to cultivate, to honour', and named the tending of land before it named the tending of minds.","cn":"cultura 来自 colere「耕作、培育、敬奉」，先指对土地的照料，后指对心智的培育。"},{"era":"LATIN IDEM","en":"Identitas was formed in Late Latin on idem 'the same', so identity originally named the state of being the same through change.","cn":"identitas 在晚期拉丁语中依 idem「同一」构成，因此 identity 原指在变化中保持同一的状态。"},{"era":"ENGLISH CULTURE","en":"English culture widened from the tending of crops to the whole way of life of a people during the nineteenth century.","cn":"英语 culture 在十九世纪从照料作物扩展为一个民族的整体生活方式。"},{"era":"MODERN IDENTITY","en":"Identity moved from logic and law into psychology, where it named a person's lasting sense of self.","cn":"identity 从逻辑学与法学进入心理学，指一个人持久的自我感。"},{"era":"TWENTIETH-CENTURY PHRASE","en":"Cultural identity was taken up in sociology and cultural studies to name the culture a group or person identifies with.","cn":"cultural identity 被社会学与文化研究采用，指一个群体或个人认同于其间的文化。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first use of the phrase is not recorded, and the deeper origin of colere is unsettled, so any earlier root proposed for it is a reconstructed form.","cn":"来源不确定：这个说法的确切首见没有记录，colere 的更早来源亦无定论，因此为它提出的更早词根均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the phrase from the neighbouring kinds of identity; group two holds words for heritage and belonging that are close in use but not in meaning.","cn":"第一组把这一说法与邻近的各种身份概念分开；第二组是用法相近、含义不同的「传承与归属」类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"social identity","ipa":"/ˈsəʊʃl aɪˈdentəti/","tag":"role-based","definition":"The self defined by roles and groups such as profession or class; cultural identity is the slice defined by shared culture.","definitionCN":"由职业、阶层等角色与群体定义的自我；文化认同是其中由共享文化定义的那一部分。"},{"word":"ethnic identity","ipa":"/ˈeθnɪk aɪˈdentəti/","tag":"ancestry-based","definition":"Identity grounded in ancestry and descent; cultural identity can be acquired, which ethnic identity usually claims not to be.","definitionCN":"以血统与世系为依据的认同；文化认同可以习得，而族群认同通常声称不可习得。"},{"word":"national identity","ipa":"/ˈnæʃnəl aɪˈdentəti/","tag":"state-based","definition":"Identity tied to a state and its citizenship; it is a political frame that may contain several cultures.","definitionCN":"与国家及其公民身份相连的认同；它是政治框架，可能包含多种文化。"},{"word":"identity crisis","ipa":"/aɪˈdentəti ˈkraɪsɪs/","tag":"the breakdown","definition":"A period when a person or group cannot tell what it is; it names the failure of identity, not the identity itself.","definitionCN":"个人或群体说不清自己是谁的一段时期；它指认同的失效，而非认同本身。"},{"word":"cultural assimilation","ipa":"/ˈkʌltʃərəl əˌsɪməˈleɪʃn/","tag":"the giving up","definition":"The process by which a minority culture is absorbed into a majority one; it is the opposite outcome from retaining an identity, not a synonym for it.","definitionCN":"少数文化被多数文化吸收的过程；它是保留认同的反面结果，而不是其同义说法。"}]},{"heading":"NEAR MEANING","entries":[{"word":"heritage","ipa":"/ˈherɪtɪdʒ/","tag":"what is handed down","definition":"The practices and objects inherited from earlier generations; heritage is the material passed on, identity is the self built from it.","definitionCN":"从前辈继承的实践与物件；遗产是被传下的材料，认同是由此建成的自我。"},{"word":"belonging","ipa":"/bɪˈlɒŋɪŋ/","tag":"the feeling","definition":"The sense of being accepted in a place or group; it is the emotional side of identity without the cultural content.","definitionCN":"在一个地方或群体中被接纳的感觉；它是认同的情感面，不含文化内容。"},{"word":"tradition","ipa":"/trəˈdɪʃn/","tag":"handed-on practice","definition":"Practices passed down over time; a tradition can outlive the identity that produced it, and vice versa.","definitionCN":"随时间传下的实践；传统可以比产生它的认同活得更久，反之亦然。"},{"word":"sense of self","ipa":"/sens əv self/","tag":"personal core","definition":"A person's private feeling of being a continuous individual; culture may shape it without defining it.","definitionCN":"个人对自身是连续个体的私下感受；文化可以塑造它，却未必定义它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two Latin roots, the real collocations and the real relatives, not invented rhymes.","cn":"正常联想：两个真实的拉丁词根、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"cultura 'tending' + identitas 'sameness': the culture you tend and feel the same as.","cn":"cultura「照料」+ identitas「同一」：你照料、并觉得自己与之相同的那个文化。"},{"en":"idem is the Latin word for 'the same', and it also gives identical and identify.","cn":"idem 是拉丁语「同一」，它也衍生出 identical 与 identify。"},{"en":"Fixed phrases mark the range: sense of cultural identity, cultural identity crisis, national cultural identity.","cn":"固定搭配标出范围：文化认同感、文化认同危机、国家层面的文化认同。"},{"en":"The family runs culture, cultural, culturally, identity, identify, identification, identical.","cn":"同族词包括 culture、cultural、culturally、identity、identify、identification、identical。"},{"en":"Colere meant to till the soil; culture later tilled people instead.","cn":"colere 原指耕土；后来 culture 耕的是人。"}],"abstract":[{"en":"Picture a box holding a headscarf, a spice bag and a ticket to a place no longer lived in.","cn":"想象一只箱子，里面放着一条头巾、一袋香料和一张通往已不再居住之地的车票。"},{"en":"Picture a mirror that shows a face made of several faces laid over one another.","cn":"想象一面镜子，照出一张由好几张脸叠成的脸。"},{"en":"Picture a recipe written in two hands, one old and one still learning.","cn":"想象一份食谱由两只手写成，一只苍老，一只仍在学。"}]},"examples":[{"en":"Schools can support cultural identity without turning it into a costume show.","cn":"学校可以支持文化认同，而不把它变成一场服装表演。"},{"en":"For refugees, cultural identity often survives in recipes and songs.","cn":"对难民而言，文化认同常常活在食谱与歌谣里。"},{"en":"The census made cultural identity a category that had to be counted.","cn":"人口普查把文化认同变成了一个必须被计数的类别。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「cultural（文化的）+ identity（身份）」——由文化给出的那张身份 → 文化认同","word":"cultural identity"},"root":"cultural（拉丁 cultura「耕作、培育」，来自 colere）+ identity（晚期拉丁 identitas，来自 idem「同一」）；短语为二十世纪社会学与文化研究用语。","sensesIntro":{"en":"Eight senses follow one movement: a person feels the same as a culture, that sameness is then located in group traits, in conscious membership, in migration, in a nation, in a political claim, in visible markers, and finally in a self that must be rebuilt.","cn":"八个义项沿一个走向展开：一个人感到自己与某种文化相同，这份「相同」随后落在群体特征、自觉的成员身份、迁徙处境、国家、政治主张、可感标记，最后落在一个必须重建的自我上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person recognizing a face in a mirror and finding it is also the face of a group.","cn":"核心意象：一个人从镜中认出自己的脸，又发现这张脸也是一个群体的脸。"},"chain":["FEELING OF BELONGING","GROUP TRAITS","CONSCIOUS MEMBERSHIP","MIGRANT RETENTION","NATIONAL CLAIM","REBUILT SELF"],"branches":[{"senses":"01 · 02","en":"FEELING AND ITS MARKS: the belonging is felt first, then located in traits that can be seen and named.","cn":"感受与其标记：先感到归属，再把归属安放在看得见、说得出的特征上。"},{"senses":"03","en":"THE ACT OF PLACING ONESELF: membership becomes explicit when a person consciously accepts a culture's claims.","cn":"把自己放进去的动作：当一个人有意识地接受某文化的要求，成员身份就变得明确。"},{"senses":"04","en":"IDENTITY UNDER PRESSURE: a minority culture discovers its identity precisely where it must defend it.","cn":"受压的认同：少数群体恰恰在必须捍卫之处发现自己的认同。"},{"senses":"05 · 06","en":"IDENTITY AS A POLITICAL OBJECT: a nation adopts a culture, and a movement turns it into a demand.","cn":"作为政治对象的认同：国家采纳一种文化，运动则把它变成一项诉求。"},{"senses":"07 · 08","en":"CARRIERS AND RECONSTRUCTION: language, food and dress carry the identity, and when inheritance breaks, the same carriers are reassembled.","cn":"载体与重建：语言、食物与服饰承载认同；当继承断裂，同样的载体又被重新拼装。"}]},"affixes":{"intro":{"en":"Both halves are Latin-derived and highly productive: cultura builds the culture family, identitas builds the identity family.","cn":"两半都源自拉丁语且构词力很强：cultura 建起 culture 词族，identitas 建起 identity 词族。"},"latinIntro":{"en":"Latin supplies both halves: cultura from colere 'to till', and identitas from idem 'the same'.","cn":"两半都来自拉丁语：cultura 出自 colere「耕作」，identitas 出自 idem「同一」。"},"items":[{"word":"colere","structure":"colere, colui, cultum (Latin verb, third conjugation)","meaning":"to till, cultivate, honour","meaningCN":"耕作；培育；敬奉","example":"The verb first described work on land.","exampleCN":"这个动词最初描述的是土地上的劳作。"},{"word":"cultura","structure":"cultura (Latin noun, first declension)","meaning":"tending, cultivation","meaningCN":"照料；培育","example":"Cultura named the care given to a field.","exampleCN":"cultura 指给予田地的照料。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"The suffix makes an adjective of culture.","exampleCN":"这个后缀把 culture 变成形容词。"},{"word":"-ally","structure":"-al + -ly (adverb ending)","meaning":"in that manner","meaningCN":"以那种方式","example":"Culturally, the two towns differ sharply.","exampleCN":"在文化上，这两个小镇差别很大。"},{"word":"idem","structure":"idem (Latin pronoun, 'the same')","meaning":"the same","meaningCN":"同一的","example":"The root supplies the sameness in identity.","exampleCN":"这个词根提供了 identity 中的「同一」。"},{"word":"identitas","structure":"identitas, identitatis (f., Late Latin, third declension)","meaning":"sameness, identity","meaningCN":"同一；身份","example":"Late Latin formed the noun on idem.","exampleCN":"晚期拉丁语依 idem 构成了这个名词。"},{"word":"identity","structure":"identitas via French identité","meaning":"the state of being oneself","meaningCN":"保持为自身的状态","example":"Identity survives changes of place.","exampleCN":"身份能挺过地点的改变。"},{"word":"-ify","structure":"-ificare (Latin verb-forming suffix)","meaning":"to make","meaningCN":"使成为","example":"The suffix turns identity into a verb.","exampleCN":"这个后缀把 identity 变成动词。"},{"word":"-ation","structure":"-atio (Latin action-noun suffix)","meaning":"the act or process","meaningCN":"动作或过程","example":"The suffix names the process of identifying.","exampleCN":"这个后缀指确认同一的过程。"},{"word":"-ical","structure":"-icalis (Latin adjective suffix)","meaning":"having the character of","meaningCN":"具有……性质的","example":"Identical means exactly the same.","exampleCN":"identical 意为完全相同。"}],"latinEntries":[{"word":"cultura","structure":"cultura, culturae (f., first declension)","meaning":"tending, cultivation, care","meaningCN":"照料；耕作；培育"},{"word":"colere","structure":"colere, colui, cultum (verb, third conjugation)","meaning":"to till, cultivate","meaningCN":"耕作；培育"},{"word":"identitas","structure":"identitas, identitatis (f., third declension, Late Latin)","meaning":"sameness","meaningCN":"同一性"},{"word":"idem","structure":"idem (pronoun/adjective, 'the same')","meaning":"the same","meaningCN":"同一个"}]}},{"word":"urbanization","ipa_uk":"/ˌɜːbənaɪˈzeɪʃn/","ipa_us":"/ˌɜːrbənəˈzeɪʃn/","definition_zh":"城市化；城市人口比重上升；城市地域扩张；城市化程度；过度城市化","definition_en":"the process by which a population becomes concentrated in cities and the countryside takes on city forms","core_image":"稻田中央竖起塔吊，水泥路把田埂切成整齐的方块，远处楼群一层层往上长","scene":"稻田中央新起了一片楼群，水泥路把田埂切成方块，远处塔吊还在转。Rapid urbanization swallowed the rice fields within a decade.","sceneCN":"这里 urbanization 指「人口与土地持续向城市集中的过程」（第 1 个义项：乡村人口转为城市人口）；句意为快速城市化在十年内吞掉了这片稻田。可辨识物件：塔吊、楼群、水泥路、田埂。","pos":[{"tag":"n.","zh":"城市化；城市化过程与程度（不可数）"}],"collocations":[{"phrase":"rapid urbanization","zh":"快速城市化"},{"phrase":"urbanization rate","zh":"城市化率"},{"phrase":"unplanned urbanization","zh":"无序城市化"},{"phrase":"the urbanization process","zh":"城市化进程"},{"phrase":"urbanization of rural areas","zh":"乡村地区的城市化"},{"phrase":"counter-urbanization","zh":"逆城市化"}],"forms":[{"label":"不可数名词","form":"urbanization"},{"label":"英式拼写变体","form":"urbanisation"},{"label":"动词（使城市化）","form":"urbanize"},{"label":"形容词（已城市化的）","form":"urbanized"},{"label":"形容词（城市的）","form":"urban"},{"label":"名词（城市主义）","form":"urbanism"},{"label":"名词（城市居民）","form":"urbanite"}],"derivatives":[{"word":"urban","pos":"adj.","zh":"拉丁 urbanus「城市的」→ 由「城市」偏移为「属于城市或城市生活的」"},{"word":"urbanize","pos":"v.","zh":"urban + -ize（动词后缀）→ 偏移为「使某地转为城市形态」"},{"word":"urbanized","pos":"adj.","zh":"urbanize + -ed（形容词化过去分词）→ 偏移为「已经城市化的」"},{"word":"urbanism","pos":"n.","zh":"urban + -ism（名词后缀，表体系或倾向）→ 偏移为「城市生活方式与规划理念」"},{"word":"urbanist","pos":"n.","zh":"urbanism + -ist（人名词后缀）→ 偏移为「研究或倡导城市生活的人」"},{"word":"suburban","pos":"adj.","zh":"sub-（在下、近旁）+ urban → 偏移为「城郊的」"},{"word":"exurban","pos":"adj.","zh":"ex-（向外）+ urban → 偏移为「城市远郊的」"}],"senses":[{"no":"01","title":"Movement of people into cities","titleCN":"人口向城市集中","definition":"the process by which people move from the countryside into cities and stay there","definitionCN":"人们从乡村迁入城市并留下来的过程","example":"Rapid urbanization swallowed the rice fields within a decade.","exampleCN":"快速城市化在十年内吞掉了这片稻田。","why":"urbanus meant 'of the city', and -ization names a process, so the word is literally the process of becoming city-like.","whyCN":"urbanus 意为「城市的」，-ization 表过程，因此这个词字面上就是「变成城市样子的过程」。"},{"no":"02","title":"A rising urban share","titleCN":"城市人口比重的上升","definition":"the increase in the proportion of a population that lives in urban areas","definitionCN":"生活在城市地区的人口所占比例的上升","example":"The census recorded urbanization of four points in five years.","exampleCN":"普查记录到五年内城市化率上升了四个百分点。","why":"the process can be measured, so the noun also names the number that measures it.","whyCN":"这个过程可以被测量，因此这个名词也指测量它的那个数字。"},{"no":"03","title":"Expansion of built-up land","titleCN":"城市地域的扩张","definition":"the spread of built-up land into formerly rural areas","definitionCN":"建成区向原本的乡村地区铺开","example":"Urbanization pushed the edge of the city three kilometres outward.","exampleCN":"城市化把城市边缘向外推了三公里。","why":"people need land as well as jobs, so population movement shows up on the map as spreading construction.","whyCN":"人既需要工作也需要土地，因此人口迁移在地图上就表现为建筑的铺开。"},{"no":"04","title":"Diffusion of city ways","titleCN":"城市生活方式的扩散","definition":"the spread of city habits, services and expectations into non-city places","definitionCN":"城市习惯、服务与期待扩散到非城市地区","example":"Urbanization reached the village as piped water and evening buses.","exampleCN":"城市化以自来水和夜班公交的形式抵达了这个村庄。","why":"the word covers ways of living, not only where people sleep, so it can arrive without a skyline.","whyCN":"这个词覆盖的是生活方式，而不只是人睡在哪里，因此它可以在没有高楼天际线时也抵达。"},{"no":"05","title":"Degree of urbanization","titleCN":"城市化程度","definition":"how far a place has already become urban, expressed as a level or share","definitionCN":"某地已经城市化的程度，用水平或比例表示","example":"Their level of urbanization differs sharply from the coastal provinces.","exampleCN":"他们的城市化程度与沿海省份差别很大。","why":"a process that can be measured can also be reported as a level, so the noun doubles as a score.","whyCN":"一个可测量的过程也可以被报告为一个水平，因此这个名词兼作分数。"},{"no":"06","title":"Planning and infrastructure drive","titleCN":"规划与基础设施推动的城市化","definition":"deliberate state building of roads, housing and services that turns land urban","definitionCN":"国家有计划地修建道路、住房与服务，使土地转为城市","example":"State-led urbanization built the new district before anyone moved in.","exampleCN":"国家主导的城市化在有人入住之前就把新区建好了。","why":"the process need not wait for migrants; when the state builds first, the noun names a policy, not a migration.","whyCN":"这个过程不必等移民到来；当国家先建设时，这个名词指的就是政策，而不是迁移。"},{"no":"07","title":"Social change accompanying cities","titleCN":"城市带来的社会变迁","definition":"the social shifts that follow dense living, such as smaller households and new work patterns","definitionCN":"密集居住带来的社会变化，如家庭规模缩小与工作方式改变","example":"Urbanization loosened the hold of the extended family.","exampleCN":"城市化松动了大家庭的约束。","why":"dense living changes who shares a roof and how work is timed, which is why the social effects take the same name.","whyCN":"密集居住改变了谁与谁同住一个屋顶、工作如何排时间，因此这些社会后果也用同一个名字。"},{"no":"08","title":"Over-urbanization","titleCN":"过度城市化","definition":"city growth faster than the jobs, housing and services that could absorb it","definitionCN":"城市增长快于就业、住房与服务的吸纳能力","example":"Over-urbanization left rows of unfinished towers beside open drains.","exampleCN":"过度城市化在露天排水沟旁留下了一排排未完工的塔楼。","why":"the same process, pushed past the point that jobs and services can absorb, becomes a warning rather than a goal.","whyCN":"同一个过程一旦被推过就业与服务能吸纳的界限，就从一个目标变成一个警示。"}],"etymology":{"intro":{"en":"Urbanization joins urbanus, Latin for 'of the city', to the suffix -ization, which names a process; the word belongs to nineteenth-century social description. Dates are approximate.","cn":"urbanization 把拉丁语指「城市的」的 urbanus 与表过程的 -ization 组合起来；这个词属于十九世纪的社会描述。年代均为约数。"},"items":[{"era":"LATIN URBS","en":"Urbs meant 'city', especially Rome. Its deeper origin is uncertain; no accepted Indo-European source has been shown.","cn":"urbs 意为「城市」，尤指罗马城。其更早来源不确定，没有已获公认的印欧语来源。"},{"era":"LATIN URBANUS","en":"Urbanus meant 'of the city', and carried a secondary tone of city manners, from which English gets both urban and urbane.","cn":"urbanus 意为「城市的」，并带有「城市举止」的第二层色彩，英语的 urban 与 urbane 都由此而来。"},{"era":"FRENCH URBANISATION","en":"French urbanisation was coined in the nineteenth century to describe the growth of city populations.","cn":"法语 urbanisation 在十九世纪被造出来，用以描述城市人口的增长。"},{"era":"GREEK -IZEIN","en":"The suffix -ization goes back to Greek -izein 'to make, to act' through Latin -izare and French -isation; it names a process rather than a state.","cn":"后缀 -ization 经拉丁 -izare 与法语 -isation 上溯至希腊 -izein「使、做」；它指过程，而非状态。"},{"era":"ENGLISH TERM","en":"English adopted urbanization in the late nineteenth century, first as a description of population movement and later as a policy field.","cn":"英语在十九世纪末采纳 urbanization，最初描述人口流动，后来成为一个政策领域。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of urbs before Latin is unsettled and the exact first English citation is unrecorded, so any earlier form proposed for urbs is a reconstructed form.","cn":"来源不确定：urbs 在拉丁语之前的来源无定论，英语首见的确切书证也没有记录，因此为 urbs 提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates urbanization from its own family, which shares the same stem; group two holds related demographic and economic processes.","cn":"第一组把 urbanization 与同一词干的自家人分开；第二组是相关的人口与经济过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"urbanism","ipa":"/ˈɜːbənɪzəm/","tag":"way of life","definition":"The mode of life and set of values associated with cities; urbanization is the process of arriving at that mode.","definitionCN":"与城市相连的生活方式与价值取向；城市化是抵达这种方式的进程。"},{"word":"urbanize","ipa":"/ˈɜːbənaɪz/","tag":"the verb","definition":"To make an area or a population urban; it is the acting verb behind the process noun.","definitionCN":"使某地或某人群城市化；它是这个进程名词背后的动词。"},{"word":"urban","ipa":"/ˈɜːbən/","tag":"the adjective","definition":"Of or in a city; the adjective describes a state, the noun describes movement into that state.","definitionCN":"城市中的、城市的；形容词描述状态，名词描述进入该状态的过程。"},{"word":"suburbanization","ipa":"/səˌbɜːbənaɪˈzeɪʃn/","tag":"outward growth","definition":"The movement of city populations to the outskirts; it is a later phase of the same process, not a synonym.","definitionCN":"城市人口向郊区移动；它是同一进程的较晚阶段，并非同义词。"},{"word":"counter-urbanization","ipa":"/ˈkaʊntər ˌɜːbənaɪˈzeɪʃn/","tag":"the reverse","definition":"Movement away from large cities toward smaller settlements; it reverses the direction, so it cannot replace the term.","definitionCN":"从大城市迁往较小居民点的移动；它反转了方向，因此不能替代本条术语。"}]},{"heading":"NEAR MEANING","entries":[{"word":"migration","ipa":"/maɪˈɡreɪʃn/","tag":"any move","definition":"Movement from one place to another; it is the general term, of which the rural-to-city flow is one case.","definitionCN":"从一个地方到另一个地方的移动；它是一般术语，乡到城的流动只是其中一种情形。"},{"word":"industrialization","ipa":"/ɪnˌdʌstriəlaɪˈzeɪʃn/","tag":"factory growth","definition":"The growth of factory production; it often drives urbanization but is a different process with a different measure.","definitionCN":"工厂生产的增长；它常推动城市化，却是另一种进程，衡量方式也不同。"},{"word":"modernization","ipa":"/ˌmɒdənaɪˈzeɪʃn/","tag":"broad change","definition":"Broad adoption of modern technology and institutions; it is wider than urbanization and need not be urban.","definitionCN":"对现代技术与制度的广泛采纳；比城市化更宽，也不必是城市的。"},{"word":"urban sprawl","ipa":"/ˈɜːbən sprɔːl/","tag":"low-density spread","definition":"The spread of low-density development over open land; it is one physical result of urbanization, often criticized.","definitionCN":"低密度开发在空地上的铺开；它是城市化的一个物理结果，常受批评。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, the real process suffix and the real relatives, not invented rhymes.","cn":"正常联想：真实的拉丁词干、真实的过程后缀与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"urbs 'city' gives urban; add -ization and you get the process of becoming city.","cn":"urbs「城市」给出 urban；加上 -ization 就得到「变成城市」的过程。"},{"en":"The family runs urban, urbanize, urbanized, urbanism, urbanist, suburban, exurban.","cn":"同族词包括 urban、urbanize、urbanized、urbanism、urbanist、suburban、exurban。"},{"en":"Fixed phrases mark the measured sense: urbanization rate, rapid urbanization, counter-urbanization.","cn":"固定搭配标出可测量的义项：城市化率、快速城市化、逆城市化。"},{"en":"Latin had both urbanus 'of the city' and the sharper urbane 'city-mannered'; English kept the pair.","cn":"拉丁语既有 urbanus「城市的」，也有更偏「城市举止」的 urbane；英语把这一对都留下了。"},{"en":"-ization names a process in hundreds of words: industrialization, modernization, globalization.","cn":"-ization 在成百上千的词里表过程：工业化、现代化、全球化。"}],"abstract":[{"en":"Picture a field where the footpaths are slowly replaced by kerbs without anyone deciding the whole plan.","cn":"想象一片田野，小路一点点被路缘石取代，却没有人定下整体规划。"},{"en":"Picture a village clock that begins to keep city hours.","cn":"想象一只村庄的钟，开始按城市的时间走。"},{"en":"Picture a map where the grey area grows like water spreading across paper.","cn":"想象一张地图，灰色区域像水在纸上蔓延一样扩大。"}]},"examples":[{"en":"Urbanization without sewers turns a growing city into a health crisis.","cn":"没有下水道的城市化会把一座成长中的城市变成一场卫生危机。"},{"en":"The country reached an urbanization rate of seventy per cent in one generation.","cn":"这个国家在一代人之内达到七成的城市化率。"},{"en":"Historians treat nineteenth-century urbanization as a rupture in everyday life.","cn":"历史学者把十九世纪的城市化视为日常生活的一次断裂。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「urban（城市的）+ ize（使成为）+ ation（过程）」——使地方变成城市的那一过程 → 城市化","word":"urbanization"},"root":"拉丁 urbs「城市」→ urbanus「城市的」+ -ization（经拉丁 -izare、希腊 -izein「使、做」，表过程）；urbs 更早来源不确定。英语 urbanization 为十九世纪社会描述用语。","sensesIntro":{"en":"Eight senses follow one process: people move into cities, the measured share rises, built land spreads, city habits diffuse, a level is reached, the state builds, society reshapes, and growth can outrun what supports it.","cn":"八个义项沿一个进程展开：人迁入城市，可测的比重上升，建成区铺开，城市习惯扩散，达到某个水平，国家主动建设，社会随之变形，最后增长可以超出支撑能力。"},"semanticMap":{"core":{"en":"CORE IMAGE: grey built-up area spreading across a map that was green only a generation ago.","cn":"核心意象：灰色的建成区在一张上一代人还是绿色的地图上蔓延。"},"chain":["PEOPLE MOVE IN","SHARE RISES","LAND BUILT UP","HABITS DIFFUSE","STATE BUILDS","GROWTH OUTRUNS SUPPORT"],"branches":[{"senses":"01 · 02","en":"MOVEMENT AND MEASURE: the flow of people, and the percentage that records it.","cn":"流动与度量：人的迁移，以及记录这一迁移的百分比。"},{"senses":"03 · 07","en":"LAND AND SOCIETY: building spreads over fields, and dense living redraws households and work.","cn":"土地与社会：建筑铺过田野，密集居住重画了家庭与工作。"},{"senses":"04 · 05","en":"DIFFUSION AND LEVEL: city ways travel beyond the skyline, and the whole can be rated by how far it has gone.","cn":"扩散与水平：城市方式越过天际线传播，整体也可按进展程度评级。"},{"senses":"06","en":"DELIBERATE BUILDING: the state lays roads and housing first and waits for residents.","cn":"有意的建设：国家先铺路建房，再等居民到来。"},{"senses":"08","en":"GROWTH TOO FAST: when jobs and services lag, the same process produces overcrowding rather than opportunity.","cn":"过快的增长：当就业与服务跟不上，同一进程产出的是拥挤，而非机会。"}]},"affixes":{"intro":{"en":"Urbanization is a Latin stem plus a process suffix, and both parts build long families in English.","cn":"urbanization 是一个拉丁词干加一个表过程的后缀，两部分在英语里都建起了很长的词族。"},"latinIntro":{"en":"Latin urbs and urbanus supply the stem; -ization reaches Latin through -izare and Greek -izein.","cn":"拉丁 urbs 与 urbanus 提供词干；-ization 经拉丁 -izare 与希腊 -izein 上溯。"},"items":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市","example":"The Latin noun named the city as a walled place.","exampleCN":"这个拉丁名词把城市指为有城墙的地方。"},{"word":"urbanus","structure":"urbanus (Latin adjective, from urbs)","meaning":"of the city","meaningCN":"城市的","example":"The adjective described both place and manner.","exampleCN":"这个形容词既描述地点，也描述举止。"},{"word":"-ize","structure":"-izare (Latin verb suffix, from Greek -izein)","meaning":"to make, to act","meaningCN":"使；做","example":"The suffix turns a quality into an action.","exampleCN":"这个后缀把性质变成动作。"},{"word":"-ization","structure":"-izatio (Latin action-noun suffix)","meaning":"the process of making","meaningCN":"使之成为的过程","example":"The suffix names the whole process, not one act.","exampleCN":"这个后缀指整个过程，而非单个动作。"},{"word":"urban","structure":"urbanus via French urbain","meaning":"relating to a city","meaningCN":"与城市相关的","example":"Urban schools face different pressures.","exampleCN":"城市学校面对不同的压力。"},{"word":"urbane","structure":"urbanus, with the manner sense kept","meaning":"polished in manner","meaningCN":"举止文雅的","example":"His urbane reply avoided the question.","exampleCN":"他文雅的回答避开了那个问题。"},{"word":"urbanize","structure":"urban + -ize","meaning":"to make urban","meaningCN":"使城市化","example":"The railway urbanized the valley.","exampleCN":"铁路使这个山谷城市化了。"},{"word":"urbanized","structure":"urbanize + -ed","meaning":"made urban","meaningCN":"已城市化的","example":"The urbanized strip follows the motorway.","exampleCN":"城市化的地带沿着高速公路展开。"},{"word":"urbanism","structure":"urban + -ism","meaning":"city life as a pattern","meaningCN":"作为模式的城市生活","example":"Urbanism changed how neighbours meet.","exampleCN":"城市生活方式改变了邻里的相遇方式。"},{"word":"urbanist","structure":"urbanism + -ist","meaning":"one who studies or advocates city life","meaningCN":"研究或倡导城市生活的人","example":"The urbanist argued for narrower streets.","exampleCN":"这位城市研究者主张把街道弄窄。"},{"word":"sub-","structure":"Latin prefix sub- 'under, near'","meaning":"near, below","meaningCN":"近旁、在下","example":"The prefix places the suburb just outside.","exampleCN":"这个前缀把郊区放在城的近外。"},{"word":"ex-","structure":"Latin prefix ex- 'out of'","meaning":"outward","meaningCN":"向外","example":"The prefix pushes development beyond the edge.","exampleCN":"这个前缀把开发推到边缘之外。"}],"latinEntries":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市"},{"word":"urbanus","structure":"urbanus, urbana, urbanum (adjective)","meaning":"of the city","meaningCN":"城市的"},{"word":"urbanitas","structure":"urbanitas, urbanitatis (f., third declension)","meaning":"city life, city manners","meaningCN":"城市生活；城市举止"}]}},{"word":"urban","ipa_uk":"/ˈɜːbən/","ipa_us":"/ˈɜːrbən/","definition_zh":"城市的；都市的；住在城市的；城市化的；城市问题相关的；都市文化风格的","definition_en":"relating to, located in, or characteristic of a city","core_image":"高楼之间的一条窄巷，晾衣绳横在两栋楼的窗台之间，巷口是一家只在凌晨开门的唱片店","scene":"清晨的巷口，早点摊、公交站和修鞋铺挤在同一条街上，行人彼此侧身而过。Urban streets wake earlier than the offices above them.","sceneCN":"这里 urban 指「属于城市的、位于城市之中的」（第 1 个义项：与城市空间相关）；句意为城市街道比它们上方的写字楼醒得更早。可辨识物件：早点摊、公交站牌、修鞋铺、窄巷。","pos":[{"tag":"adj.","zh":"城市的；都市的；住在城市的；城市化的"}],"collocations":[{"phrase":"urban area","zh":"城市地区"},{"phrase":"urban life","zh":"城市生活"},{"phrase":"urban planning","zh":"城市规划"},{"phrase":"urban population","zh":"城市人口"},{"phrase":"urban sprawl","zh":"城市无序扩张"},{"phrase":"urban renewal","zh":"城市更新"}],"forms":[{"label":"原级","form":"urban"},{"label":"比较级","form":"more urban"},{"label":"最高级","form":"most urban"},{"label":"名词（城市主义）","form":"urbanism"},{"label":"动词（使城市化）","form":"urbanize"},{"label":"名词（城市化）","form":"urbanization"},{"label":"名词（城市居民）","form":"urbanite"}],"derivatives":[{"word":"urbanize","pos":"v.","zh":"基础词 urban + -ize（动词后缀）→ 由「城市的」偏移为「使某地转为城市形态」"},{"word":"urbanization","pos":"n.","zh":"urbanize + -ation（动作名词后缀）→ 偏移为「人口与土地转向城市的过程」"},{"word":"urbanism","pos":"n.","zh":"urban + -ism（名词后缀，表体系或倾向）→ 偏移为「城市生活方式与规划理念」"},{"word":"urbanist","pos":"n.","zh":"urbanism + -ist（人名词后缀）→ 偏移为「研究或倡导城市生活的人」"},{"word":"urbanite","pos":"n.","zh":"urban + -ite（表居民的人名词后缀）→ 偏移为「住在城里的人」"},{"word":"urbane","pos":"adj.","zh":"拉丁 urbanus 保留「城市举止」一义的另一支 → 偏移为「举止文雅、世故的」"},{"word":"suburban","pos":"adj.","zh":"sub-（近旁、在下）+ urban → 偏移为「城郊的」"},{"word":"exurban","pos":"adj.","zh":"ex-（向外）+ urban → 偏移为「城市远郊的」"}],"senses":[{"no":"01","title":"Of a city","titleCN":"城市的，位于城市中的","definition":"relating to a city or located within one","definitionCN":"与城市相关，或位于城市之内","example":"Urban streets wake earlier than the offices above them.","exampleCN":"城市街道比它们上方的写字楼醒得更早。","why":"urbanus was the Latin adjective for 'of the city', built on urbs 'city', so the English word simply carries the place.","whyCN":"urbanus 是拉丁语中表「城市的」形容词，由 urbs「城市」构成，英语这个词只是把这个地点带了过来。"},{"no":"02","title":"Living in a city","titleCN":"住在城市的，城市居民的","definition":"describing people or groups who live in cities","definitionCN":"描述住在城市里的人或群体","example":"Urban households spend more of their income on rent.","exampleCN":"城市家庭把更多收入花在租金上。","why":"the same adjective attaches to people, not only to places, because living somewhere makes you a kind of person in speech.","whyCN":"同一个形容词也挂在人身上，而不只挂在地点上，因为住在某处会让人在语言中成为一种人。"},{"no":"03","title":"Characteristic of city life","titleCN":"城市生活特有的","definition":"typical of the pace, style and habits of city life","definitionCN":"体现城市生活的节奏、风格与习惯","example":"The film catches an urban rhythm of rushed meals and late buses.","exampleCN":"这部影片捕捉到一种匆忙吃饭、深夜赶车的城市节奏。","why":"where many strangers live close together, a distinctive manner appears, and the adjective comes to name it.","whyCN":"许多陌生人近距离同住的地方会出现一种独特的举止，形容词便来命名这种举止。"},{"no":"04","title":"Already built up","titleCN":"已城市化的，建成区性质的","definition":"describing land or a district that has taken on city form","definitionCN":"描述已呈城市形态的土地或城区","example":"The urban strip along the motorway was farmland a generation ago.","exampleCN":"沿着高速公路的那条城市地带，在一代人之前还是农田。","why":"the adjective can describe a state reached, not only a location, so a field can become urban without being inside a city.","whyCN":"这个形容词也能描述已达到的状态，而不只是位置，因此一片田野可以在不属于任何城市的情况下变得「城市化」。"},{"no":"05","title":"Relating to city problems","titleCN":"与城市问题相关的","definition":"used of policy concerns that arise from dense city living, such as housing or transport","definitionCN":"用于描述密集城市生活引发的政策问题，如住房或交通","example":"Urban poverty is concentrated in a few blocks near the old market.","exampleCN":"城市贫困集中在旧市场附近的几个街区。","why":"problems cluster where people do, so the adjective became a policy label for that cluster.","whyCN":"问题会聚在人聚的地方，因此这个形容词成了指称那一簇问题的政策标签。"},{"no":"06","title":"A city music and style label","titleCN":"都市文化风格的（音乐、时尚用语）","definition":"used commercially for music, fashion and culture marketed as city-rooted","definitionCN":"商业上用于被标榜为源自城市的音乐、时尚与文化","example":"The radio calls that playlist urban, though half of it comes from small towns.","exampleCN":"电台把那张歌单称为都市风格，尽管其中一半来自小镇。","why":"a label spreads by marketing rather than by geography, which is why this sense is loose and often disputed.","whyCN":"标签靠营销传播，而不是靠地理传播，因此这一义项松散且常受争议。"},{"no":"07","title":"Within city limits","titleCN":"城市规划范围内的","definition":"in planning and law, marking what falls inside a city's administrative boundary","definitionCN":"在规划与法律中，标记位于城市行政边界之内","example":"The urban boundary decides which plots pay the city tax.","exampleCN":"城市边界决定了哪些地块缴纳城市税。","why":"administration needs a hard line where everyday speech has a soft one, so the adjective becomes a legal marker.","whyCN":"行政需要一个硬边界，而日常语言只有软边界，因此这个形容词成了法律标记。"},{"no":"08","title":"Refined in manner (dated)","titleCN":"举止文雅的（旧义）","definition":"old use: polished and sophisticated in manner, a sense now carried by urbane","definitionCN":"旧用法：举止讲究、世故的，这个意思今天改由另一支词形表达","example":"The older novel still uses urban where we would now write urbane.","exampleCN":"那本较早的小说仍在用这个词表达我们今天会换用另一个词形的意思。","why":"urbanus covered both place and manner, and English split the two, giving the manner sense to urbane.","whyCN":"urbanus 同时覆盖地点与举止，英语把两者分开，把举止义交给了 urbane。"}],"etymology":{"intro":{"en":"Urban comes from Latin urbanus 'of the city', built on urbs 'city'; English took it through French urbain in the sixteenth century. Dates are approximate.","cn":"urban 来自拉丁 urbanus「城市的」，由 urbs「城市」构成；英语在十六世纪经法语 urbain 引入。年代均为约数。"},"items":[{"era":"LATIN URBS","en":"Urbs meant 'city', and in Roman usage often meant Rome itself. Its deeper origin is uncertain and no accepted Indo-European source has been demonstrated.","cn":"urbs 意为「城市」，在罗马用法中常特指罗马城。其更早来源不确定，没有已获公认的印欧语来源。"},{"era":"LATIN URBANUS","en":"Urbanus meant 'of the city' and also 'city-mannered'. The double meaning explains why English has both urban and urbane.","cn":"urbanus 既指「城市的」，也指「有城市举止的」。这双重含义解释了英语为何同时有 urban 与 urbane。"},{"era":"LATIN URBANITAS","en":"Urbanitas named city life and the polish thought to belong to it, a word later borrowed into English as urbanity.","cn":"urbanitas 指城市生活以及被认为属于它的文雅，这个词后来被借入英语成为 urbanity。"},{"era":"FRENCH URBAIN","en":"French urbain carried the place sense into English, while the manner sense came in separately as urbane.","cn":"法语 urbain 把地点义带入英语，而举止义另以 urbane 的形式进入。"},{"era":"MODERN POLICY USE","en":"From the nineteenth century urban was attached to problems, planning and populations, producing the policy senses common today.","cn":"从十九世纪起，urban 被挂到问题、规划与人口上，产生了今天常见的政策义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of urbs before Latin is unsettled and the exact first English date is unrecorded, so any earlier form proposed for urbs is a reconstructed form.","cn":"来源不确定：urbs 在拉丁语之前的来源无定论，英语首见的确切年代也没有记录，因此为 urbs 提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the words that share the Latin stem and are swapped constantly; group two holds other adjectives for settled, built-up places.","cn":"第一组是同出拉丁词干、极易互换的词；第二组是其他描述「已成形的居住地」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"urbane","ipa":"/ɜːˈbeɪn/","tag":"manner, not place","definition":"Polished and sophisticated in manner; it kept the social sense of urbanus while urban kept the geographic one.","definitionCN":"举止文雅、世故的；它保留了 urbanus 的社会义，而 urban 保留了地理义。"},{"word":"urbanized","ipa":"/ˈɜːbənaɪzd/","tag":"state reached","definition":"Having already taken on city form; it describes a result, while urban can describe a location.","definitionCN":"已经具备城市形态的；它描述结果，而 urban 可以描述位置。"},{"word":"suburban","ipa":"/səˈbɜːbən/","tag":"edge of the city","definition":"Of the residential districts outside a city centre; it is a position relative to the city, not a synonym.","definitionCN":"指城市中心之外的居住区；它是相对城市的位置，而非同义词。"},{"word":"rural","ipa":"/ˈrʊərəl/","tag":"the opposite","definition":"Of the countryside; it is the standard opposite of urban rather than a near equivalent.","definitionCN":"乡村的；它是 urban 的标准反义词，而不是近义词。"},{"word":"urbanization","ipa":"/ˌɜːbənaɪˈzeɪʃn/","tag":"the process","definition":"The process of becoming city-like; the adjective describes what exists, the noun describes the change.","definitionCN":"变成城市样子的过程；形容词描述已存在之物，名词描述变化。"}]},{"heading":"NEAR MEANING","entries":[{"word":"metropolitan","ipa":"/ˌmetrəˈpɒlɪtən/","tag":"the whole conurbation","definition":"Relating to a large city and its surrounding region; it is wider than urban because it includes the commuter belt.","definitionCN":"与大城市及其周边地区相关；比 urban 更宽，因为它包含通勤带。"},{"word":"civic","ipa":"/ˈsɪvɪk/","tag":"citizens and government","definition":"Relating to citizens or city government; it concerns administration, where urban concerns space and life.","definitionCN":"与公民或市政府相关；它关乎行政，而 urban 关乎空间与生活。"},{"word":"municipal","ipa":"/mjuːˈnɪsɪpl/","tag":"by legal status","definition":"Of a town or city as a legal body; it is an official category, not a description of life.","definitionCN":"指作为法人的城镇或城市；它是官方类别，不是对生活的描述。"},{"word":"built-up","ipa":"/ˌbɪlt ˈʌp/","tag":"covered with buildings","definition":"Densely covered with buildings; it describes the physical surface without the social sense urban carries.","definitionCN":"建筑密集覆盖的；它描述物理表面，不含 urban 所带的社会含义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Latin stem, the real split with urbane and real fixed phrases, not invented rhymes.","cn":"正常联想：真实的拉丁词干、与 urbane 的真实分化以及真实固定搭配，而非编造的顺口溜。"},"normal":[{"en":"urbs 'city' gives urbanus 'of the city'; the place sense stays in urban, the manner sense went to urbane.","cn":"urbs「城市」给出 urbanus「城市的」；地点义留在 urban，举止义去了 urbane。"},{"en":"The family runs urban, urbanize, urbanization, urbanism, urbanist, urbanite, suburban, exurban.","cn":"同族词包括 urban、urbanize、urbanization、urbanism、urbanist、urbanite、suburban、exurban。"},{"en":"Fixed phrases mark the policy senses: urban area, urban planning, urban renewal, urban sprawl.","cn":"固定搭配标出政策义：城市地区、城市规划、城市更新、城市无序扩张。"},{"en":"Latin urbanitas became English urbanity, the noun for city polish.","cn":"拉丁 urbanitas 变成英语 urbanity，指城市式的文雅。"},{"en":"The opposite is rural, and the in-between is suburban; three words mark three rings.","cn":"反面是 rural，中间是 suburban；三个词标出三个圈层。"}],"abstract":[{"en":"Picture a narrow lane where a clothes line connects two windows and a record shop opens at midnight.","cn":"想象一条窄巷，晾衣绳连着两扇窗，一家唱片店在午夜开门。"},{"en":"Picture a street that knows the time by buses rather than by clocks.","cn":"想象一条街靠公交而不是靠钟表来知道时间。"},{"en":"Picture a map where a single line separates taxed ground from untaxed ground.","cn":"想象一张地图，一条线把要缴税的地和不用缴税的地分开。"}]},"examples":[{"en":"Urban heat is worse where there are few trees and much concrete.","cn":"树木少、水泥多的地方，城市高温更严重。"},{"en":"The study compared urban and rural school results.","cn":"这项研究比较了城市与乡村的学校成绩。"},{"en":"Her accent is urban without being local to any one city.","cn":"她的口音是城市味的，却不属于任何一座具体的城市。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「urban（音近『饿本』）」——城里什么都贵，饿了得花本钱 → 城市的、都市的","word":"urban"},"root":"拉丁 urbs「城市」→ urbanus「城市的、有城市举止的」；urbs 更早来源不确定。英语 urban 经法语 urbain 进入，举止义另由 urbane 承担。","sensesIntro":{"en":"Eight senses follow one place: the adjective begins with city space, then attaches to the people in it, to the manner of living there, to land already built up, to policy problems, to a marketing label, to a legal boundary, and finally to an older sense of polished manners.","cn":"八个义项沿一个地点展开：这个形容词从城市空间出发，随后挂到其中的人、那里的生活方式、已建成的土地、政策问题、商业标签、法律边界，最后落到一个更旧的「举止文雅」义。"},"semanticMap":{"core":{"en":"CORE IMAGE: a dense place where strangers live close enough to share walls, buses and noise.","cn":"核心意象：一个密集之处，陌生人住得足够近，共享墙壁、公交与噪音。"},"chain":["CITY SPACE","CITY PEOPLE","CITY MANNER","BUILT-UP LAND","CITY POLICY","POLISHED MANNERS"],"branches":[{"senses":"01","en":"THE PLACE ITSELF: the basic geographic sense, a city and what lies inside it.","cn":"地点本身：最基本的地理义，指一座城市及其内部。"},{"senses":"02 · 03","en":"PEOPLE AND MANNER: those who live there, and the rhythm that dense living produces.","cn":"人与举止：住在那里的人，以及密集居住产生的节奏。"},{"senses":"04 · 07","en":"LAND AND LINE: ground that has taken city form, and the legal boundary drawn around it.","cn":"土地与界线：已呈城市形态的地面，以及围住它的法律边界。"},{"senses":"05 · 06","en":"PROBLEMS AND LABELS: policy concerns that cluster in cities, and commercial labels that borrow the word.","cn":"问题与标签：聚在城市里的政策关切，以及借用这个词的商业标签。"},{"senses":"08","en":"MANNER SPLIT OFF: the old social sense survives in urbane, a separate word.","cn":"分出去的举止义：旧的社会义活在另一个词 urbane 里。"}]},"affixes":{"intro":{"en":"Urban is a Latin adjective whose stem builds a large modern family through suffixes of process, state, person and place.","cn":"urban 是一个拉丁形容词，其词干通过表过程、状态、人物与位置的后缀建起一个很大的现代词族。"},"latinIntro":{"en":"Latin urbs 'city' and urbanus 'of the city' supply the stem; urbanitas adds the manner sense that English split off as urbane.","cn":"拉丁 urbs「城市」与 urbanus「城市的」提供词干；urbanitas 增添的举止义被英语分出去成为 urbane。"},"items":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市","example":"The noun named a city as a bounded place.","exampleCN":"这个名词把城市指为一个有边界的地方。"},{"word":"urbanus","structure":"urbanus (Latin adjective, from urbs)","meaning":"of the city","meaningCN":"城市的","example":"The adjective served for both place and manner.","exampleCN":"这个形容词兼指地点与举止。"},{"word":"-ize","structure":"-izare (Latin verb suffix, from Greek -izein)","meaning":"to make","meaningCN":"使成为","example":"The suffix turns the adjective into a verb of change.","exampleCN":"这个后缀把形容词变成表变化的动词。"},{"word":"-ation","structure":"-atio (Latin action-noun suffix)","meaning":"the process","meaningCN":"过程","example":"The suffix names the whole change, not one step.","exampleCN":"这个后缀指整个变化，而非其中一步。"},{"word":"-ism","structure":"-ismus (Greek and Latin noun suffix)","meaning":"a system or tendency","meaningCN":"体系或倾向","example":"Urbanism names a way of living.","exampleCN":"urbanism 指一种生活方式。"},{"word":"-ist","structure":"-ista (person suffix)","meaning":"one who practices","meaningCN":"从事者","example":"The urbanist studies street life.","exampleCN":"这位城市研究者研究街道生活。"},{"word":"-ite","structure":"-ita (person suffix, 'dweller')","meaning":"a resident","meaningCN":"居民","example":"An urbanite rarely hears silence at night.","exampleCN":"城市居民夜里很少听到安静。"},{"word":"-ane","structure":"Latin -anus with a shift of meaning","meaning":"belonging to, in manner","meaningCN":"属于……的（就举止而言）","example":"Urbane kept the social half of the Latin word.","exampleCN":"urbane 保留了那个拉丁词的社会那一半。"},{"word":"sub-","structure":"Latin prefix sub- 'under, near'","meaning":"near, just outside","meaningCN":"近旁、紧靠外侧","example":"The prefix marks the ring just outside the centre.","exampleCN":"这个前缀标出紧靠中心外侧的那一圈。"},{"word":"ex-","structure":"Latin prefix ex- 'out of'","meaning":"outward, beyond","meaningCN":"向外、越出","example":"The prefix marks development beyond the edge.","exampleCN":"这个前缀标出边缘之外的开发。"}],"latinEntries":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市"},{"word":"urbanus","structure":"urbanus, urbana, urbanum (adjective)","meaning":"of the city","meaningCN":"城市的"},{"word":"urbanitas","structure":"urbanitas, urbanitatis (f., third declension)","meaning":"city life; city manners","meaningCN":"城市生活；城市举止"}]}},{"word":"urban development","ipa_uk":"/ˈɜːbən dɪˈveləpmənt/","ipa_us":"/ˈɜːrbən dɪˈveləpmənt/","definition_zh":"城市开发；城市发展；城市建设项目；城市更新；可持续城市发展","definition_en":"the building, expansion and improvement of land and services within a city","core_image":"围挡上印着未来的公园与地铁线，围挡里面是刚挖开的土坑和几台静立的挖机","scene":"河岸边旧仓库被推倒，新楼盘的围挡上印着公园与地铁的规划图。Urban development reshaped the old harbour district.","sceneCN":"这里 urban development 指「城市土地与设施的建设与改造」（第 1 个义项：城市空间的实体开发）；句意为城市开发重塑了这片旧港区。可辨识物件：围挡、规划图、挖机、旧仓库。","pos":[{"tag":"n.","zh":"城市开发；城市发展（通常不可数，指多个项目时可说 urban developments）"}],"collocations":[{"phrase":"urban development project","zh":"城市开发项目"},{"phrase":"sustainable urban development","zh":"可持续城市发展"},{"phrase":"rapid urban development","zh":"快速城市发展"},{"phrase":"urban development plan","zh":"城市开发规划"},{"phrase":"urban development policy","zh":"城市发展政策"},{"phrase":"urban development land","zh":"城市开发用地"}],"forms":[{"label":"通常形式（不可数）","form":"urban development"},{"label":"复数（指多个具体项目）","form":"urban developments"},{"label":"相关名词（开发商）","form":"urban developer"},{"label":"相关名词（开发）","form":"development"},{"label":"相关形容词（城市的）","form":"urban"},{"label":"同义说法","form":"urban growth"}],"derivatives":[{"word":"develop","pos":"v.","zh":"基础动词 develop 去掉 -ment 后的形式，由「逐步展开」偏移为「使土地或地区具备用途」"},{"word":"development","pos":"n.","zh":"develop + -ment（名词后缀）→ 偏移为「逐步展开的过程与成果」"},{"word":"developer","pos":"n.","zh":"develop + -er（施事后缀）→ 偏移为「做开发的人或公司」"},{"word":"developmental","pos":"adj.","zh":"development + -al（形容词后缀）→ 偏移为「与发育或发展相关的」"},{"word":"redevelopment","pos":"n.","zh":"re-（再）+ development → 偏移为「对已开发地段的再次改造」"},{"word":"underdevelopment","pos":"n.","zh":"under-（不足）+ development → 偏移为「发展不足的状态」"},{"word":"urbanize","pos":"v.","zh":"urban + -ize（动词后缀）→ 偏移为「使某地转为城市形态」"}],"senses":[{"no":"01","title":"Physical building of city land","titleCN":"城市土地的实体开发","definition":"the construction of buildings, roads and services on land within or next to a city","definitionCN":"在城市之内或紧邻城市的土地上修建建筑、道路与服务设施","example":"Urban development reshaped the old harbour district.","exampleCN":"城市开发重塑了这片旧港区。","why":"development means the gradual unfolding of something, and applied to land it means bringing a site into use step by step.","whyCN":"development 指某物逐步展开，用在土地上就是让一块地一步步具备用途。"},{"no":"02","title":"City planning of growth","titleCN":"对城市增长所作的规划","definition":"the planned direction of a city's growth, including zoning and phasing","definitionCN":"对城市增长方向所做的计划，包括分区与分期","example":"The urban development map reserved the flood plain as parkland.","exampleCN":"城市开发图把洪泛区留作公园用地。","why":"once growth can be steered, development stops describing what happened and starts naming what is intended.","whyCN":"一旦增长可以被引导，开发就不再描述已发生的事，而开始命名所意图的事。"},{"no":"03","title":"A specific development project","titleCN":"具体的城市开发项目","definition":"one scheme, such as a housing estate or a commercial block, built as a unit","definitionCN":"作为一个整体来建的一项工程，如住宅区或商业街区","example":"Three urban developments line the new tram route.","exampleCN":"三个城市开发项目沿新电车线路排开。","why":"the uncountable process is countable when it is packaged as a project, which is why the plural exists.","whyCN":"这一不可数的过程在被打包成工程时就可数了，因此才有复数形式。"},{"no":"04","title":"Economic growth of a city","titleCN":"城市的经济增长与发展","definition":"the growth of a city's economy, jobs and tax base","definitionCN":"城市经济、就业与税基的增长","example":"Urban development brought warehouses but few skilled jobs.","exampleCN":"城市发展带来了仓库，却几乎没有带来技术岗位。","why":"development also measures a place's economic advance, so the same phrase serves planners and economists.","whyCN":"开发也衡量一个地方的经济进展，因此同一短语同时供规划者与经济学家使用。"},{"no":"05","title":"Urban renewal","titleCN":"城市更新与再开发","definition":"the replacement or repair of decayed districts rather than the extension of new ones","definitionCN":"对衰败城区的替换或修缮，而非向外扩建新区","example":"Urban development here means knocking down and rebuilding, not expanding.","exampleCN":"这里的城市开发指的是拆掉重建，而不是向外扩张。","why":"when a city has no empty land, development must reuse what already exists.","whyCN":"当城市没有空地，开发只能重新利用已有的东西。"},{"no":"06","title":"Real estate development","titleCN":"城市房地产开发","definition":"the commercial building of housing and offices for sale or rent","definitionCN":"为出售或出租而商业性建造住房与写字楼","example":"Private urban development outpaced the public water network.","exampleCN":"私人房地产开发跑在了公共水管网前面。","why":"the phrase is neutral, so it covers both public works and the private property business.","whyCN":"这个短语是中性的，因此既覆盖公共工程，也覆盖私人房地产业。"},{"no":"07","title":"Sustainable urban development","titleCN":"可持续城市发展","definition":"growth planned so that transport, housing and green space remain workable long term","definitionCN":"为使交通、住房与绿地在长期内仍可运作而规划的增长","example":"Sustainable urban development means building where the drains already run.","exampleCN":"可持续城市发展意味着在排水系统已经到位的地方建设。","why":"the phrase acquired a policy sense once the costs of unplanned growth became visible.","whyCN":"当无序增长的代价显现，这个短语就获得了一个政策义。"},{"no":"08","title":"Institutions and policy","titleCN":"城市发展的制度与政策","definition":"the laws, agencies and financing through which building is approved and paid for","definitionCN":"批准并资助建设的法律、机构与融资安排","example":"Urban development is decided in offices far from the sites.","exampleCN":"城市发展是在远离工地的办公室里被决定的。","why":"what gets built is settled by permits and budgets, so the phrase extends to the machinery behind the building.","whyCN":"建什么由许可与预算决定，因此这个短语扩展到建筑背后的那套机器。"}],"etymology":{"intro":{"en":"Urban development joins urban, from Latin urbs 'city', to development, whose deeper origin is uncertain; the phrase is a twentieth-century planning term. Dates are approximate.","cn":"urban development 把来自拉丁 urbs「城市」的 urban 与 development 组合起来，后者更早的来源不确定；这个短语是二十世纪的规划术语。年代均为约数。"},"items":[{"era":"LATIN URBANUS","en":"Urbanus 'of the city' came from urbs 'city', whose origin before Latin is not established.","cn":"urbanus「城市的」来自 urbs「城市」，而 urbs 在拉丁语之前的来源未得到证明。"},{"era":"OLD FRENCH DESVELOPER","en":"Old French desveloper meant 'to unwrap, to unfold'. The sense of gradual growth came later, in English.","cn":"古法语 desveloper 意为「解开、展开」，逐步成长的意思后来才在英语中出现。"},{"era":"ENGLISH DEVELOP","en":"English develop first meant to unfold or bring out what was latent, then to build up land and resources.","cn":"英语 develop 先指展开或引出潜在之物，后指开发土地与资源。"},{"era":"DEVELOPMENT NOUN","en":"The noun development took the sense of a built result as well as a process, which is why a site can be called a development.","cn":"名词 development 兼指过程与建成的结果，因此一块地也可以被称为一项开发。"},{"era":"POST-WAR PLANNING","en":"Urban development became a standard phrase in post-war planning, housing and international aid writing.","cn":"urban development 在战后规划、住房与国际援助文献中成为标准说法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the deeper origin of desveloper is unsettled and the exact first use of the phrase is unrecorded; any earlier form proposed for it is a reconstructed form.","cn":"来源不确定：desveloper 的更早来源无定论，这个短语的确切首见也没有记录；为它提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the compound from the overlapping planning terms; group two holds the physical and social processes it is often confused with.","cn":"第一组把这一复合词与重叠的规划术语分开；第二组是常与它混淆的实体与社会过程。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"urban planning","ipa":"/ˈɜːbən ˈplænɪŋ/","tag":"the design stage","definition":"The professional activity of deciding land use and layout; development is the building that follows the plan.","definitionCN":"决定土地使用与布局的专业活动；开发是跟着规划进行的建设。"},{"word":"urban growth","ipa":"/ˈɜːbən ɡrəʊθ/","tag":"the measured increase","definition":"The increase in a city's size or population; growth can be measured, while development includes deliberate improvement.","definitionCN":"城市规模或人口的增长；增长可以测量，而开发还包含有意的改良。"},{"word":"redevelopment","ipa":"/ˌriːdɪˈveləpmənt/","tag":"second round","definition":"Development of land that was already built on; it is one branch of urban development, not the whole.","definitionCN":"对已建成土地的再次开发；它是城市开发的一个分支，而非全部。"},{"word":"development","ipa":"/dɪˈveləpmənt/","tag":"the general term","definition":"The general process of growth or building; adding urban narrows it to cities but does not change its logic.","definitionCN":"增长或建设的一般过程；加上 urban 只是把它收窄到城市，并不改变其逻辑。"},{"word":"urban sprawl","ipa":"/ˈɜːbən sprɔːl/","tag":"the criticized form","definition":"Low-density outward spread; it is a pattern that development can produce, and usually a criticism of it.","definitionCN":"低密度的向外铺开；它是开发可能产生的一种形态，通常带着批评。"}]},{"heading":"NEAR MEANING","entries":[{"word":"construction","ipa":"/kənˈstrʌkʃn/","tag":"the work itself","definition":"The activity of building; it is the physical work, while development covers financing, approval and use.","definitionCN":"建造的活动；它是实体施工，而开发还涵盖融资、审批与用途。"},{"word":"infrastructure","ipa":"/ˈɪnfrəstrʌktʃə/","tag":"the support systems","definition":"Roads, pipes and power that support a city; infrastructure is one input to development, not its synonym.","definitionCN":"支撑城市的道路、管网与电力；基础设施是开发的投入之一，不是同义词。"},{"word":"gentrification","ipa":"/ˌdʒentrɪfɪˈkeɪʃn/","tag":"social displacement","definition":"The renewal of a poor district that displaces its poorer residents; it is one social outcome of development.","definitionCN":"贫困街区被翻新、却把较穷的居民挤走；它是开发的一种社会后果。"},{"word":"modernization","ipa":"/ˌmɒdənaɪˈzeɪʃn/","tag":"technology and institutions","definition":"Adoption of modern methods and institutions; it can happen without any building, so it is broader than development.","definitionCN":"采纳现代方法与制度；它可以在完全不建设的情况下发生，因此比开发更宽。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves, the real planning phrases and the real relatives.","cn":"正常联想：两个真实的部分、真实的规划说法与真实同族词。"},"normal":[{"en":"urban 'of the city' + development 'unfolding': the city unfolded into use.","cn":"urban「城市的」+ development「展开」：城市被一步步展开到可用状态。"},{"en":"Fixed phrases mark the field: urban development project, urban development plan, urban development policy.","cn":"固定搭配标出领域：城市开发项目、城市开发规划、城市发展政策。"},{"en":"The family runs develop, development, developer, developmental, redevelopment, underdevelopment.","cn":"同族词包括 develop、development、developer、developmental、redevelopment、underdevelopment。"},{"en":"A site is called a development because the noun names the built result as well as the process.","cn":"一块地被称为一项开发，是因为这个名词兼指过程与建成的结果。"},{"en":"Sustainable urban development adds the condition that drains, transport and green space must keep working.","cn":"可持续城市发展加上了排水、交通与绿地必须持续可用的条件。"}],"abstract":[{"en":"Picture a fence painted with the park that will stand behind it.","cn":"想象一道围挡，上面画着将来会立在它后面的公园。"},{"en":"Picture an old warehouse whose bricks are numbered for reuse before it is pulled down.","cn":"想象一座旧仓库在被推倒之前，砖块已被编号准备再用。"},{"en":"Picture a permit signed far away that decides which field will become a street.","cn":"想象一份在很远的地方签下的许可，决定了哪片田会变成街道。"}]},"examples":[{"en":"Urban development stalled when the water supply could not keep pace.","cn":"供水跟不上时，城市开发停滞了。"},{"en":"The report treats urban development as a public health issue.","cn":"这份报告把城市发展当作公共卫生问题来处理。"},{"en":"New urban developments must leave room for drainage.","cn":"新的城市开发项目必须留出排水空间。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「urban（城市的）+ development（展开、发展）」——把城市一步步展开建起来 → 城市开发","word":"urban development"},"root":"urban（拉丁 urbs「城市」→ urbanus「城市的」）+ development（古法语 desveloper「解开、展开」，更早来源不确定）；短语为二十世纪规划用语。","sensesIntro":{"en":"Eight senses follow one act: land is brought into use, and the same act is then seen as a plan, a project, an economy, a renewal, a property business, a sustainability condition and finally as the offices that permit it.","cn":"八个义项沿一个动作展开：土地被带人可使用状态，这个动作随后被看作规划、项目、经济、更新、房地产业、可持续条件，最后被看作批准它的那些办公室。"},"semanticMap":{"core":{"en":"CORE IMAGE: a site fenced off from its old use and opened toward a new one.","cn":"核心意象：一块地从旧用途中被围起来，朝一个新用途打开。"},"chain":["SITE BROUGHT INTO USE","GROWTH STEERED","PROJECT PACKAGED","ECONOMY EXPANDED","OLD DISTRICT REBUILT","PERMITS AND BUDGETS"],"branches":[{"senses":"01 · 03","en":"FROM GROUND TO PROJECT: physical work on a site, then the same work packaged and counted as one scheme.","cn":"从地面到项目：工地上的实体施工，再把同一施工打包计作一项工程。"},{"senses":"02","en":"STEERING GROWTH: the plan comes before the building and decides its direction.","cn":"引导增长：规划先于建设，并决定其方向。"},{"senses":"04 · 06","en":"MONEY AND JOBS: development is also an economic and property process with its own measures.","cn":"钱与岗位：开发也是一种经济与房地产过程，有自己的衡量方式。"},{"senses":"05","en":"REBUILDING WHAT EXISTS: when there is no empty land, development must reuse the old district.","cn":"重建已有之物：没有空地时，开发只能重新利用旧城区。"},{"senses":"07 · 08","en":"CONDITIONS AND PERMISSIONS: sustainability sets limits, and offices and budgets decide what is allowed.","cn":"条件与许可：可持续性设定限制，办公室与预算决定什么被允许。"}]},"affixes":{"intro":{"en":"The phrase is two words, and each contributes a productive family: urban for place, development for unfolding.","cn":"这个短语由两个词组成，每个都贡献一个高产词族：urban 表地点，development 表展开。"},"latinIntro":{"en":"Urban is Latin-derived, from urbs; development is not Latin at all, coming through Old French with an uncertain deeper origin.","cn":"urban 源自拉丁 urbs；development 并非拉丁词，经古法语进入英语，更早来源不确定。"},"items":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市","example":"The stem supplies the place half of the phrase.","exampleCN":"这个词干提供短语中表地点的那一半。"},{"word":"urbanus","structure":"urbanus (Latin adjective)","meaning":"of the city","meaningCN":"城市的","example":"Urban land carries a different price.","exampleCN":"城市土地的价格不同。"},{"word":"develop","structure":"Old French desveloper 'to unwrap'","meaning":"to unfold gradually","meaningCN":"逐步展开","example":"The site developed over twenty years.","exampleCN":"这块地在二十年间逐步开发。"},{"word":"-ment","structure":"Latin -mentum via French -ment (noun suffix)","meaning":"result or process","meaningCN":"结果或过程","example":"The suffix makes a noun of the action.","exampleCN":"这个后缀把动作变成名词。"},{"word":"developer","structure":"develop + -er (agent suffix)","meaning":"one who develops","meaningCN":"做开发的人","example":"The developer missed the drainage deadline.","exampleCN":"开发商错过了排水工程的期限。"},{"word":"developmental","structure":"development + -al","meaning":"relating to growth","meaningCN":"与成长相关的","example":"The project entered its developmental stage.","exampleCN":"这个项目进入开发阶段。"},{"word":"re-","structure":"Latin prefix re- 'again, back'","meaning":"again","meaningCN":"再次","example":"Redevelopment repeats the work on old ground.","exampleCN":"再开发是在旧地面上重做一遍。"},{"word":"under-","structure":"Old English prefix under- 'below, insufficient'","meaning":"too little","meaningCN":"不足","example":"Underdevelopment marks a shortfall, not a stage.","exampleCN":"发展不足标记的是欠缺，而不是某个阶段。"},{"word":"urbanize","structure":"urban + -ize","meaning":"to make urban","meaningCN":"使城市化","example":"The road urbanized the valley within a decade.","exampleCN":"这条路在十年内使山谷城市化了。"}],"latinEntries":[{"word":"urbs","structure":"urbs, urbis (f., third declension)","meaning":"city","meaningCN":"城市"},{"word":"urbanus","structure":"urbanus, urbana, urbanum (adjective)","meaning":"of the city","meaningCN":"城市的"}]}},{"word":"metropolis","ipa_uk":"/məˈtrɒpəlɪs/","ipa_us":"/məˈtrɑːpəlɪs/","definition_zh":"大都市；首要城市；特大城市的中心；文化或经济中心；宗主国城市；大主教座城市","definition_en":"a very large and important city, especially one that is the centre of a region","core_image":"从高处看，高架桥一层层叠起，灯光一直铺到看不见的地平线，城市没有明显的边","scene":"从观景台看下去，高架桥层层叠叠，灯光一直铺到看不见的地平线。The metropolis keeps moving long after midnight.","sceneCN":"这里 metropolis 指「规模极大、并作为区域中心的大城市」（第 1 个义项：首要大城市）；句意为这座大都市在午夜之后仍不停歇。可辨识物件：观景台、高架桥、车灯、地平线。","pos":[{"tag":"n.","zh":"大都市；首要城市（可数，复数 metropolises）"}],"collocations":[{"phrase":"sprawling metropolis","zh":"不断铺开的大都市"},{"phrase":"financial metropolis","zh":"金融大都市"},{"phrase":"bustling metropolis","zh":"熙攘的大都市"},{"phrase":"the metropolis of the region","zh":"该区域的首要大城"},{"phrase":"rise of the metropolis","zh":"大都市的兴起"},{"phrase":"a great metropolis","zh":"一座伟大的都市"}],"forms":[{"label":"单数","form":"metropolis"},{"label":"复数","form":"metropolises"},{"label":"形容词（大都市的）","form":"metropolitan"},{"label":"名词（宗主国本土）","form":"metropole"},{"label":"截短形式（地铁）","form":"metro"},{"label":"名词（巨型城市带）","form":"megalopolis"}],"derivatives":[{"word":"metropolitan","pos":"adj./n.","zh":"metropolis 去掉词尾 -is 加拉丁 -itan（形容词后缀）→ 由「母城」偏移为「属于大都市的」"},{"word":"metropole","pos":"n.","zh":"希腊 mētropolis 经法语 métropole → 偏移为「相对殖民地的宗主国本土」"},{"word":"metro","pos":"n.","zh":"metropolitan 的截短形式 → 偏移为「大都市的地铁系统」"},{"word":"megalopolis","pos":"n.","zh":"mega-（巨大）+ polis（城）→ 偏移为「连成一片的巨型城市带」"},{"word":"necropolis","pos":"n.","zh":"necro-（死者）+ polis（城）→ 偏移为「墓城、大型墓地」"},{"word":"metropolitanism","pos":"n.","zh":"metropolitan + -ism（名词后缀）→ 偏移为「以大都市为中心的生活方式与心态」"}],"senses":[{"no":"01","title":"A great city","titleCN":"大都市，首要大城市","definition":"a city of great size and importance, usually the leading city of a country or region","definitionCN":"规模与重要性都很高、通常是某国或某地区首位城市的城市","example":"The metropolis keeps moving long after midnight.","exampleCN":"这座大都市在午夜之后仍不停歇。","why":"Greek mētēr 'mother' plus polis 'city' named the mother city of a colony, and size and centrality grew out of that role.","whyCN":"希腊 mētēr「母亲」加 polis「城」原指殖民地的母城，规模与中心地位都从这个角色生长出来。"},{"no":"02","title":"A city by sheer size","titleCN":"按人口规模而言的特大城市","definition":"a city defined chiefly by the number of people packed into it","definitionCN":"主要以聚居于其中的人口数量来界定的大城","example":"By population alone, the delta holds three metropolises.","exampleCN":"仅按人口计算，这个三角洲就有三座特大城市。","why":"once the word lost its colonial meaning, sheer scale was enough to earn it.","whyCN":"一旦这个词失去殖民义，单凭规模就足以取得它。"},{"no":"03","title":"A regional hub","titleCN":"区域中心与枢纽","definition":"the city through which a region's transport, trade and administration run","definitionCN":"一个地区的交通、贸易与行政所经的中心城市","example":"Every rail line in the province ends at the metropolis.","exampleCN":"全省每一条铁路都终点于这座中心城市。","why":"being a mother city means other places depend on you, and dependence is what makes a hub.","whyCN":"作为母城意味着别的地方依赖你，而依赖正是枢纽之所以为枢纽。"},{"no":"04","title":"An imperial mother city","titleCN":"宗主国城市（历史义）","definition":"in colonial usage, the home city or country ruling over a dependent territory","definitionCN":"在殖民用法中，统治附属地的本土城市或本国","example":"The colony shipped its raw material to the metropolis.","exampleCN":"殖民地把它原料运往宗主国城市。","why":"this is the original sense restored: the mother city that a settlement looked back to.","whyCN":"这是原义的回返：移居地回头仰望的那座母城。"},{"no":"05","title":"A cultural and economic centre","titleCN":"文化与经济中心","definition":"a city that concentrates a country's publishing, finance, fashion or education","definitionCN":"集中一国出版、金融、时尚或教育的城市","example":"The metropolis sets the style that the provinces copy.","exampleCN":"这座都市定下风格，外地再模仿。","why":"centrality in institutions followed centrality in politics, and the word widened to any dominant centre.","whyCN":"机构上的中心性跟着政治上的中心性而来，这个词便扩展到任何占主导的中心。"},{"no":"06","title":"An archbishop's seat","titleCN":"大主教座所在城市（教会义）","definition":"the see of a metropolitan bishop, who oversees the bishops of a province","definitionCN":"大主教座所在之地，该主教管辖一教省的诸主教","example":"The old metropolis still holds the cathedral and the archives.","exampleCN":"这座古老的座城仍保有主教座堂与档案。","why":"the church kept the administrative sense of the mother city long after empires had gone.","whyCN":"帝国消失很久之后，教会仍保留着「母城」的行政义。"},{"no":"07","title":"A city in fiction","titleCN":"虚构作品中的巨型城市","definition":"an imagined city of enormous scale used as a setting or a character","definitionCN":"作为背景或角色使用的、规模巨大的想象城市","example":"The novel's metropolis has no edges, only weather.","exampleCN":"小说里的那座巨型城市没有边界，只有天气。","why":"fiction pushes the defining trait, sheer size, until the city becomes a condition rather than a place.","whyCN":"虚构把它的核心特征——纯粹的规模——推到极致，直到城市成为一种处境而不是一个地点。"},{"no":"08","title":"A figurative centre","titleCN":"比喻义的中心与枢纽","definition":"the acknowledged centre of a activity, used figuratively of a place or institution","definitionCN":"某项活动公认的中心，用于地点或机构的比喻说法","example":"That laboratory is the metropolis of the field.","exampleCN":"那间实验室是该领域的中心。","why":"if a metropolis is where everything converges, any converging point can be called one.","whyCN":"如果大都市是一切汇聚之处，那么任何汇聚点都可以被称为大都市。"}],"etymology":{"intro":{"en":"Metropolis is Greek mētēr 'mother' plus polis 'city', naming the mother city of a colony; it reached English through Late Latin and French. Dates are approximate.","cn":"metropolis 由希腊 mētēr「母亲」加 polis「城」构成，指殖民地的母城；它经晚期拉丁与法语进入英语。年代均为约数。"},"items":[{"era":"GREEK METER","en":"Mētēr meant 'mother'; its Indo-European origin is generally thought to be the widespread *mater- root, though the Greek form itself is attested, not reconstructed.","cn":"mētēr 意为「母亲」；一般认为其印欧来源是广泛分布的 *mater- 词根，不过希腊语形式本身有书证，并非重构。"},{"era":"GREEK POLIS","en":"Polis meant 'city, citizen-body'. Its deeper origin is uncertain, and no single Indo-European source has been accepted.","cn":"polis 意为「城邦、公民群体」。其更早来源不确定，也没有公认的单一印欧语来源。"},{"era":"GREEK METROPOLIS","en":"Mētropolis named the mother city of a colony, the place from which settlers came and to which the settlement remained tied.","cn":"mētropolis 指殖民地的母城，即移居者来处、也是移居地仍与之相连的地方。"},{"era":"LATE LATIN","en":"Late Latin used metropolis as a Greek loanword, chiefly in church administration for a bishop's seat.","cn":"晚期拉丁把 metropolis 作为希腊借词使用，主要用于教会行政，指主教座所在之城。"},{"era":"FRENCH MÉTROPOLE","en":"French métropole carried the word into modern European languages, where it widened from mother city to any great city.","cn":"法语 métropole 把这个词带入近代欧洲诸语言，其义从母城扩展为任何大城。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of polis before Greek is unsettled, and no attested earlier form exists, so any proposed pre-Greek root is a reconstructed form.","cn":"来源不确定：polis 在希腊语之前的来源无定论，也没有有书证的更早形式，因此任何提出的希腊语之前词根均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the polis family and its look-alikes; group two holds the terms for very large urban units.","cn":"第一组是 polis 词族及其形近词；第二组是表示超大城市场域的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metropolitan","ipa":"/ˌmetrəˈpɒlɪtən/","tag":"the adjective","definition":"Relating to a metropolis or its whole region; it describes, while metropolis names the city.","definitionCN":"与大都市或其整个区域相关；它作描述，而 metropolis 指城市本身。"},{"word":"metropole","ipa":"/ˈmetrəpəʊl/","tag":"the imperial sense","definition":"The home territory of a colonial power, as seen from the colony; it is the political half of the older word.","definitionCN":"从殖民地视角看的宗主国本土；它是这个旧词的政治那一半。"},{"word":"megalopolis","ipa":"/ˌmeɡəˈlɒpəlɪs/","tag":"joined cities","definition":"A continuous urban region formed when several cities merge; it is larger than one metropolis and not a synonym.","definitionCN":"由数座城市连并而成的连续城市区域；比单座大都市更大，并非同义词。"},{"word":"necropolis","ipa":"/neˈkrɒpəlɪs/","tag":"city of the dead","definition":"A large cemetery, literally a city of the dead; it shares the polis ending but not the meaning.","definitionCN":"大型墓地，字面是「死者的城」；它与 metropolis 共享 polis 词尾，意思却不同。"},{"word":"cosmopolis","ipa":"/kɒzˈmɒpəlɪs/","tag":"world city","definition":"A city of many peoples, literally a world city; the first element is cosmos, not mother.","definitionCN":"由许多民族组成的城市，字面是「世界城」；前一个成分是 cosmos，不是「母亲」。"}]},{"heading":"NEAR MEANING","entries":[{"word":"megacity","ipa":"/ˈmeɡəsɪti/","tag":"a threshold term","definition":"A city above a fixed population threshold, usually ten million; it is a statistical category, not a historical role.","definitionCN":"人口超过某一固定门槛（通常一千万）的城市；它是统计类别，不是历史角色。"},{"word":"capital","ipa":"/ˈkæpɪtl/","tag":"seat of government","definition":"The city where a government sits; a metropolis may or may not be a capital, since the word concerns size and centrality.","definitionCN":"政府所在之城；大都市未必是首都，因为这个词关乎规模与中心性。"},{"word":"conurbation","ipa":"/ˌkɒnɜːˈbeɪʃn/","tag":"merged built area","definition":"A continuous built-up area formed by several towns growing together; it describes the fabric, not the leading city.","definitionCN":"由数个城镇共同生长成的连片建成区；它描述肌理，而非首位城市。"},{"word":"city","ipa":"/ˈsɪti/","tag":"the general word","definition":"The ordinary term for an urban settlement; metropolis adds scale, centrality and often a historical role.","definitionCN":"城市聚落的一般说法；metropolis 额外带上规模、中心性与常有的历史角色。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real Greek elements, the real polis family and the real fixed phrases.","cn":"正常联想：两个真实的希腊语成分、真实的 polis 词族与真实固定搭配。"},"normal":[{"en":"mētēr 'mother' + polis 'city': the mother city that a colony looked back to.","cn":"mētēr「母亲」+ polis「城」：殖民地回头仰望的母城。"},{"en":"The polis family runs metropolis, metropolitan, metropole, megalopolis, necropolis, cosmopolis.","cn":"polis 词族包括 metropolis、metropolitan、metropole、megalopolis、necropolis、cosmopolis。"},{"en":"Fixed phrases mark the scale: sprawling metropolis, financial metropolis, bustling metropolis.","cn":"固定搭配标出规模：不断铺开的大都市、金融大都市、熙攘的大都市。"},{"en":"The church kept the administrative sense, so a metropolis can still mean an archbishop's seat.","cn":"教会保留了行政义，因此 metropolis 仍可指大主教座所在之城。"},{"en":"Metro is the clipped form of metropolitan, now naming the underground railway.","cn":"metro 是 metropolitan 的截短形式，如今指地下铁路。"}],"abstract":[{"en":"Picture lights that continue past the last road sign and never quite end.","cn":"想象灯光越过最后一块路牌还在继续，始终没有真正结束。"},{"en":"Picture a city that is described by weather because its edges cannot be found.","cn":"想象一座只能用天气来描述的城市，因为找不到它的边缘。"},{"en":"Picture a harbour where every road in the province finally arrives.","cn":"想象一座港口，全省的每条路最后都抵达这里。"}]},"examples":[{"en":"The metropolis absorbs the labour of four surrounding provinces.","cn":"这座大都市吸纳了周边四个省的劳动力。"},{"en":"Long before it was a metropolis, the town was a colonial mother city.","cn":"在这座城成为大都市之前很久，它曾是殖民地的母城。"},{"en":"Planners now speak of the whole delta as one metropolis.","cn":"规划者现在把整个三角洲当作一座大都市来谈。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「metro（母亲）+ polis（城）」——像母亲一样把周边都拢在怀里的那座城 → 大都市","word":"metropolis"},"root":"希腊 mētēr「母亲」+ polis「城」，原指殖民地的母城；经晚期拉丁与法语 métropole 进入英语。polis 更早来源不确定，mētēr 一般认为出自印欧 *mater-。","sensesIntro":{"en":"Eight senses follow one role: a mother city, and that role widens into great size, regional centrality, imperial rule, cultural dominance, church administration, fictional vastness and finally any figurative centre.","cn":"八个义项沿一个角色展开：母城，而这个角色依次扩展为巨大规模、区域中心、宗主统治、文化主导、教会管辖、虚构的浩大，最后是任何比喻意义上的中心。"},"semanticMap":{"core":{"en":"CORE IMAGE: a city that other places point toward, as a child points toward a mother.","cn":"核心意象：别的地方都朝向它的一座城，像一个孩子朝向母亲。"},"chain":["MOTHER CITY","GREAT SIZE","REGIONAL HUB","IMPERIAL CENTRE","CULTURAL CAPITAL","FIGURATIVE CENTRE"],"branches":[{"senses":"01 · 02","en":"THE MOTHER CITY AND ITS SCALE: the original role, then sheer size as a sufficient claim to the name.","cn":"母城与规模：先是原初角色，随后单凭规模就足以取得这个名字。"},{"senses":"03","en":"THE HUB: other places depend on it for transport, trade and administration.","cn":"枢纽：别的地方在交通、贸易与行政上依赖它。"},{"senses":"04 · 06","en":"TWO KINDS OF AUTHORITY: the colonial mother country and the archbishop's seat both rule from a centre.","cn":"两种权威：殖民地母国与大主教座城都从一个中心施行管辖。"},{"senses":"05","en":"CULTURAL DOMINANCE: institutions concentrate there, and the provinces copy its style.","cn":"文化主导：机构集中于此，外地模仿它的风格。"},{"senses":"07 · 08","en":"THE WORD LOOSENED: fiction takes the vastness as a condition, and ordinary speech takes the centre as a metaphor.","cn":"词的松动：虚构把它的大当作一种处境，日常语言则把它的中心当作比喻。"}]},"affixes":{"intro":{"en":"Metropolis is a Greek compound of two very productive elements, and the second of them builds a whole family of city words.","cn":"metropolis 是由两个构词力极强的希腊成分组成的复合词，其中后一个成分建起了一整族「城」的词。"},"latinIntro":{"en":"There is no inherited Latin family: metropolis entered Latin only as a Greek loanword, mainly in church usage, so no genuine Latin cognate exists.","cn":"这里没有拉丁语固有词族：metropolis 只作为希腊借词进入拉丁语，且主要用于教会语境，因此不存在真正的拉丁同族词。"},"items":[{"word":"mētēr","structure":"Greek noun mētēr 'mother'","meaning":"mother","meaningCN":"母亲","example":"The first element names the parent city.","exampleCN":"前一个成分命名的是母城。"},{"word":"polis","structure":"Greek noun polis 'city, citizen-body'","meaning":"city","meaningCN":"城邦","example":"The second element names the city itself.","exampleCN":"后一个成分命名的是城市本身。"},{"word":"metropolis","structure":"mētēr + polis","meaning":"mother city","meaningCN":"母城","example":"The colony sent grain to its metropolis.","exampleCN":"殖民地往母城送粮食。"},{"word":"-itan","structure":"-itēs (Greek) via Latin -itanus (adjective suffix)","meaning":"belonging to","meaningCN":"属于……的","example":"The suffix forms metropolitan from metropolis.","exampleCN":"这个后缀把 metropolis 变成 metropolitan。"},{"word":"megalopolis","structure":"megas 'great' + polis","meaning":"a joined giant urban region","meaningCN":"连片巨型城市区域","example":"The coast has become one megalopolis.","exampleCN":"这条海岸已连成一片巨型城市带。"},{"word":"necropolis","structure":"nekros 'dead' + polis","meaning":"a large cemetery","meaningCN":"大型墓地","example":"The necropolis lies outside the old walls.","exampleCN":"那片墓城位于旧城墙之外。"},{"word":"cosmopolis","structure":"kosmos 'world' + polis","meaning":"a city of many peoples","meaningCN":"多民族共居的世界城","example":"The port grew into a cosmopolis.","exampleCN":"这座港口长成了一座世界城。"},{"word":"metropole","structure":"mētropolis via French métropole","meaning":"the imperial home territory","meaningCN":"宗主国本土","example":"The metropole imported the colony's rubber.","exampleCN":"宗主国进口殖民地的橡胶。"},{"word":"metro","structure":"clipped from metropolitan","meaning":"the city's underground railway","meaningCN":"城市地下铁路","example":"The metro runs until two in the morning.","exampleCN":"地铁运行到凌晨两点。"},{"word":"-ism","structure":"Greek -ismos via Latin -ismus","meaning":"a system or outlook","meaningCN":"体系或心态","example":"Metropolitanism shapes how the capital sees itself.","exampleCN":"大都市心态塑造了首都看待自己的方式。"}],"latinEntries":[]}},{"word":"metropolitan","ipa_uk":"/ˌmetrəˈpɒlɪtən/","ipa_us":"/ˌmetrəˈpɑːlɪtən/","definition_zh":"大都市的；大都市区的；宗主国本土的；大主教辖区的；都市风格的；大都市居民","definition_en":"relating to a metropolis or to the whole urban region around it","core_image":"一张通勤卡能坐地铁、城际铁路和跨区公交，票面印着整个都市圈的轮廓","scene":"一张通勤卡同时能坐地铁、城际铁路和跨区公交，票面印着整个都市圈的范围。The metropolitan area extends far beyond the old city walls.","sceneCN":"这里 metropolitan 指「属于大都市区整体的」（第 2 个义项：涵盖中心城市与其通勤带的整个区域）；句意为这个大都市区远远超出旧城墙的范围。可辨识物件：通勤卡、地铁标志、城际列车、线路图。","pos":[{"tag":"adj.","zh":"大都市的；大都市区的；宗主国本土的；大主教辖区的"},{"tag":"n.","zh":"大都市居民；大都市人（可数，复数 metropolitans）"}],"collocations":[{"phrase":"metropolitan area","zh":"大都市区"},{"phrase":"metropolitan region","zh":"大都市圈"},{"phrase":"metropolitan government","zh":"大都市政府"},{"phrase":"metropolitan police","zh":"首都警察局（英式用法）"},{"phrase":"metropolitan railway","zh":"都市铁路"},{"phrase":"metropolitan elite","zh":"都市精英"}],"forms":[{"label":"形容词原级","form":"metropolitan"},{"label":"形容词比较级","form":"more metropolitan"},{"label":"名词（大都市居民）","form":"metropolitan"},{"label":"名词复数（居民）","form":"metropolitans"},{"label":"相关名词（大都市）","form":"metropolis"},{"label":"相关名词（宗主国本土）","form":"metropole"},{"label":"截短形式（地铁）","form":"metro"}],"derivatives":[{"word":"metropolis","pos":"n.","zh":"希腊 mētropolis（mētēr「母亲」+ polis「城」）→ 由「母城」偏移为「大都市」"},{"word":"metropole","pos":"n.","zh":"metropolis 经法语 métropole → 偏移为「相对殖民地的宗主国本土」"},{"word":"metro","pos":"n.","zh":"metropolitan 的截短 → 偏移为「大都市的地铁系统」"},{"word":"metropolitanism","pos":"n.","zh":"metropolitan + -ism（名词后缀，表体系或心态）→ 偏移为「以大都市为中心的生活方式与心态」"},{"word":"metropolitanize","pos":"v.","zh":"metropolitan + -ize（动词后缀）→ 偏移为「使某地带上大都市的特征」"},{"word":"cosmopolitan","pos":"adj.","zh":"希腊 kosmos「世界」+ politēs「公民」→ 由「世界城」偏移为「具世界主义气质的」"}],"senses":[{"no":"01","title":"Of a metropolis","titleCN":"大都市的","definition":"relating to a metropolis, its institutions or its characteristic life","definitionCN":"与大都市、其机构或其特征性生活相关","example":"Metropolitan wages pull workers in from the smaller towns.","exampleCN":"大都市的工资把周边小城的人吸了进来。","why":"the Greek noun mētropolitēs meant 'of a mother city', and the adjective still points to that leading city.","whyCN":"希腊名词 mētropolitēs 意为「母城的」，这个形容词至今仍指向那座首位城市。"},{"no":"02","title":"Of the whole urban region","titleCN":"大都市区的，涵盖通勤带的","definition":"covering the central city together with the suburbs and commuter belt around it","definitionCN":"涵盖中心城以及其周边郊区与通勤带","example":"The metropolitan area extends far beyond the old city walls.","exampleCN":"这个大都市区远远超出旧城墙的范围。","why":"once people commute across boundaries, the city that matters is the whole travel-to-work region, not the legal city.","whyCN":"一旦人们跨边界通勤，真正起作用的城市是整个通勤区域，而不是法定城市。"},{"no":"03","title":"Of the imperial home country","titleCN":"宗主国本土的","definition":"in colonial usage, belonging to the home country that rules a dependent territory","definitionCN":"在殖民用法中，属于统治附属地的本土国家","example":"Metropolitan troops were sent to hold the port.","exampleCN":"宗主国本土的军队被派去守住那个港口。","why":"this sense keeps the original mother-city relation, viewed from the colony's side.","whyCN":"这一义项保留了原初的母城关系，只是从殖民地一侧来看。"},{"no":"04","title":"Of an archbishop's see","titleCN":"大主教辖区的","definition":"relating to a metropolitan bishop and the province he oversees","definitionCN":"与大主教及其所管辖的教省相关","example":"The metropolitan cathedral stands above the river.","exampleCN":"大主教座堂立在河岸高处。","why":"church administration preserved the administrative sense of the mother city for centuries.","whyCN":"教会行政把母城的行政义保留了许多世纪。"},{"no":"05","title":"City-styled","titleCN":"都市风格的，有都市气派的","definition":"having the polish, scale or manners associated with a great city","definitionCN":"具有与大城市相联的讲究、规模或举止","example":"The hotel markets a metropolitan style to provincial buyers.","exampleCN":"这家酒店向省内买家推销一种都市风格。","why":"a large city sets a standard of polish that others buy, so the adjective can describe a style rather than a place.","whyCN":"大城市定下文雅的标准，别处来买，因此这个形容词可以描述风格而非地点。"},{"no":"06","title":"A city dweller","titleCN":"大都市居民","definition":"a person who lives in a metropolis, especially one identified with its habits","definitionCN":"住在大都市的人，尤指带有其生活习惯的人","example":"The metropolitans rarely see the farms that feed them.","exampleCN":"都市居民很少见到供养他们的农田。","why":"the adjective became a noun by leaving out the word person, a common path in English.","whyCN":"这个形容词省略掉「人」这个词而变成名词，这是英语常见的路径。"},{"no":"07","title":"Of a city transport network","titleCN":"都市交通网络的","definition":"naming rail, bus or police systems that serve a whole conurbation","definitionCN":"指服务整个都市圈的铁路、公交或警务系统","example":"The metropolitan line was built before the suburbs filled in.","exampleCN":"这条都市铁路线在郊区填满之前就建好了。","why":"infrastructure is organized at the scale of the whole region, so the adjective attaches to networks rather than to one city hall.","whyCN":"基础设施按整个区域的尺度组织，因此这个形容词挂在网络上，而不是挂在某一个市政厅上。"},{"no":"08","title":"Of metropolitan government","titleCN":"大都市治理层面的","definition":"relating to an authority that governs a city and its surrounding districts together","definitionCN":"与把城市及其周边区县一并治理的机构相关","example":"Metropolitan planning overrode three local councils.","exampleCN":"大都市层面的规划压过了三个地方议会。","why":"problems such as transport and water cross boundaries, so a single authority is created at that scale.","whyCN":"交通与水这类问题跨越边界，因此要在那个尺度上设立单一机构。"}],"etymology":{"intro":{"en":"Metropolitan comes from Greek mētropolitēs 'of a mother city', through Late Latin metropolitanus and French métropolitain. Dates are approximate.","cn":"metropolitan 来自希腊 mētropolitēs「母城的」，经晚期拉丁 metropolitanus 与法语 métropolitain 进入英语。年代均为约数。"},"items":[{"era":"GREEK METROPOLITES","en":"Mētropolitēs meant 'of a mother city', built on mētēr 'mother', polis 'city' and the suffix -itēs 'belonging to'.","cn":"mētropolitēs 意为「母城的」，由 mētēr「母亲」、polis「城」与后缀 -itēs「属于」构成。"},{"era":"GREEK POLIS","en":"Polis meant 'city, citizen-body'; its deeper origin is uncertain and no single Indo-European source has been accepted.","cn":"polis 意为「城邦、公民群体」；其更早来源不确定，也没有公认的单一印欧语来源。"},{"era":"LATE LATIN","en":"Late Latin metropolitanus was used chiefly of bishops holding a mother see, which fixed the church sense in the West.","cn":"晚期拉丁 metropolitanus 主要用于持有母座的主教，这一用法把教会义固定在了西方。"},{"era":"FRENCH METROPOLITAIN","en":"French métropolitain carried both the church and the city senses into modern languages.","cn":"法语 métropolitain 把教会义与城市义一并带入近代诸语言。"},{"era":"MODERN URBAN SENSE","en":"In the nineteenth and twentieth centuries the adjective was attached to railways, police and planning that served whole conurbations.","cn":"在十九与二十世纪，这个形容词被挂到服务整个都市圈的铁路、警务与规划上。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of polis before Greek is unsettled, and the exact date of the first English use is unrecorded, so any earlier form proposed is a reconstructed form.","cn":"来源不确定：polis 在希腊语之前的来源无定论，英语首见的确切年代也没有记录，因此凡提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one holds the polis family and the words it is swapped with; group two holds adjectives for government and for non-metropolitan places.","cn":"第一组是 polis 词族及常被互换的词；第二组是表治理以及表非都市地区的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"metropolis","ipa":"/məˈtrɒpəlɪs/","tag":"the city itself","definition":"The city as an entity; metropolitan is the adjective for it and for its surrounding region.","definitionCN":"作为实体的城市；metropolitan 是它及其周边区域的形容词。"},{"word":"metropole","ipa":"/ˈmetrəpəʊl/","tag":"imperial home","definition":"The colonial power's home territory; metropolitan in its colonial sense describes what belongs to that home.","definitionCN":"殖民国家的本土；metropolitan 的殖民义即描述属于那个本土的东西。"},{"word":"municipal","ipa":"/mjuːˈnɪsɪpl/","tag":"legal city body","definition":"Of a town as a legal corporation; metropolitan covers a far larger area than any single municipality.","definitionCN":"指作为法人的城镇；metropolitan 覆盖的范围远大于任何单个市镇。"},{"word":"urban","ipa":"/ˈɜːbən/","tag":"city as such","definition":"Of a city in general; metropolitan adds the idea of the leading city and its whole commuter region.","definitionCN":"泛指城市的；metropolitan 额外带上首位城市及其整个通勤区域的意思。"},{"word":"metro","ipa":"/ˈmetrəʊ/","tag":"clipped form","definition":"The shortened form, now mostly naming an underground railway system rather than the region.","definitionCN":"截短形式，如今多指地下铁路系统，而非整个区域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"civic","ipa":"/ˈsɪvɪk/","tag":"citizens and government","definition":"Relating to citizens or city government; it concerns administration, where metropolitan concerns scale and region.","definitionCN":"与公民或市政府相关；它关乎行政，而 metropolitan 关乎规模与区域。"},{"word":"cosmopolitan","ipa":"/ˌkɒzməˈpɒlɪtən/","tag":"world mix","definition":"Made up of many peoples and outlooks; it describes mixture, not size or administration.","definitionCN":"由许多民族与观念混合而成；它描述混合，而非规模或行政。"},{"word":"provincial","ipa":"/prəˈvɪnʃl/","tag":"the opposite","definition":"Of the provinces, often with a tone of narrowness; it is the standard contrast to metropolitan.","definitionCN":"外省的，常带狭窄之气；它是 metropolitan 的标准对照词。"},{"word":"capital","ipa":"/ˈkæpɪtl/","tag":"seat of government","definition":"The city where government sits; metropolitan describes a region, which may contain the capital or not.","definitionCN":"政府所在之城；metropolitan 描述的是一个区域，其中可能有也可能没有首都。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real Greek compound, the real region phrases and the real family.","cn":"正常联想：真实的希腊复合词、真实的区域说法与真实词族。"},"normal":[{"en":"mētēr 'mother' + polis 'city' + -itēs 'belonging to': belonging to the mother city.","cn":"mētēr「母亲」+ polis「城」+ -itēs「属于」：属于母城的。"},{"en":"The family runs metropolis, metropolitan, metropole, metro, metropolitanism, cosmopolitan.","cn":"同族词包括 metropolis、metropolitan、metropole、metro、metropolitanism、cosmopolitan。"},{"en":"Fixed phrases mark the field: metropolitan area, metropolitan government, metropolitan railway.","cn":"固定搭配标出领域：大都市区、大都市政府、都市铁路。"},{"en":"Three scales: urban for the city, metropolitan for the region, provincial for everything outside.","cn":"三个尺度：urban 指城市，metropolitan 指整个区域，provincial 指外面的一切。"},{"en":"The church sense survives in titles such as metropolitan bishop, a bishop of a mother see.","cn":"教会义仍活在 metropolitan bishop 这类称谓里，指母座主教。"}],"abstract":[{"en":"Picture a ticket that works on every kind of transport inside one drawn ring.","cn":"想象一张票，在一个画出的圈内所有交通工具上都能用。"},{"en":"Picture a boundary drawn around commuters rather than around walls.","cn":"想象一条边界围着通勤者画，而不是围着城墙画。"},{"en":"Picture a single office that must answer for three town halls at once.","cn":"想象一个办公室要同时为三个市政厅负责。"}]},"examples":[{"en":"Metropolitan growth has outpaced the water authority's planning.","cn":"大都市的增长已经超过了水务部门的规划。"},{"en":"The metropolitan elite rarely sends its children to local schools.","cn":"都市精英很少把孩子送进本地学校。"},{"en":"In colonial records, metropolitan goods were taxed less than local ones.","cn":"在殖民档案里，宗主国本土货物的税比本地货物低。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「metro（母亲、大城）+ politan（属于……的）」——属于那座母城及其整个周边的 → 大都市的","word":"metropolitan"},"root":"希腊 mētropolitēs「母城的」（mētēr「母亲」+ polis「城」+ -itēs「属于」），经晚期拉丁 metropolitanus 与法语 métropolitain；polis 更早来源不确定。","sensesIntro":{"en":"Eight senses follow one scale: the leading city, then the whole commuter region, then the imperial home, the church province, a city style, its residents, its networks and finally its government.","cn":"八个义项沿一个尺度展开：先是首位城市，再是整个通勤区域，随后是宗主国本土、教省、都市风格、都市居民、都市网络，最后是都市治理。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ring drawn around a city wide enough to contain everyone who comes into it to work.","cn":"核心意象：围着城市画的一个圈，宽到足以容纳所有进来工作的人。"},"chain":["MOTHER CITY","COMMUTER REGION","IMPERIAL HOME","CHURCH PROVINCE","CITY STYLE","REGIONAL GOVERNMENT"],"branches":[{"senses":"01 · 02","en":"CITY AND REGION: the leading city first, then the whole travel-to-work area that depends on it.","cn":"城市与区域：先是首位城市，再是依赖它的整个通勤区域。"},{"senses":"03 · 04","en":"TWO ADMINISTRATIVE HOMES: the colonial mother country and the archbishop's province both rule from a centre.","cn":"两个行政母体：殖民地母国与大主教教省都从一个中心施行管辖。"},{"senses":"05","en":"STYLE BORROWED FROM THE CENTRE: manners and scale marketed as belonging to the great city.","cn":"从中心借来的风格：被当作属于大城市的举止与气派在市场上流通。"},{"senses":"06","en":"THE PEOPLE: those who live at that scale, and are identified with its habits.","cn":"人：在那个尺度上生活、并被认作带有其习惯的人。"},{"senses":"07 · 08","en":"NETWORKS AND GOVERNMENT: transport and policing are organized region-wide, and so is the authority above the councils.","cn":"网络与治理：交通与警务按整个区域组织，压在议会之上的机构也是如此。"}]},"affixes":{"intro":{"en":"The adjective is a Greek compound plus a Latin adjective ending, and each element still builds words in English.","cn":"这个形容词是一个希腊复合词加一个拉丁形容词词尾，每个成分在英语中仍在构词。"},"latinIntro":{"en":"Latin took mētropolitēs as metropolitanus, a church adjective; there is no inherited Latin root family here, only a Greek compound dressed in a Latin ending.","cn":"拉丁语把 mētropolitēs 吸收为教会形容词 metropolitanus；这里没有拉丁固有词根词族，只有一个穿上拉丁词尾的希腊复合词。"},"items":[{"word":"mētēr","structure":"Greek noun mētēr 'mother'","meaning":"mother","meaningCN":"母亲","example":"The first element marks the parent city.","exampleCN":"第一个成分标记母城。"},{"word":"polis","structure":"Greek noun polis 'city'","meaning":"city","meaningCN":"城邦","example":"The second element names the city.","exampleCN":"第二个成分命名城市。"},{"word":"-ites","structure":"Greek suffix -itēs 'belonging to'","meaning":"one belonging to","meaningCN":"属于……的人或物","example":"The suffix makes an adjective of belonging.","exampleCN":"这个后缀构成表归属的形容词。"},{"word":"-an","structure":"Latin -anus (adjective ending)","meaning":"of or belonging to","meaningCN":"属于……的","example":"The ending carried the word into Latin.","exampleCN":"这个词尾把这个词带进了拉丁语。"},{"word":"metropolis","structure":"mētēr + polis","meaning":"mother city","meaningCN":"母城","example":"The region looks to its metropolis.","exampleCN":"这个区域仰赖它的大都市。"},{"word":"metropole","structure":"mētropolis via French","meaning":"imperial home territory","meaningCN":"宗主国本土","example":"The metropole set the tariffs.","exampleCN":"宗主国本土定下了关税。"},{"word":"megalopolis","structure":"megas 'great' + polis","meaning":"joined giant urban region","meaningCN":"连片巨型城市区域","example":"The corridor is now a megalopolis.","exampleCN":"这条走廊如今已是巨型城市带。"},{"word":"cosmopolitan","structure":"kosmos 'world' + politēs 'citizen'","meaning":"belonging to the whole world","meaningCN":"属于整个世界的","example":"The port has a cosmopolitan population.","exampleCN":"这座港口的人口来自世界各地。"},{"word":"metro","structure":"clipped from metropolitan","meaning":"the underground railway","meaningCN":"地下铁路","example":"The metro closes at midnight.","exampleCN":"地铁午夜收班。"},{"word":"-ism","structure":"Greek -ismos via Latin -ismus","meaning":"an outlook or system","meaningCN":"心态或体系","example":"Metropolitanism can blind planners to the provinces.","exampleCN":"都市心态会让规划者看不见外省。"}],"latinEntries":[]}},{"word":"city-state","ipa_uk":"/ˈsɪti steɪt/","ipa_us":"/ˈsɪti steɪt/","definition_zh":"城邦；独立城市国家；古希腊城邦；意大利城邦；现代城市国家；以城市为核心的政体","definition_en":"a state whose territory consists of a single city and its surrounding land","core_image":"山顶卫城只剩石阶与柱础，山脚下却是另一个国家的海关","scene":"山顶的卫城里只剩石阶与柱础，山脚下却是另一个国家的海关。The ancient city-state ruled a valley no wider than a day's walk.","sceneCN":"这里 city-state 指「以一个城市及其周边土地构成的独立国家」（第 1 个义项：城邦这种政体）；句意为这个古代城邦统治着一座一天就能走完的山谷。可辨识物件：卫城石阶、柱础、海关岗亭、山谷。","pos":[{"tag":"n.","zh":"城邦；城市国家（可数，复数 city-states）"}],"collocations":[{"phrase":"ancient Greek city-state","zh":"古希腊城邦"},{"phrase":"independent city-state","zh":"独立城邦"},{"phrase":"city-state system","zh":"城邦体系"},{"phrase":"Italian city-states","zh":"意大利诸城邦"},{"phrase":"modern city-state","zh":"现代城市国家"},{"phrase":"the rise of the city-state","zh":"城邦的兴起"}],"forms":[{"label":"单数","form":"city-state"},{"label":"复数","form":"city-states"},{"label":"定语用法","form":"city-state"},{"label":"前项名词（城市）","form":"city"},{"label":"后项名词（国家）","form":"state"},{"label":"同义说法（意大利城邦）","form":"city republic"}],"derivatives":[{"word":"city","pos":"n.","zh":"拉丁 civitas「公民共同体」→ 由「公民身份」偏移为「公民共同居住的地方」"},{"word":"civic","pos":"adj.","zh":"civis「公民」+ -ic（形容词后缀）→ 偏移为「与公民和城市相关的」"},{"word":"citizen","pos":"n.","zh":"civitas 经法语→ 偏移为「拥有公民身份的人」"},{"word":"citizenship","pos":"n.","zh":"citizen + -ship（状态名词后缀）→ 偏移为「公民身份与义务」"},{"word":"state","pos":"n.","zh":"拉丁 status「站立的状态」→ 由「站姿」偏移为「稳定的政治共同体」"},{"word":"stateless","pos":"adj.","zh":"state + -less（缺乏后缀）→ 偏移为「没有国籍归属的」"},{"word":"statesman","pos":"n.","zh":"state + man（人）→ 偏移为「处理国家事务的人」"}],"senses":[{"no":"01","title":"A state made of one city","titleCN":"以一个城市构成的城邦","definition":"a sovereign state whose territory is a single city together with its hinterland","definitionCN":"领土由一座城市及其腹地组成的独立国家","example":"The ancient city-state ruled a valley no wider than a day's walk.","exampleCN":"这个古代城邦统治着一座一天就能走完的山谷。","why":"city names the settlement and state names the political body, so the compound names a politics that coincides with one town.","whyCN":"city 指聚落，state 指政治体，因此这个复合词命名的是与一座城镇重合的政治体。"},{"no":"02","title":"The Greek polis","titleCN":"古希腊城邦","definition":"the classical Greek polis, a city with its own laws, army and citizenship","definitionCN":"拥有自己的法律、军队与公民身份的古希腊城邦","example":"Each Greek city-state kept its own calendar and coinage.","exampleCN":"每个希腊城邦都有自己的历法与钱币。","why":"the compound was coined to translate polis, which English otherwise borrowed as a separate term.","whyCN":"这个复合词是为翻译 polis 而造的，英语另又把 polis 直接借了进来。"},{"no":"03","title":"The Italian city republics","titleCN":"意大利城邦共和国","definition":"the self-governing commercial cities of late medieval and Renaissance Italy","definitionCN":"中世纪晚期与文艺复兴时期意大利自治的商业城市","example":"The Italian city-states financed their wars with trade.","exampleCN":"意大利城邦用贸易来支撑战争。","why":"wealthy ports governed themselves and behaved like states, which made them the model case for the term.","whyCN":"富裕的港口自我治理、行事如国家，因此成了这个术语的典型例子。"},{"no":"04","title":"A modern city-state","titleCN":"现代城市国家","definition":"a present-day sovereign microstate that is essentially one city, such as Singapore","definitionCN":"本质上就是一座城市的当代主权微型国家，如新加坡","example":"The modern city-state survives by trading rather than by farming.","exampleCN":"现代城市国家靠贸易而不是靠农耕存续。","why":"decolonization left a few port cities sovereign, and the old term was the obvious fit.","whyCN":"去殖民化让少数港口城市成为主权体，旧术语正好合用。"},{"no":"05","title":"A city-led polity","titleCN":"以城市为核心政体的政权","definition":"any polity in which the governing centre is a city rather than a territorial capital","definitionCN":"治理中心是城市而非领土型都城的任何政体","example":"Some leagues were city-states in all but name.","exampleCN":"有些同盟实际上就是城邦，只是没有用这个名字。","why":"the term can be used by analogy whenever a city, not a landed realm, is the political unit.","whyCN":"只要政治单位是城市而非有土地的王国，这个术语就可以按类比使用。"},{"no":"06","title":"A system of city-states","titleCN":"城邦体系与城邦间关系","definition":"the pattern of separate cities coexisting, competing and allying within one region","definitionCN":"同一区域内多个城市并存、竞争并结盟的格局","example":"The city-state system kept the peninsula divided for centuries.","exampleCN":"城邦体系让这个半岛分裂了许多世纪。","why":"when many such units coexist, the compound shifts from one state to a system of states.","whyCN":"当许多这样的单位并存，这个复合词就从单个国家转到国家体系。"},{"no":"07","title":"A small self-governing entity","titleCN":"小而自主的实体（比喻义）","definition":"figuratively, a small organization that governs itself like a sovereign city","definitionCN":"比喻说法，指像主权城市一样自我管理的小型组织","example":"The research institute behaves like a city-state inside the university.","exampleCN":"这个研究所在大学内部表现得像一个城邦。","why":"if a state is a body that rules itself, any small self-ruling unit can borrow the image.","whyCN":"如果国家是自我治理的团体，任何小型自治单位都可以借用这个意象。"},{"no":"08","title":"Civic culture of a city-state","titleCN":"城邦的公民文化与认同","definition":"the civic identity and public institutions that a city-state produces in its citizens","definitionCN":"城邦在其公民身上产生的公民认同与公共制度","example":"The city-state left a civic culture of public debate.","exampleCN":"这个城邦留下了一种公开辩论的公民文化。","why":"when citizenship is bounded by one city, civic identity becomes unusually sharp.","whyCN":"当公民身份以一座城为界，公民认同会变得格外鲜明。"}],"etymology":{"intro":{"en":"City-state is an English compound of city, from Latin civitas, and state, from Latin status; it was formed as a calque of Greek polis. Dates are approximate.","cn":"city-state 是英语复合词，由来自拉丁 civitas 的 city 与来自拉丁 status 的 state 组成；它是为对应希腊 polis 而造的仿译词。年代均为约数。"},"items":[{"era":"LATIN CIVITAS","en":"Civitas named a citizen-body and, by extension, the town where it lived; city came into English through French cité.","cn":"civitas 指公民共同体，进而指其居住的城镇；city 经法语 cité 进入英语。"},{"era":"LATIN STATUS","en":"Status meant 'standing, position, condition', from stare 'to stand'; state first meant a condition before it meant a polity.","cn":"status 意为「站姿、位置、状况」，来自 stare「站立」；state 先指状态，后指政治体。"},{"era":"GREEK POLIS","en":"Polis named the Greek city and its citizen community, a unit that was at once a town and a state.","cn":"polis 指希腊的城市及其公民共同体，是城镇与国家合一的单位。"},{"era":"CALQUE IN POLITICAL WRITING","en":"Modern political writing coined city-state to render polis, since neither city nor state alone covered the unit.","cn":"近代政治写作造出 city-state 来对译 polis，因为单用 city 或 state 都无法涵盖这个单位。"},{"era":"MODERN REVIVAL","en":"The term returned to general use when Singapore, Hong Kong and other small territories were discussed as sovereign or quasi-sovereign cities.","cn":"当新加坡、香港等地被作为主权或半主权的城市讨论时，这个词回到了一般用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first use of the compound is unrecorded, and the origin of polis before Greek is unsettled, so any earlier form proposed is a reconstructed form.","cn":"来源不确定：这个复合词的确切首见没有记录，polis 在希腊语之前的来源亦无定论，因此提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the compound from city territorial words it is built from or confused with; group two holds other small-sovereignty terms.","cn":"第一组把这一复合词与构成它或易混的城市领土词分开；第二组是其他小主权实体术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"city","ipa":"/ˈsɪti/","tag":"settlement only","definition":"A large town; it says nothing about sovereignty, which is exactly what the compound adds.","definitionCN":"一座大城镇；它不含主权之意，而主权正是这个复合词所加的部分。"},{"word":"state","ipa":"/steɪt/","tag":"polity only","definition":"A political community under one government; it may span many cities, so it does not imply one city.","definitionCN":"受一个政府管辖的政治共同体；它可以横跨多座城市，因此并不含「一座城」之意。"},{"word":"nation-state","ipa":"/ˈneɪʃn steɪt/","tag":"people plus state","definition":"A state legitimated by a shared nation; city-states rest on civic rather than ethnic unity.","definitionCN":"以共享民族为合法性基础的国家；城邦靠的是公民团结，而非族群团结。"},{"word":"city republic","ipa":"/ˈsɪti rɪˈpʌblɪk/","tag":"republican form","definition":"A self-governing city with republican institutions; it is one kind of city-state, not the general term.","definitionCN":"拥有共和制度的自治城市；它是城邦的一种，而非一般说法。"},{"word":"polis","ipa":"/ˈpɒlɪs/","tag":"the Greek term","definition":"The Greek word for a city and its citizen-body; English uses it for the classical case specifically.","definitionCN":"希腊语指城市及其公民共同体的词；英语用它专指古典情形。"}]},{"heading":"NEAR MEANING","entries":[{"word":"microstate","ipa":"/ˈmaɪkrəʊsteɪt/","tag":"by size","definition":"A very small sovereign state; it may contain several towns, so size alone does not make a city-state.","definitionCN":"面积极小的主权国家；它可能含数座城镇，因此单凭面积并不构成城邦。"},{"word":"principality","ipa":"/ˌprɪnsəˈpæləti/","tag":"ruled by a prince","definition":"A territory ruled by a prince; the criterion is the ruler, not the coincidence of city and state.","definitionCN":"由亲王统治的领地；其标准是统治者，而不是城市与国家的重合。"},{"word":"municipality","ipa":"/mjuːˌnɪsɪˈpæləti/","tag":"local government","definition":"A town or district with its own local government; it is subordinate, where a city-state is sovereign.","definitionCN":"拥有本地政府的城镇或区；它是下级单位，而城邦是主权体。"},{"word":"sovereignty","ipa":"/ˈsɒvrənti/","tag":"the key property","definition":"Supreme authority within a territory; a city-state is defined by holding it, however small the territory.","definitionCN":"对某领土的最高权力；城邦的定义就在于持有它，无论领土多小。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real Latin halves, the Greek model and real fixed phrases.","cn":"正常联想：两个真实的拉丁部分、希腊原型与真实固定搭配。"},"normal":[{"en":"city from civitas 'citizen-body', state from status 'standing': a citizen-body that stands as a polity.","cn":"city 出自 civitas「公民共同体」，state 出自 status「站立」：一个立为政治体的公民共同体。"},{"en":"The compound translates polis, which was city and state at once.","cn":"这个复合词对译 polis，而 polis 同时是城与国家。"},{"en":"Fixed phrases mark the cases: ancient Greek city-state, Italian city-states, modern city-state.","cn":"固定搭配标出实例：古希腊城邦、意大利诸城邦、现代城市国家。"},{"en":"The family runs city, civic, citizen, citizenship, state, stateless, statesman.","cn":"同族词包括 city、civic、citizen、citizenship、state、stateless、statesman。"},{"en":"A polis was small enough to walk across, and that smallness is part of the idea.","cn":"一个 polis 小到可以徒步走完，这种小正是这个概念的一部分。"}],"abstract":[{"en":"Picture a hilltop with only column bases left, and a customs booth at the foot of it.","cn":"想象一座山顶只剩柱础，而山脚立着一个海关岗亭。"},{"en":"Picture a wall that is also a border, and a market that is also a treasury.","cn":"想象一道墙同时是国界，一个市场同时是国库。"},{"en":"Picture a town small enough that every citizen could hear one speaker.","cn":"想象一座小城，小到每个公民都能听见同一个人说话。"}]},"examples":[{"en":"The city-state minted its own coins and kept its own army.","cn":"这个城邦自己铸钱，也保留自己的军队。"},{"en":"Historians compare the Italian city-states with the Greek polis.","cn":"历史学者把意大利城邦与希腊城邦作比较。"},{"en":"A modern city-state must import nearly everything it eats.","cn":"现代城市国家几乎必须进口它所吃的一切。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「city（城市）+ state（国家）」——一座城就是一个国 → 城邦、城市国家","word":"city-state"},"root":"city（拉丁 civitas「公民共同体」，来自 civis「公民」）+ state（拉丁 status「站立的状态」，来自 stare「站立」）；复合词为对译希腊 polis 而造。","sensesIntro":{"en":"Eight senses follow one coincidence: a city that is also a state, and the same coincidence appears in classical Greece, Renaissance Italy, modern microstates, city-led leagues, systems of rivals, small self-ruling bodies and finally in civic culture.","cn":"八个义项沿一个重合展开：一座同时是国家的城，这个重合依次出现在古典希腊、文艺复兴意大利、现代微型国家、以城为核心的联盟、竞争共存的体系、小型自治体，最后落在公民文化上。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall that is at once a city boundary and a national border.","cn":"核心意象：一道墙，同时是城市边界与国界。"},"chain":["CITY EQUALS STATE","GREEK POLIS","ITALIAN REPUBLICS","MODERN MICROSTATE","SYSTEM OF RIVALS","CIVIC CULTURE"],"branches":[{"senses":"01 · 02","en":"THE BASIC COINCIDENCE: one city holding sovereignty, first as a definition and then as the Greek case.","cn":"基本重合：一座城掌握主权，先是定义，随后是希腊实例。"},{"senses":"03 · 04","en":"TWO HISTORICAL FORMS: the commercial republics of Italy and the surviving microstates of today.","cn":"两种历史形态：意大利的商业共和国与今天的存续微型国家。"},{"senses":"05 · 07","en":"THE ANALOGY: any polity or organization whose ruling unit is one city can borrow the name.","cn":"类比：任何以一座城为治理单位的政体或组织都可以借用这个名字。"},{"senses":"06","en":"MANY UNITS AT ONCE: the term shifts from one state to the system they form together.","cn":"多个单位并存：这个词从单个国家转到它们共同构成的体系。"},{"senses":"08","en":"THE CIVIC RESULT: bounded citizenship produces an unusually sharp public culture.","cn":"公民结果：有边界的公民身份产生一种格外鲜明的公共文化。"}]},"affixes":{"intro":{"en":"The compound is two Latin-derived English nouns, and each half brings a family of political and civic words.","cn":"这个复合词由两个源自拉丁语的英语名词组成，每一半都带来一族政治与公民词汇。"},"latinIntro":{"en":"Both halves are Latin: civitas and civis supply city and civic, status and stare supply state and status.","cn":"两半都来自拉丁语：civitas 与 civis 提供 city 与 civic，status 与 stare 提供 state 与 status。"},"items":[{"word":"civis","structure":"civis, civis (m./f., third declension)","meaning":"citizen","meaningCN":"公民","example":"The noun named membership in a community.","exampleCN":"这个名词指共同体内的成员身份。"},{"word":"civitas","structure":"civitas, civitatis (f., third declension)","meaning":"citizen-body, city","meaningCN":"公民共同体；城市","example":"The word covered people and place at once.","exampleCN":"这个词同时覆盖人与地方。"},{"word":"-ic","structure":"-icus (Latin adjective suffix)","meaning":"relating to","meaningCN":"与……相关的","example":"Civic duties belong to citizens.","exampleCN":"公民义务属于公民。"},{"word":"-ship","structure":"Old English -scipe (state suffix)","meaning":"the condition of","meaningCN":"……的状态","example":"Citizenship is a legal condition.","exampleCN":"公民身份是一种法律状态。"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"standing, condition","meaningCN":"站立的状态；状况","example":"Status first named how one stood.","exampleCN":"status 最初指人如何站立。"},{"word":"stare","structure":"stare, steti, statum (Latin verb)","meaning":"to stand","meaningCN":"站立","example":"The verb supplies the idea of standing firm.","exampleCN":"这个动词提供「站稳」的意思。"},{"word":"state","structure":"status via Old French estat","meaning":"a standing polity","meaningCN":"立住的政治体","example":"The state claims the monopoly of law.","exampleCN":"国家声称拥有法律的垄断权。"},{"word":"-less","structure":"Old English -leas (privative suffix)","meaning":"without","meaningCN":"没有","example":"Stateless people lack a legal home.","exampleCN":"无国籍者没有法律归属。"},{"word":"polis","structure":"Greek polis (city, citizen-body)","meaning":"the model behind the compound","meaningCN":"复合词背后的原型","example":"The polis united town and state.","exampleCN":"polis 把城镇与国家合为一体。"},{"word":"city","structure":"civitas via French cité","meaning":"a walled town","meaningCN":"有城墙的城镇","example":"The city grew beyond its walls.","exampleCN":"城市长出了它的城墙。"}],"latinEntries":[{"word":"civitas","structure":"civitas, civitatis (f., third declension)","meaning":"citizen-body, city","meaningCN":"公民共同体；城市"},{"word":"civis","structure":"civis, civis (m./f., third declension)","meaning":"citizen","meaningCN":"公民"},{"word":"status","structure":"status, status (m., fourth declension)","meaning":"standing, condition","meaningCN":"站立的状态；状况"},{"word":"stare","structure":"stare, steti, statum (verb, first conjugation)","meaning":"to stand","meaningCN":"站立"}]}},{"word":"city planning","ipa_uk":"/ˈsɪti ˈplænɪŋ/","ipa_us":"/ˈsɪti ˈplænɪŋ/","definition_zh":"城市规划；城市总体规划；土地利用规划；交通与基础设施规划；城市空间设计","definition_en":"the professional activity of deciding how land, transport and buildings in a city should be arranged","core_image":"会议桌上一张街区图，红线标出将来的轻轨，绿色块留给公园","scene":"会议桌上摊开一张街区图，红线标出将来的轻轨，绿色块留给公园。City planning decides where the rail line will cut through the old quarter.","sceneCN":"这里 city planning 指「对城市交通与基础设施走向所作的专业安排」（第 4 个义项：交通与基础设施规划）；句意为城市规划决定了轻轨将怎样穿过老城区。可辨识物件：街区图、红线、绿色块、会议桌。","pos":[{"tag":"n.","zh":"城市规划（不可数，指专业活动或学科）"}],"collocations":[{"phrase":"city planning department","zh":"城市规划部门"},{"phrase":"city planning office","zh":"城市规划办公室"},{"phrase":"city planning policy","zh":"城市规划政策"},{"phrase":"city planning process","zh":"城市规划流程"},{"phrase":"city planning regulations","zh":"城市规划法规"},{"phrase":"city planning map","zh":"城市规划图"}],"forms":[{"label":"不可数名词","form":"city planning"},{"label":"定语用法","form":"city-planning"},{"label":"从业者（城市规划师）","form":"city planner"},{"label":"同义说法（更常写）","form":"urban planning"},{"label":"相关名词（规划）","form":"planning"},{"label":"相关名词（总体图）","form":"master plan"}],"derivatives":[{"word":"plan","pos":"n./v.","zh":"基础词 plan 去掉 -ing 后的形式，来自拉丁 planum「平面」→ 由「平面图」偏移为「预先安排的方案」"},{"word":"planner","pos":"n.","zh":"plan + -er（施事后缀）→ 偏移为「做规划的人」"},{"word":"planning","pos":"n.","zh":"plan + -ing（动名词后缀）→ 偏移为「规划这一活动」"},{"word":"planned","pos":"adj.","zh":"plan + -ed（过去分词作定语）→ 偏移为「按计划建成的」"},{"word":"unplanned","pos":"adj.","zh":"un-（否定前缀）+ planned → 偏移为「未经规划的」"},{"word":"cityscape","pos":"n.","zh":"city + -scape（景观后缀，仿 landscape）→ 偏移为「城市景观整体」"},{"word":"zoning","pos":"n.","zh":"zone + -ing（动名词后缀）→ 偏移为「按用途划分土地的制度」"}],"senses":[{"no":"01","title":"The profession","titleCN":"城市规划这一专业与学科","definition":"the profession and academic field that studies how cities should be laid out","definitionCN":"研究城市应如何布局的专业与学科","example":"City planning grew out of public health surveys of overcrowded housing.","exampleCN":"城市规划是从对拥挤住房的公共卫生调查中生长出来的。","why":"planning names the activity of arranging in advance, and city names its object, so the phrase is the profession of arranging cities.","whyCN":"planning 指预先安排的活动，city 指其对象，因此这个短语就是安排城市的专业。"},{"no":"02","title":"A master plan","titleCN":"城市总体规划","definition":"the single long-range document that sets a city's intended shape for decades","definitionCN":"为城市数十年形态定下意图的长远文件","example":"The master plan of city planning reserved a green belt in the north.","exampleCN":"城市规划的总体方案在北部保留了一条绿带。","why":"a profession needs one binding document, and the phrase shifts from the activity to that document.","whyCN":"一个专业需要一份有约束力的文件，于是这个短语从活动转指那份文件。"},{"no":"03","title":"Land-use planning","titleCN":"土地利用规划","definition":"the allocation of parcels to housing, industry, farming or open space","definitionCN":"把地块分配给住房、工业、农业或空地","example":"City planning decides which fields may become factories.","exampleCN":"城市规划决定了哪些田地可以变成工厂。","why":"land is the scarce thing a city allocates, so use-allocation is the core of the craft.","whyCN":"土地是城市分配中最稀缺的东西，所以用途分配就成了这门行当的核心。"},{"no":"04","title":"Transport and infrastructure planning","titleCN":"交通与基础设施规划","definition":"the routing of roads, rail, water and power before they are built","definitionCN":"在建造之前安排道路、铁路、供水与电力的走向","example":"City planning decides where the rail line will cut through the old quarter.","exampleCN":"城市规划决定了轻轨将怎样穿过老城区。","why":"networks last longer than buildings, so their routes are fixed first and constrain everything after.","whyCN":"管网比建筑存续更久，所以它们的走向先被定下，并约束其后的一切。"},{"no":"05","title":"Urban design and layout","titleCN":"城市设计与空间布局","definition":"the shaping of streets, blocks and public space at the scale of the neighbourhood","definitionCN":"以街区尺度塑造街道、地块与公共空间","example":"Good city planning makes a square that people actually cross.","exampleCN":"好的城市规划会做出人们真的愿意穿过的广场。","why":"planning at drawing scale becomes design, where dimensions and frontages decide how a place feels.","whyCN":"规划落到图纸尺度就成了设计，尺寸与临街面决定一个地方给人的感受。"},{"no":"06","title":"Neighbourhood planning","titleCN":"社区与街区规划","definition":"planning carried out at the level of a district with resident participation","definitionCN":"在有居民参与的区级层面进行的规划","example":"City planning at this level begins with the school run.","exampleCN":"这一层面的城市规划从送孩子上学的那条路开始。","why":"national and city-wide rules must be applied somewhere, and that somewhere is a neighbourhood.","whyCN":"全国与全市的规则总要落到某个具体地方，而那个地方就是街区。"},{"no":"07","title":"Rules and regulation","titleCN":"规划政策与法规","definition":"the ordinances, permits and zoning rules that give plans legal force","definitionCN":"赋予规划法律效力的条例、许可与分区规则","example":"City planning without enforcement is only a drawing.","exampleCN":"没有执行的规划只是一张图。","why":"a plan changes nothing until it is written into law, so the phrase covers the rule-making as well.","whyCN":"规划不写进法律就什么都改变不了，因此这个短语也涵盖规则的制定。"},{"no":"08","title":"Planning for renewal","titleCN":"城市更新中的规划","definition":"the replanning of districts that are already built, often with relocation involved","definitionCN":"对已建成城区重新规划，常涉及搬迁","example":"City planning here means deciding who must move before the blocks come down.","exampleCN":"这里的城市规划意味着在街区被拆掉之前决定谁必须搬走。","why":"when there is no new land, planning becomes a negotiation over existing space and existing residents.","whyCN":"没有新土地时，规划就变成围绕既有空间与既有居民的协商。"}],"etymology":{"intro":{"en":"City planning joins city, from Latin civitas, to planning, from plan, whose Latin source is planum 'flat surface'. Dates are approximate.","cn":"city planning 把来自拉丁 civitas 的 city 与来自 plan 的 planning 组合起来，而 plan 的拉丁来源是 planum「平面」。年代均为约数。"},"items":[{"era":"LATIN CIVITAS","en":"Civitas named a citizen-body and its town; city entered English through French cité.","cn":"civitas 指公民共同体及其城镇；city 经法语 cité 进入英语。"},{"era":"LATIN PLANUM","en":"Planum meant 'a flat surface', from planus 'flat, level'. A plan was first a drawing on a flat sheet.","cn":"planum 意为「平面」，来自 planus「平的、平坦的」。plan 最初指画在平面纸上的一张图。"},{"era":"FRENCH PLAN","en":"French plan carried both the drawing and the scheme senses into English.","cn":"法语 plan 把「图」与「方案」两层意思一并带入英语。"},{"era":"NINETEENTH-CENTURY CRAFT","en":"City planning emerged as a named activity when industrial cities began to be laid out with sewers, parks and bylaws.","cn":"当工业城市开始被按排水、公园与附例来布局时，city planning 才作为一项有名字的活动出现。"},{"era":"PROFESSIONAL TERM","en":"In the twentieth century the phrase named a licensed profession and a municipal department, not only a drawing.","cn":"到二十世纪，这个短语指一门有执照的专业与一个市政部门，而不只是一张图。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact first use of the phrase is unrecorded, and the deeper origin of planus is unsettled, so any earlier form proposed is a reconstructed form.","cn":"来源不确定：这个短语的确切首见没有记录，planus 的更早来源亦无定论，因此提出的更早形式均属重构形式。"}]},"similar":{"note":{"en":"Group one separates the phrase from its near-synonyms and from the documents it produces; group two holds the practices it overlaps with.","cn":"第一组把这一短语与近义说法以及它产出的文件分开；第二组是与之重叠的实践。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"urban planning","ipa":"/ˈɜːbən ˈplænɪŋ/","tag":"the usual synonym","definition":"The commoner term for the same profession; it is wider because it covers regions as well as cities.","definitionCN":"同一专业更常见的说法；它更宽，因为同时涵盖区域与城市。"},{"word":"city plan","ipa":"/ˈsɪti plæn/","tag":"the document","definition":"The document or drawing produced; planning is the activity, a plan is its output.","definitionCN":"所产出的文件或图纸；规划是活动，方案是产出。"},{"word":"master plan","ipa":"/ˈmɑːstə plæn/","tag":"one instrument","definition":"The long-range framework document; it is one product of city planning, not the whole field.","definitionCN":"长远的框架文件；它是城市规划的一项产出，而非整个领域。"},{"word":"zoning","ipa":"/ˈzəʊnɪŋ/","tag":"one legal tool","definition":"The division of land into use districts; zoning is a tool that planning uses, not its equal.","definitionCN":"把土地划为用途分区；分区是规划所用的一种工具，并不等同于规划。"},{"word":"urban design","ipa":"/ˈɜːbən dɪˈzaɪn/","tag":"the physical craft","definition":"The design of buildings, streets and spaces as a coherent whole; it is the three-dimensional side of planning.","definitionCN":"把建筑、街道与空间作为整体来设计；它是规划的三维一面。"}]},{"heading":"NEAR MEANING","entries":[{"word":"land-use planning","ipa":"/ˈlænd juːs ˈplænɪŋ/","tag":"one branch","definition":"The allocation of land to uses; it is a core branch of city planning rather than a synonym.","definitionCN":"把土地分配给各类用途；它是城市规划的核心分支，而非同义词。"},{"word":"redevelopment","ipa":"/ˌriːdɪˈveləpmənt/","tag":"building after the plan","definition":"Rebuilding land that was already built on; it follows a plan and is not the planning itself.","definitionCN":"对已建成土地的再建；它依规划而行，本身不是规划。"},{"word":"infrastructure planning","ipa":"/ˈɪnfrəstrʌktʃə ˈplænɪŋ/","tag":"networks first","definition":"The routing of roads, water and power; it is one specialized branch of the wider field.","definitionCN":"安排道路、供水与电力的走向；它是更宽领域中的一个专门分支。"},{"word":"policy","ipa":"/ˈpɒləsi/","tag":"the rules","definition":"A settled course of action adopted by an authority; planning produces policy but also responds to it.","definitionCN":"权威采纳的既定行动方向；规划既产出政策，也受政策约束。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves, the Latin source of plan and the real instruments.","cn":"正常联想：两个真实的部分、plan 的拉丁来源与真实工具名称。"},"normal":[{"en":"planum 'flat surface' gives plan: a scheme is first a drawing on a flat sheet.","cn":"planum「平面」给出 plan：方案最初是画在平面纸上的一张图。"},{"en":"The family runs plan, planner, planning, planned, unplanned, zoning, cityscape.","cn":"同族词包括 plan、planner、planning、planned、unplanned、zoning、cityscape。"},{"en":"Fixed phrases mark the office: city planning department, city planning policy, city planning map.","cn":"固定搭配标出机构：城市规划部门、城市规划政策、城市规划图。"},{"en":"The commoner synonym is urban planning, which also covers regional scales.","cn":"更常见的同义说法是 urban planning，它还覆盖区域尺度。"},{"en":"A plan without enforcement is only a drawing: policy turns it into law.","cn":"没有执行的方案只是一张图：政策把它变成法律。"}],"abstract":[{"en":"Picture a red line drawn across a map years before anyone digs the trench.","cn":"想象一条红线在地图上画下多年之后，才有人去挖那条沟。"},{"en":"Picture a green square that forbids a building that has not yet been imagined.","cn":"想象一个绿色方块，禁止了一栋尚未被想象出来的建筑。"},{"en":"Picture a meeting where the school run is used as evidence about a road.","cn":"想象一场会议，把送孩子上学的路线当作关于一条路的证据。"}]},"examples":[{"en":"City planning failed where the new blocks had no school.","cn":"新区没有配学校的地方，城市规划失败了。"},{"en":"The city planning office publishes its maps online.","cn":"城市规划办公室把图纸公布在网上。"},{"en":"City planning must consider drainage before it draws the streets.","cn":"城市规划必须先考虑排水，再画街道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「city（城市）+ planning（预先安排）」——给城市事先画好图、定好规矩 → 城市规划","word":"city planning"},"root":"city（拉丁 civitas「公民共同体」）+ planning（plan 来自拉丁 planum「平面」，planus「平的」）；短语在十九世纪工业城市布局中成为专门说法。","sensesIntro":{"en":"Eight senses follow one act: someone arranges a city in advance, and that act appears as a profession, a master document, land allocation, transport routes, three-dimensional design, neighbourhood work, legal rules and replanning of what already stands.","cn":"八个义项沿一个动作展开：有人事先安排城市，这个动作依次表现为专业、总体文件、土地分配、交通走向、三维设计、街区工作、法律规则，以及对已建成之物的重新规划。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn on paper that will later become a trench, a wall or a park.","cn":"核心意象：画在纸上的一条线，日后会变成沟、墙或公园。"},"chain":["ARRANGE IN ADVANCE","MASTER DOCUMENT","LAND ALLOCATION","NETWORK ROUTES","THREE-DIMENSIONAL DESIGN","REPLANNING WHAT EXISTS"],"branches":[{"senses":"01 · 02","en":"THE ACT AND ITS DOCUMENT: a profession of arranging, and the one long-range plan it produces.","cn":"动作与文件：一门安排的专业，以及它产出的那份长远方案。"},{"senses":"03","en":"WHO GETS WHICH LAND: the allocation of parcels is the core decision of the craft.","cn":"谁得到哪块地：地块分配是这门手艺的核心决定。"},{"senses":"04","en":"ROUTES FIXED FIRST: transport and utility lines outlast buildings and constrain everything after.","cn":"先定走向：交通与管线比建筑活得久，并约束后来的一切。"},{"senses":"05 · 06","en":"FROM DRAWING TO FEELING: dimensions and frontages decide how a place feels, and residents meet the plan at street level.","cn":"从图纸到感受：尺寸与临街面决定一个地方的感受，而居民在街道层面遇见规划。"},{"senses":"07 · 08","en":"FORCE AND REVISION: rules give the plan legal force, and renewal applies them to ground already occupied.","cn":"效力与修订：规则赋予方案法律效力，更新则把它们用于已被人占用的地面。"}]},"affixes":{"intro":{"en":"City planning is two words, each with its own productive endings and compounds.","cn":"city planning 是两个词，各自带有高产词尾与复合形式。"},"latinIntro":{"en":"Both halves trace to Latin: civitas for city and planum for plan, the latter from planus 'flat'.","cn":"两半都可上溯拉丁语：city 出自 civitas，plan 出自 planum，后者来自 planus「平的」。"},"items":[{"word":"civitas","structure":"civitas, civitatis (f., third declension)","meaning":"citizen-body, city","meaningCN":"公民共同体；城市","example":"The word names the political town.","exampleCN":"这个词命名的是政治意义上的城镇。"},{"word":"-scape","structure":"-scape (landscape-type suffix)","meaning":"a wide view of a kind","meaningCN":"某一类全景","example":"Cityscape names the city as a view.","exampleCN":"cityscape 把城市指为一种景观。"},{"word":"planum","structure":"planum (n., second declension, 'flat surface')","meaning":"a flat drawing surface","meaningCN":"平的图面","example":"The word began as a surface, not a scheme.","exampleCN":"这个词最初指一个表面，而不是方案。"},{"word":"planus","structure":"planus, plana, planum (adjective)","meaning":"flat, level","meaningCN":"平的、平坦的","example":"The adjective described ground easy to draw on.","exampleCN":"这个形容词描述易于绘图的地面。"},{"word":"plan","structure":"planum via French plan","meaning":"drawing or scheme","meaningCN":"图纸或方案","example":"The plan fits on one sheet.","exampleCN":"这张方案能放在一张纸上。"},{"word":"-er","structure":"agent suffix -er","meaning":"one who does","meaningCN":"做某事的人","example":"The planner walks the site first.","exampleCN":"规划师先走一遍场地。"},{"word":"-ing","structure":"verbal noun suffix -ing","meaning":"the activity","meaningCN":"活动本身","example":"Planning is the activity, a plan is the output.","exampleCN":"规划是活动，方案是产出。"},{"word":"-ed","structure":"past-participle adjective ending","meaning":"made by the action","meaningCN":"由该动作造成的","example":"A planned district has services in place.","exampleCN":"规划过的城区已把设施安排好。"},{"word":"un-","structure":"Old English negative prefix un-","meaning":"not","meaningCN":"否定","example":"Unplanned growth outruns the drains.","exampleCN":"未经规划的增长跑得比排水快。"},{"word":"zone","structure":"Greek zōnē 'belt' via Latin zona","meaning":"a belt or district","meaningCN":"带、区","example":"Zoning divides the map into belts of use.","exampleCN":"分区把地图切成用途带。"}],"latinEntries":[{"word":"civitas","structure":"civitas, civitatis (f., third declension)","meaning":"citizen-body, city","meaningCN":"公民共同体；城市"},{"word":"planum","structure":"planum, plani (n., second declension)","meaning":"flat surface","meaningCN":"平面"},{"word":"planus","structure":"planus, plana, planum (adjective)","meaning":"flat, level","meaningCN":"平的"},{"word":"zona","structure":"zona, zonae (f., first declension, Greek loanword)","meaning":"belt, girdle","meaningCN":"带、腰带"}]}},{"word":"irrigation","ipa_uk":"/ˌɪrɪˈɡeɪʃn/","ipa_us":"/ˌɪrɪˈɡeɪʃn/","definition_zh":"灌溉；灌溉系统；所供之水；医学冲洗；河流对土地的补给；灌区；灌溉农业；灌溉工程学","definition_en":"the artificial supply of water to land, or the system, water and practice by which this is done","core_image":"干裂的田垄上，一条新挖的沟把河水一点点引到玉米根部，泥土由灰转深","scene":"正午的田埂上，农人提起闸板，让河水顺着沟流进干裂的玉米地。The farmer lifts the sluice gate and lets river water run down the ditch for irrigation.","sceneCN":"这里 irrigation 指「把水引入农田的行为」（第 1 个义项：人工给土地供水）；句意为农人提起闸板放水，让河水顺着沟流进田里。可辨识物件：田埂、闸板、沟渠、玉米地。","pos":[{"tag":"n.","zh":"灌溉；灌溉系统；冲洗"}],"collocations":[{"phrase":"irrigation system","zh":"灌溉系统"},{"phrase":"irrigation canal","zh":"灌溉渠"},{"phrase":"drip irrigation","zh":"滴灌"},{"phrase":"flood irrigation","zh":"漫灌"},{"phrase":"irrigation water","zh":"灌溉用水"},{"phrase":"irrigation project","zh":"灌溉工程"}],"forms":[{"label":"单数","form":"irrigation"},{"label":"复数","form":"irrigations"},{"label":"动词","form":"irrigate"},{"label":"施动者名词","form":"irrigator"},{"label":"形容词（可灌溉的）","form":"irrigable"},{"label":"复合形式","form":"irrigation system"}],"derivatives":[{"word":"irrigate","pos":"v.","zh":"拉丁 irrigare「浇水」的动词形，去掉动作名词后缀 -ation 后得到，语义由「灌溉这一行为」转为「实施灌溉」"},{"word":"irrigator","pos":"n.","zh":"基础词 irrigate + -or（拉丁施动者后缀）→ 由「浇水」偏移为「进行灌溉的人或器具」"},{"word":"irrigable","pos":"adj.","zh":"基础词 irrigate + -able（能力后缀）→ 由「浇水」偏移为「可以灌溉的」"},{"word":"irrigational","pos":"adj.","zh":"基础词 irrigation + -al（形容词后缀）→ 由「灌溉」偏移为「与灌溉相关的」"},{"word":"microirrigation","pos":"n.","zh":"micro-（微小）+ irrigation → 由「灌溉」偏移为「微灌，极小尺度的灌溉」"},{"word":"fertigation","pos":"n.","zh":"fertilizer 与 irrigation 的混成形式 → 由「灌溉」偏移为「随水施肥」"}],"senses":[{"no":"01","title":"Supply of water to land","titleCN":"给土地供水","definition":"the artificial supply of water to fields or crops, usually through channels, pipes or sprinklers","definitionCN":"通过渠道、管道或喷头向农田或作物人工供水","example":"Irrigation turned the dry valley into a wheat field.","exampleCN":"灌溉把这条干谷变成了麦田。","why":"the noun names the action itself, the plainest sense of the Latin verb irrigare 'to water'.","whyCN":"这个名词直接指行为本身，是拉丁动词 irrigare「浇水」最朴素的义项。"},{"no":"02","title":"System of canals and works","titleCN":"渠网与灌溉设施","definition":"the canals, pipes, pumps and channels built to carry water to land","definitionCN":"为把水送到田间而修建的渠道、管道、水泵与沟渠","example":"The irrigation of the plain begins at a stone weir upstream.","exampleCN":"这片平原的灌溉从上游一座石堰开始。","why":"once the action is repeated at scale, the word shifts from the act to the built works that make it possible.","whyCN":"当这一行为被大规模重复，这个词就从行为转指使行为得以实现的工程设施。"},{"no":"03","title":"Water delivered","titleCN":"所供之水、灌水量","definition":"the water that is actually delivered to a field, measured in volume or depth","definitionCN":"实际送到田里的水，按体积或深度计量","example":"The irrigation for this plot is measured at the gate.","exampleCN":"这块地的灌水量在闸口处计量。","why":"since the verb means to water, the noun can name the water itself rather than the act of giving it.","whyCN":"既然动词意为浇水，名词也可以指水本身，而不指给水这个动作。"},{"no":"04","title":"Washing a wound or cavity","titleCN":"医学冲洗","definition":"the flushing of a wound, sinus or body cavity with a stream of liquid","definitionCN":"用液流冲洗伤口、窦腔或体腔","example":"The nurse recorded the irrigation of the wound in the chart.","exampleCN":"护士把伤口冲洗记录在病历上。","why":"medicine borrowed the watering image for washing a body surface with fluid, and the noun followed the verb into that use.","whyCN":"医学借用了「浇水」这一意象，指用液体冲洗体表，名词也随之进入这一用法。"},{"no":"05","title":"Watering by a river","titleCN":"河流对土地的天然补给","definition":"the natural watering of land by a river, flood or rising groundwater","definitionCN":"河流、洪水或上升的地下水对土地的自然浸润","example":"The annual irrigation of the floodplain keeps its soil fertile.","exampleCN":"洪泛平原每年的自然浸润使土壤保持肥沃。","why":"rivers water their banks without any engineer, and the noun extends to that natural supply.","whyCN":"河流无需工程师也会浸润两岸，名词便延伸到这种天然供水。"},{"no":"06","title":"Irrigated land","titleCN":"灌区、受灌溉的土地","definition":"the tract of land that is supplied with water by a system, considered as a whole","definitionCN":"由灌溉系统供水的一大片土地，作为整体看待","example":"The irrigation of the province covers a hundred thousand hectares.","exampleCN":"该省的灌区覆盖十万公顷土地。","why":"the noun can stand for the area that receives the water, since the land is what the whole system exists for.","whyCN":"名词可以指接受供水的整片区域，因为整个系统正是为这片土地而存在。"},{"no":"07","title":"Farming that depends on watering","titleCN":"依赖灌溉的农业","definition":"a way of farming in which crops depend on delivered water rather than on rainfall","definitionCN":"作物依赖输送的水而非降雨的耕作方式","example":"Irrigation supports two harvests a year in this district.","exampleCN":"灌溉让这个地区一年有两季收成。","why":"where rain is unreliable, the practice becomes a whole farming method, and the noun names it.","whyCN":"在雨水不可靠的地方，这种做法成为一整套耕作方式，名词便指这种方式。"},{"no":"08","title":"The engineering field","titleCN":"灌溉工程学","definition":"the branch of engineering and agronomy concerned with designing and managing water delivery","definitionCN":"负责设计与管理输水系统的工程学与农学分支","example":"She took a course in irrigation before returning to the family farm.","exampleCN":"她先修了一门灌溉工程课，之后回到家里的农场。","why":"a body of technique and theory grows around the practice, and the noun comes to name that field of study.","whyCN":"围绕这一做法生长出一套技术与理论，名词便转而指这个研究领域。"}],"etymology":{"intro":{"en":"Irrigation comes from Latin irrigatio, the noun of action from irrigare 'to water', formed with in- 'into' and rigare 'to moisten'. Dates are approximate.","cn":"irrigation 来自拉丁 irrigatio，是动词 irrigare「浇水」的动作名词，由 in-「进入」与 rigare「润湿」构成。年代均为约数。"},"items":[{"era":"LATIN RIGARE","en":"Rigare meant 'to water, moisten'. Its deeper origin is not established; the links suggested with other watering verbs are hypotheses, so any earlier root offered for it is a reconstructed form.","cn":"rigare 意为「浇水、润湿」。其更早来源尚无定论；把它与别的「浇水」动词相联系的种种说法都只是假说，因此为它给出的更早词根均属重构形式。"},{"era":"LATIN IN- + RIGARE","en":"The prefix in- 'into' combined with rigare to give irrigare 'to lead water into, to water'. The prefix assimilates to ir- before r.","cn":"前缀 in-「进入」与 rigare 结合成 irrigare「把水引入、浇水」，前缀在 r 前同化为 ir-。"},{"era":"LATIN IRRIGATIO","en":"Irrigatio was the action noun: the supplying of water, and by extension the works that supplied it.","cn":"irrigatio 是动作名词，指供水，也引申指供水的设施。"},{"era":"MEDIEVAL AND EARLY MODERN USE","en":"Medieval Latin kept the word for watering farmland and for washing a body part, and both senses passed into the European languages.","cn":"中世纪拉丁语保留了「浇灌农田」与「冲洗身体部位」两义，二者都传入了欧洲各语言。"},{"era":"ENGLISH","en":"English adopted irrigation in the seventeenth century, first for the watering of land and later for medical flushing.","cn":"英语在十七世纪吸收了 irrigation，先指给土地浇水，后又指医学冲洗。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of rigare is unsettled, and the exact date of its first English use is not recorded, so older forms quoted for it are reconstructed rather than attested.","cn":"来源不确定：rigare 的来源无定论，其英语首见的确切年代也无记录，因此为它引用的更早形式属重构形式而非书证。"}]},"similar":{"note":{"en":"Group one separates the word from its close relatives and from the look-alike irritation, which shares sound but not origin; group two separates it from other water words.","cn":"第一组把它与近亲词以及形近而不同源的 irritation 分开；第二组把它与别的「水」类词分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"irrigate","ipa":"/ˈɪrɪɡeɪt/","tag":"the verb","definition":"The verb names the act; irrigation is the noun of action built on it.","definitionCN":"动词指动作；irrigation 是在它之上构成的动作名词。"},{"word":"irrigated","ipa":"/ˈɪrɪɡeɪtɪd/","tag":"past participle","definition":"Describes land or a field that has received water; it modifies the object, not the practice.","definitionCN":"描述已受水的土地或田地；它修饰对象，而不指这种做法。"},{"word":"irrigable","ipa":"/ˈɪrɪɡəbl/","tag":"can be watered","definition":"Says of land that can be irrigated; a capacity word, not the act.","definitionCN":"指土地可以灌溉；这是能力词，不是行为。"},{"word":"irritation","ipa":"/ˌɪrɪˈteɪʃn/","tag":"different origin","definition":"From irritare 'to provoke'; it looks and sounds close but has no watering sense at all.","definitionCN":"来自 irritare「激怒」；形音都接近，却与水毫无关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"watering","ipa":"/ˈwɔːtərɪŋ/","tag":"everyday word","definition":"The ordinary word for giving plants water; irrigation is the large-scale, engineered version.","definitionCN":"给植物供水的日常说法；irrigation 是大规模、有工程的版本。"},{"word":"drainage","ipa":"/ˈdreɪnɪdʒ/","tag":"opposite direction","definition":"The removal of water from land; irrigation brings water in, drainage takes it away.","definitionCN":"把水从土地排走；灌溉送水进来，排水把水带走。"},{"word":"flooding","ipa":"/ˈflʌdɪŋ/","tag":"a method","definition":"Deliberately covering a field with water, one technique of irrigation rather than its name.","definitionCN":"有意让水淹没田面，是灌溉的一种技术，而不是灌溉本身。"},{"word":"sprinkling","ipa":"/ˈsprɪŋklɪŋ/","tag":"a method","definition":"Distributing water in drops; it names one delivery method, while irrigation names the whole practice.","definitionCN":"以水滴形式布水；它指一种输送方式，而 irrigation 指整套做法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin verb, the built works, real fixed phrases and real derived words.","cn":"正常联想：拉丁动词、实际工程设施、真实固定搭配与真实派生词。"},"normal":[{"en":"Latin rigare 'to water' plus in- 'into': to lead water into the land.","cn":"拉丁 rigare「浇水」加 in-「进入」：把水引进土地。"},{"en":"The family runs irrigate, irrigation, irrigator, irrigable, irrigational.","cn":"同族词包括 irrigate、irrigation、irrigator、irrigable、irrigational。"},{"en":"Fixed phrases mark the practice: irrigation canal, drip irrigation, flood irrigation.","cn":"固定搭配标出这种做法：灌溉渠、滴灌、漫灌。"},{"en":"The tools have their own names: irrigator for the person or device, irrigable for land that can take water.","cn":"工具另有名称：施动者或器具叫 irrigator，能受水的土地叫 irrigable。"},{"en":"The opposite word is drainage, which removes the water that irrigation brings in.","cn":"反方向的词是 drainage，它排走灌溉送来的水。"}],"abstract":[{"en":"Picture a line drawn in dust with one finger, and water following it to a stalk.","cn":"想象用手指在尘土里划出一道线，水沿着它流到一株茎前。"},{"en":"Picture a dry field turning dark in bands as each furrow fills.","cn":"想象干田随着每条沟被灌满，一条条地由灰变深。"},{"en":"Picture a sluice gate lifted by hand, and a whole valley drinking at once.","cn":"想象一只手提起闸门，整条山谷同时开始饮水。"}]},"examples":[{"en":"Ancient irrigation made the first cities possible on land with little rain.","cn":"古老的灌溉让第一批城市得以建在少雨的土地上。"},{"en":"The hospital uses irrigation to clean deep wounds before stitching.","cn":"医院在缝合前用冲洗清洁深部伤口。"},{"en":"Modern irrigation delivers water drop by drop to save the scarce supply.","cn":"现代灌溉一滴一滴地送水，以节约稀缺的水源。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ir-（进入）+ rig（浇水）+ -ation（名词）」——把水引进田里的这件事 → 灌溉","word":"irrigation"},"root":"拉丁 in-「进入」+ rigare「浇水、润湿」→ irrigare「引水入、浇灌」→ irrigatio「供水、灌溉」；rigare 更早来源不确定。英语经法语与晚期拉丁进入。","sensesIntro":{"en":"Eight senses follow the water outward from the act: first the deed and the works, then the water itself, then the borrowed medical wash, then the river's own supply, and finally the land, the farming and the engineering field.","cn":"八个义项顺着水从行为向外展开：先是行为与工程，再是水本身，然后是借用的医学冲洗、河流自身的补给，最后是土地、农耕与工程学科。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ditch cut through dry ground, carrying river water to the roots of a crop.","cn":"核心意象：在干地上开出一条沟，把河水送到作物的根部。"},"chain":["ACTION OF WATERING","BUILT WORKS","DELIVERED WATER","MEDICAL WASH","RIVER SUPPLY","LAND AND CRAFT"],"branches":[{"senses":"01 · 03","en":"THE ACT AND ITS WATER: the deed of giving water and the water that arrives are named by the same noun.","cn":"行为与其水：给水的动作与到达的水由同一个名词命名。"},{"senses":"02 · 08","en":"WORKS AND CRAFT: channels and pumps turn the act into an engineered system, and then into a field of study.","cn":"工程与技艺：渠道与水泵把行为变成工程系统，再变成一个研究领域。"},{"senses":"04","en":"MEDICAL WASH: a fluid stream cleans a wound or cavity, borrowing the watering image.","cn":"医学冲洗：液流清洁伤口或体腔，借用了浇水的意象。"},{"senses":"05","en":"RIVER SUPPLY: a river waters its floodplain with no machinery at all.","cn":"河流补给：河流无需任何机械便浸润自己的洪泛平原。"},{"senses":"06 · 07","en":"LAND AND FARMING: the watered tract, and the farming method that depends on delivered water.","cn":"土地与农耕：受水的那片地，以及依赖输水的耕作方式。"}]},"affixes":{"intro":{"en":"Irrigation can be read in parts: an assimilated Latin prefix, a Latin verb of watering, and an action-noun suffix.","cn":"irrigation 可按部分读出：一个同化的拉丁前缀、一个表示浇水的拉丁动词，以及一个动作名词后缀。"},"latinIntro":{"en":"The Latin family is genuine here: irrigare, irrigatio, irrigator and irrigabilis all belong to the same verb, and rigare is the watering root behind them.","cn":"这里的拉丁词族是真实的：irrigare、irrigatio、irrigator 与 irrigabilis 都属同一个动词，rigare 是它们背后的浇水词根。"},"items":[{"word":"ir-","structure":"Latin in- 'into', assimilated to ir- before r","meaning":"into","meaningCN":"进入","example":"The prefix directs the water inward to the field.","exampleCN":"这个前缀把水引向田里。"},{"word":"rig-","structure":"Latin rigare 'to water, moisten'","meaning":"to water","meaningCN":"浇水","example":"The root appears again in irrigate and irrigator.","exampleCN":"这个词根也出现在 irrigate 与 irrigator 中。"},{"word":"-ate","structure":"Latin -atus, past participle and verb ending","meaning":"verb-forming","meaningCN":"构成动词","example":"Irrigate is the verb built on the root.","exampleCN":"irrigate 是在这个词根上构成的动词。"},{"word":"-ation","structure":"Latin -atio, action-noun suffix","meaning":"the act or process","meaningCN":"行为或过程","example":"Irrigation names the act and its result.","exampleCN":"irrigation 指行为及其结果。"},{"word":"irrigate","structure":"ir- + rig- + -ate","meaning":"to supply water","meaningCN":"供水、浇灌","example":"Farmers irrigate the fields in spring.","exampleCN":"农民在春天浇灌田地。"},{"word":"irrigator","structure":"irrigate + -or (agent suffix)","meaning":"one who or that which irrigates","meaningCN":"进行灌溉的人或器具","example":"The irrigator checks the gate each morning.","exampleCN":"灌溉者每天早上检查闸口。"},{"word":"irrigable","structure":"irrigate + -able (capacity suffix)","meaning":"able to be irrigated","meaningCN":"可以灌溉的","example":"The lower field is irrigable; the ridge is not.","exampleCN":"低处的田可以灌溉，山脊则不行。"},{"word":"irrigational","structure":"irrigation + -al (adjective suffix)","meaning":"relating to irrigation","meaningCN":"与灌溉相关的","example":"Irrigational works changed the valley.","exampleCN":"灌溉工程改变了这条山谷。"},{"word":"microirrigation","structure":"micro- 'small' + irrigation","meaning":"watering on a very small scale","meaningCN":"极小尺度的灌溉","example":"Microirrigation saves water in orchards.","exampleCN":"微灌在果园里省水。"},{"word":"fertigation","structure":"fertilizer + irrigation, blended","meaning":"feeding crops through the water","meaningCN":"随水施肥","example":"Fertigation delivers nutrients with the drip line.","exampleCN":"水肥一体化让养分随滴灌管送达。"}],"latinEntries":[{"word":"irrigatio","structure":"Latin noun of action from irrigare","meaning":"a watering, a supplying of water","meaningCN":"浇水、供水"},{"word":"irrigare","structure":"Latin verb: in- + rigare","meaning":"to lead water in, to water","meaningCN":"引水入、浇灌"},{"word":"rigare","structure":"Latin verb","meaning":"to water, moisten","meaningCN":"浇水、润湿"},{"word":"irrigator","structure":"Latin agent noun from irrigare","meaning":"one who waters","meaningCN":"浇水的人"}]}},{"word":"irrigate","ipa_uk":"/ˈɪrɪɡeɪt/","ipa_us":"/ˈɪrɪɡeɪt/","definition_zh":"灌溉；浇灌；引水入田；冲洗伤口或体腔；使湿润；使旱地可耕；浸润；为景观供水","definition_en":"to supply water to land, crops or a body part, usually by artificial means","core_image":"一双手把闸板抬高几寸，水头立刻爬上干沟，土色一路由浅变深","scene":"清晨的菜地里，农人把水管接到渠口，让水慢慢漫过每一垄。At dawn the grower opens the channel and lets water irrigate the vegetable rows.","sceneCN":"这里 irrigate 指「给作物或土地供水」（第 1 个义项：人工浇灌土地）；句意为农人在清晨开渠，让水浇灌菜垄。可辨识物件：水管、渠口、菜垄、晨光。","pos":[{"tag":"v.","zh":"灌溉；浇灌；冲洗；使湿润"}],"collocations":[{"phrase":"irrigate the fields","zh":"灌溉田地"},{"phrase":"irrigate crops","zh":"浇灌作物"},{"phrase":"irrigate a wound","zh":"冲洗伤口"},{"phrase":"irrigate the land","zh":"给土地供水"},{"phrase":"irrigate by canal","zh":"通过渠道引水"},{"phrase":"irrigate a garden","zh":"给园子浇水"}],"forms":[{"label":"原形","form":"irrigate"},{"label":"第三人称单数","form":"irrigates"},{"label":"过去式","form":"irrigated"},{"label":"过去分词","form":"irrigated"},{"label":"现在分词","form":"irrigating"},{"label":"名词","form":"irrigation"},{"label":"施动者名词","form":"irrigator"},{"label":"形容词","form":"irrigable"}],"derivatives":[{"word":"irrigation","pos":"n.","zh":"基础词 irrigate + -ion（拉丁 -atio 动作名词后缀）→ 由「浇水」偏移为「灌溉行为或灌溉系统」"},{"word":"irrigator","pos":"n.","zh":"基础词 irrigate + -or（拉丁施动者后缀）→ 偏移为「灌溉的人或器具」"},{"word":"irrigable","pos":"adj.","zh":"基础词 irrigate + -able（能力后缀）→ 偏移为「可灌溉的」"},{"word":"irrigational","pos":"adj.","zh":"基础词 irrigation + -al（形容词后缀）→ 偏移为「与灌溉相关的」"},{"word":"microirrigation","pos":"n.","zh":"micro-（微小）+ irrigation → 偏移为「微灌」"},{"word":"fertigation","pos":"n.","zh":"fertilizer 与 irrigation 的混成形式 → 偏移为「随水施肥」"}],"senses":[{"no":"01","title":"Supply water to land or crops","titleCN":"给土地或作物供水","definition":"to supply water to land, fields or growing plants, especially by artificial means","definitionCN":"尤以人工方式向土地、田地或生长中的作物供水","example":"They irrigate the orchard every second week in summer.","exampleCN":"夏天他们每隔一周给果园浇水。","why":"the core verb sense simply names the act that the noun irrigation also names.","whyCN":"这个动词的核心义项就是名词 irrigation 所指的那个行为本身。"},{"no":"02","title":"Lead water through channels","titleCN":"通过沟渠引水","definition":"to bring water to a field along ditches, pipes or furrows rather than by rainfall","definitionCN":"沿沟渠、管道或垄沟把水送到田里，而非依赖降雨","example":"The farmers irrigate the lower plots from a single earthen canal.","exampleCN":"农民们用一条土渠给低处的地块引水。","why":"the verb keeps the image of leading water along a path, which is the oldest technique.","whyCN":"动词保留了「沿路径把水引过去」的意象，这是最古老的技术。"},{"no":"03","title":"Flush a wound","titleCN":"冲洗伤口","definition":"to wash a wound with a stream of water or saline so that debris is carried away","definitionCN":"用水流或生理盐水冲洗伤口，把杂物带走","example":"The doctor irrigated the cut before closing it.","exampleCN":"医生在缝合前冲洗了那道伤口。","why":"medicine extended the watering verb to the cleaning of tissue, since both involve a directed stream.","whyCN":"医学把浇水这个动词扩展到清洁组织，因为二者都涉及定向的液流。"},{"no":"04","title":"Flush a body cavity","titleCN":"冲洗体腔","definition":"to flush a sinus, bladder or other cavity with liquid for treatment","definitionCN":"为治疗目的用液体冲洗窦腔、膀胱或其他腔体","example":"The nurse irrigated the patient's ear to remove the blockage.","exampleCN":"护士冲洗病人的耳朵以清除堵塞。","why":"the same stream that waters a field can clear a hollow space, so the verb spreads to cavities.","whyCN":"浇田的那股水流也能清理一个空腔，动词便延伸到体腔。"},{"no":"05","title":"Of a river: to water","titleCN":"（河流）浸润土地","definition":"of a river or flood, to supply water to the land beside it","definitionCN":"指河流或洪水给沿岸土地供水","example":"The river irrigates the plain each spring without any pump.","exampleCN":"这条河每年春天不用任何水泵就浸润平原。","why":"water does the work by itself here, so the verb drops the idea of an engineer.","whyCN":"这里水自己完成了工作，动词因此不再含「有工程师介入」的意思。"},{"no":"06","title":"Make dry land productive","titleCN":"使旱地变为可耕地","definition":"to bring water to dry ground so that it can support crops","definitionCN":"把水引到干旱的土地，使其能够种植作物","example":"The project irrigated the desert and doubled the harvest.","exampleCN":"这个工程灌溉了荒漠，使收成翻倍。","why":"the purpose behind the act is to change what the land can do, and the verb can name that result.","whyCN":"行为背后的目的是改变土地能做什么，动词因此可以指这一结果。"},{"no":"07","title":"Moisten something","titleCN":"使湿润（泛指）","definition":"to make something slightly wet, even where no crop is involved","definitionCN":"使某物略微湿润，即使与作物无关","example":"Rain irrigated the dusty road and quieted the air.","exampleCN":"雨水润湿了尘土飞扬的路，空气也静了下来。","why":"the Latin verb simply meant to moisten, and that broad sense survives beside the farming one.","whyCN":"拉丁动词本义就是润湿，这个宽泛义项一直与农业义并存。"},{"no":"08","title":"Water turf and landscape","titleCN":"为草坪与景观供水","definition":"to keep lawns, parks or sports turf supplied with water by a built system","definitionCN":"用建成系统为草坪、公园或运动场地持续供水","example":"Groundskeepers irrigate the pitch through buried sprinklers.","exampleCN":"场地管理员通过埋设的喷头给球场浇水。","why":"the same act now serves appearance rather than harvest, and the verb follows it into that setting.","whyCN":"同一行为如今服务于外观而非收成，动词也随之进入这一场景。"}],"etymology":{"intro":{"en":"Irrigate comes from Latin irrigare 'to water', from in- 'into' and rigare 'to moisten'. Dates are approximate.","cn":"irrigate 来自拉丁 irrigare「浇水」，由 in-「进入」与 rigare「润湿」构成。年代均为约数。"},"items":[{"era":"LATIN RIGARE","en":"Rigare meant 'to water, moisten'. Its deeper origin is not established; the connections proposed with other watering verbs are hypotheses, so any earlier root offered for it is a reconstructed form.","cn":"rigare 意为「浇水、润湿」。其更早来源尚无定论；有人提出的与别的「浇水」动词之间的联系都只是假说，因此为它给出的更早词根均属重构形式。"},{"era":"LATIN IRRIGARE","en":"In- 'into' plus rigare produced irrigare 'to lead water into something'. The prefix assimilates to ir- before r, giving the spelling ir-.","cn":"in-「进入」加 rigare 构成 irrigare「把水引入某物」，前缀在 r 前同化为 ir-，拼写遂作 ir-。"},{"era":"LATIN IRRIGATUS","en":"The past participle irrigatus 'watered' was used adjectivally of land and later of washed tissue.","cn":"过去分词 irrigatus「已浇过水的」先用于土地，后也用于被冲洗的组织。"},{"era":"MEDICAL LATIN","en":"Medical Latin applied the verb to the flushing of wounds and cavities with fluid, a use that English inherited.","cn":"医学拉丁语把这个动词用于以液体冲洗伤口与体腔，英语继承了这一用法。"},{"era":"ENGLISH","en":"English took the verb in the seventeenth century, first for watering land and soon after for washing body parts.","cn":"英语在十七世纪引入这个动词，先指给土地浇水，随后又指冲洗身体部位。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of rigare is unsettled, and the first English date is not precisely recorded, so earlier forms given for the root are reconstructed rather than attested.","cn":"来源不确定：rigare 在拉丁语之前的来源无定论，英语首见的年代也没有精确记录，因此为这个词根给出的更早形式属重构形式而非书证。"}]},"similar":{"note":{"en":"Group one separates the verb from its own family and from the look-alike irritate, which shares sound but not origin; group two separates it from neighbouring water verbs.","cn":"第一组把这个动词与自己的词族以及形近而不同源的 irritate 分开；第二组把它与相邻的「水」类动词分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"irrigation","ipa":"/ˌɪrɪˈɡeɪʃn/","tag":"the noun","definition":"The action noun built on the verb; it names the act, the works or the water.","definitionCN":"由动词构成的动作名词；指行为、工程或水。"},{"word":"irrigated","ipa":"/ˈɪrɪɡeɪtɪd/","tag":"participle","definition":"Describes land that has received water; it is a state, not an action.","definitionCN":"描述已受水的土地；是状态，不是动作。"},{"word":"irritate","ipa":"/ˈɪrɪteɪt/","tag":"different origin","definition":"From irritare 'to provoke'; it sounds close but carries no water at all.","definitionCN":"来自 irritare「激怒」；读音接近，却完全不含水。"},{"word":"irrigable","ipa":"/ˈɪrɪɡəbl/","tag":"capability","definition":"Says land can be watered; it does not describe anyone watering it.","definitionCN":"指土地可以受水；并不描述有人在浇。"}]},{"heading":"NEAR MEANING","entries":[{"word":"water","ipa":"/ˈwɔːtə(r)/","tag":"general verb","definition":"The everyday verb for giving plants water; irrigate implies method and scale.","definitionCN":"给植物供水的日常动词；irrigate 含方法与规模之意。"},{"word":"sprinkle","ipa":"/ˈsprɪŋkl/","tag":"method","definition":"To scatter drops over a surface; one way to irrigate, not the whole act.","definitionCN":"把水滴散在表面；是灌溉的一种方式，而非整个行为。"},{"word":"flood","ipa":"/flʌd/","tag":"method","definition":"To cover land with water deliberately; a technique, often a crude one.","definitionCN":"有意让水覆盖土地；是一种技术，往往较粗放。"},{"word":"wash","ipa":"/wɒʃ/","tag":"medical overlap","definition":"To clean with liquid; it covers the medical sense but not the farming one.","definitionCN":"用液体清洁；覆盖医学义，却不覆盖农业义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the Latin verb, its real derivatives and the phrases in which it actually occurs.","cn":"正常联想：拉丁动词、其真实派生词，以及它实际出现的搭配。"},"normal":[{"en":"Latin in- 'into' plus rigare 'to water': to lead water into the ground.","cn":"拉丁 in-「进入」加 rigare「浇水」：把水引进地里。"},{"en":"The family runs irrigate, irrigation, irrigator, irrigable, irrigational.","cn":"同族词包括 irrigate、irrigation、irrigator、irrigable、irrigational。"},{"en":"Fixed phrases mark the everyday uses: irrigate the fields, irrigate crops, irrigate a wound.","cn":"固定搭配标出日常用法：灌溉田地、浇灌作物、冲洗伤口。"},{"en":"The medical use keeps the same image: a stream is aimed at one spot and carries dirt away.","cn":"医学用法保留同一意象：一股液流对准一处，把脏物带走。"},{"en":"Its opposite in land management is drain, which takes water out instead of in.","cn":"它在土地管理中的反义是 drain，把水排出而不是引入。"}],"abstract":[{"en":"Picture a gate raised two inches and the water front crawling up the dry ditch.","cn":"想象闸板抬高两寸，水头立刻沿着干沟向上爬。"},{"en":"Picture soil changing colour in a line, from pale grey to dark brown.","cn":"想象土壤沿一条线变色，由浅灰转为深褐。"},{"en":"Picture a wound being cleaned by a thin steady stream, not by a splash.","cn":"想象一道伤口被细而稳的液流清洁，而不是被泼溅。"}]},"examples":[{"en":"Farmers irrigate the rice fields twice a week in the dry season.","cn":"旱季里农民每周给稻田浇两次水。"},{"en":"The surgeon irrigated the wound with saline before stitching.","cn":"外科医生在缝合前用盐水冲洗伤口。"},{"en":"A single river can irrigate a whole valley if its water is led by canals.","cn":"只要用渠道引水，一条河就能灌溉整条山谷。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「ir-（进入）+ rig（浇水）+ -ate（动词）」——把水引进去 → 灌溉、浇灌","word":"irrigate"},"root":"拉丁 in-「进入」+ rigare「浇水、润湿」→ irrigare「引水入、浇灌」；rigare 更早来源不确定。英语经法语与晚期拉丁进入。","sensesIntro":{"en":"Eight senses move from the plain act to its methods and borrowings: watering crops, leading water by channels, flushing a wound and then a cavity, a river watering its banks, making dry land farmable, moistening anything, and watering turf for use.","cn":"八个义项从朴素的行为走向其方式与借用：浇灌作物、用渠道引水、冲洗伤口再到冲洗体腔、河流浸润两岸、使旱地可耕、把任何东西弄湿，以及为使用而给草坪供水。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand lifting a gate so that water begins to move along a dry channel.","cn":"核心意象：一只手提起闸门，水开始沿着干涸的渠道流动。"},"chain":["WATER GIVEN","DITCHES AND PIPES","WOUND WASH","CAVITY WASH","RIVER AT WORK","GREEN LAND"],"branches":[{"senses":"01 · 02","en":"THE BASIC ACT AND ITS CHANNEL: giving water, and the ditches that decide where it goes.","cn":"基本行为与其通道：给水，以及决定水流去向的沟渠。"},{"senses":"03 · 04","en":"MEDICAL FLUSH: the same directed stream cleans a wound, then a hollow organ.","cn":"医学冲洗：同一股定向液流先清洁伤口，再清洁中空器官。"},{"senses":"05","en":"THE RIVER'S OWN WORK: no pump, no engineer, just water reaching the bank.","cn":"河流自己的工作：没有水泵，没有工程师，只有水抵达河岸。"},{"senses":"06","en":"LAND MADE PRODUCTIVE: watering changes what dry ground can grow.","cn":"土地变得可耕：供水改变了旱地能种什么。"},{"senses":"07 · 08","en":"MOISTURE AND UPKEEP: from making anything damp to keeping turf green for use.","cn":"湿润与养护：从把任何东西弄湿，到为使用而让草坪常绿。"}]},"affixes":{"intro":{"en":"Irrigate can be read in parts: an assimilated Latin prefix, the Latin root of watering, and a verb ending.","cn":"irrigate 可按部分读出：一个同化的拉丁前缀、表示浇水的拉丁词根，以及一个动词词尾。"},"latinIntro":{"en":"The Latin family is real: irrigare, irrigatio, irrigator and irrigabilis all descend from the same verb, with rigare as the watering root.","cn":"拉丁词族是真实的：irrigare、irrigatio、irrigator 与 irrigabilis 都出自同一个动词，rigare 是其中的浇水词根。"},"items":[{"word":"ir-","structure":"Latin in- 'into', assimilated to ir- before r","meaning":"into","meaningCN":"进入","example":"The prefix sends the water into the field.","exampleCN":"这个前缀把水送入田里。"},{"word":"rig-","structure":"Latin rigare 'to water, moisten'","meaning":"to water","meaningCN":"浇水","example":"The root is shared with irrigation and irrigator.","exampleCN":"这个词根与 irrigation 和 irrigator 共用。"},{"word":"-ate","structure":"Latin -atus, verb ending","meaning":"verb-forming","meaningCN":"构成动词","example":"The ending turns the root into a working verb.","exampleCN":"这个词尾把词根变成可用的动词。"},{"word":"-ion","structure":"Latin -io, action-noun suffix","meaning":"the act or result","meaningCN":"行为或结果","example":"Adding the suffix yields irrigation.","exampleCN":"加上这个后缀就得到 irrigation。"},{"word":"-or","structure":"Latin agent suffix","meaning":"one who does","meaningCN":"做某事的人或物","example":"Irrigator names the person or the device.","exampleCN":"irrigator 指那个人或那个器具。"},{"word":"-able","structure":"Latin -abilis, capacity suffix","meaning":"able to be","meaningCN":"能够被……的","example":"Irrigable land can take water.","exampleCN":"irrigable 指可以受水的土地。"},{"word":"irrigation","structure":"irrigate + -ion","meaning":"the act or the system","meaningCN":"灌溉行为或灌溉系统","example":"Irrigation supplies the fields in summer.","exampleCN":"灌溉在夏天为田地供水。"},{"word":"irrigator","structure":"irrigate + -or","meaning":"one who or that which irrigates","meaningCN":"进行灌溉的人或器具","example":"The irrigator repairs the channel gates.","exampleCN":"灌溉者修理渠口的闸门。"},{"word":"irrigable","structure":"irrigate + -able","meaning":"able to be irrigated","meaningCN":"可以灌溉的","example":"Only half the valley is irrigable.","exampleCN":"这条山谷只有一半可以灌溉。"},{"word":"irrigational","structure":"irrigation + -al","meaning":"relating to irrigation","meaningCN":"与灌溉相关的","example":"Irrigational canals cross the plain.","exampleCN":"灌溉渠道横穿平原。"}],"latinEntries":[{"word":"irrigare","structure":"Latin verb: in- + rigare","meaning":"to lead water in, to water","meaningCN":"引水入、浇灌"},{"word":"irrigatio","structure":"Latin noun of action from irrigare","meaning":"a watering, a supplying of water","meaningCN":"浇水、供水"},{"word":"rigare","structure":"Latin verb","meaning":"to water, moisten","meaningCN":"浇水、润湿"},{"word":"irrigator","structure":"Latin agent noun from irrigare","meaning":"one who waters","meaningCN":"浇水的人"}]}},{"word":"irrigation system","ipa_uk":"/ˌɪrɪˈɡeɪʃn ˌsɪstəm/","ipa_us":"/ˌɪrɪˈɡeɪʃn ˌsɪstəm/","definition_zh":"灌溉系统；渠网；滴灌系统；喷灌系统；田间灌溉体系；景观灌溉系统；古代水利系统；灌溉系统的运行与维护","definition_en":"the whole set of works, channels, pipes and devices that deliver water to land","core_image":"从河边的泵房出发，一条主管分出无数细管，末端的水滴正落在根旁的土上","scene":"山坡上的温室里，细管沿着每一行作物铺开，末端不断滴下水珠。A drip line runs along each row in the hillside greenhouse, part of the irrigation system.","sceneCN":"这里 irrigation system 指「把水送到田间的整套设施」（第 1 个义项：水源、管道与出水装置的总成）；句意为山坡温室里每一行作物都铺着滴灌管，它是灌溉系统的一部分。可辨识物件：温室、细管、水珠、作物行。","pos":[{"tag":"n.","zh":"灌溉系统；渠网；灌溉设施总成"}],"collocations":[{"phrase":"drip irrigation system","zh":"滴灌系统"},{"phrase":"sprinkler irrigation system","zh":"喷灌系统"},{"phrase":"irrigation system design","zh":"灌溉系统设计"},{"phrase":"irrigation system maintenance","zh":"灌溉系统维护"},{"phrase":"irrigation system efficiency","zh":"灌溉系统效率"},{"phrase":"traditional irrigation system","zh":"传统灌溉系统"}],"forms":[{"label":"单数","form":"irrigation system"},{"label":"复数","form":"irrigation systems"},{"label":"定语形式","form":"irrigation-system"},{"label":"简称","form":"irrigation"},{"label":"相关动词","form":"irrigate"},{"label":"施动者名词","form":"irrigator"}],"derivatives":[{"word":"irrigation","pos":"n.","zh":"基础词 irrigate + -ion（拉丁动作名词后缀）→ 由「浇水」偏移为「灌溉这一做法」"},{"word":"irrigator","pos":"n.","zh":"基础词 irrigate + -or（施动者后缀）→ 偏移为「灌溉的人或器具」"},{"word":"irrigable","pos":"adj.","zh":"基础词 irrigate + -able（能力后缀）→ 偏移为「可灌溉的」"},{"word":"systematic","pos":"adj.","zh":"基础词 system + -atic（形容词后缀，源自希腊 systema）→ 由「系统」偏移为「成体系的、有条理的」"},{"word":"systemic","pos":"adj.","zh":"基础词 system + -ic（形容词后缀）→ 偏移为「作用于整个系统的」"},{"word":"systematize","pos":"v.","zh":"基础词 system + -atize（动词后缀）→ 偏移为「使系统化」"}],"senses":[{"no":"01","title":"The whole installation","titleCN":"整套灌溉设施","definition":"the complete set of water source, pumps, channels, pipes and outlets that supplies a piece of land","definitionCN":"由水源、水泵、渠道、管道与出水口组成、为一片土地供水的完整设施","example":"The irrigation system of the estate draws from a single reservoir.","exampleCN":"这片庄园的灌溉系统只从一座水库取水。","why":"system names an organised whole, and irrigation names the job, so the phrase is the whole machine that does the job.","whyCN":"system 指有组织的整体，irrigation 指要干的活，因此这个短语就是干这活的一整套机器。"},{"no":"02","title":"Canal and ditch network","titleCN":"渠网","definition":"the open channels, ditches and gates that carry water across fields without pipes","definitionCN":"不用管道、跨越田间输水的明渠、沟与闸","example":"The old irrigation system of the delta is a lace of earthen canals.","exampleCN":"三角洲古老的灌溉系统是一张土渠织成的网。","why":"open channels came before pipes, and the phrase still names that network of dug water.","whyCN":"明渠先于管道出现，这个短语至今仍指那张由挖出的水道构成的网。"},{"no":"03","title":"Drip irrigation system","titleCN":"滴灌系统","definition":"a system that delivers water slowly through tubes and emitters directly to each plant","definitionCN":"通过管与出水器把水缓慢直接送到每株植物的系统","example":"A drip irrigation system cut the orchard's water use by half.","exampleCN":"滴灌系统把果园的用水量减少了一半。","why":"the emitter is the distinguishing part, so the phrase takes the method's name.","whyCN":"出水器是它区别于其他系统的部件，短语因此带上这种方法的名字。"},{"no":"04","title":"Sprinkler irrigation system","titleCN":"喷灌系统","definition":"a system of pipes and heads that sprays water over the surface like rain","definitionCN":"由管道与喷头把水像雨一样洒到地面的系统","example":"The sprinkler irrigation system covers the whole playing field.","exampleCN":"喷灌系统覆盖了整个运动场。","why":"spraying imitates rain, and the head is what turns a supply network into this kind of system.","whyCN":"喷洒模仿降雨，喷头正是把供水网变成这类系统的部件。"},{"no":"05","title":"Field-level system","titleCN":"田间灌溉体系","definition":"the part of the works that lies inside one farm and serves its own plots","definitionCN":"位于单个农场内部、只服务自家地块的那部分设施","example":"Each farmer maintains the on-farm irrigation system alone.","exampleCN":"每户农民独自维护田间的灌溉体系。","why":"ownership changes at the farm gate, so the phrase marks the boundary of responsibility.","whyCN":"所有权在农场门口发生变化，短语因此标出责任的边界。"},{"no":"06","title":"Landscape and turf system","titleCN":"景观与草坪灌溉系统","definition":"a system built to keep parks, gardens or sports turf green rather than to grow crops","definitionCN":"为让公园、花园或运动草坪保持常绿而非为种作物而建的设施","example":"The park's irrigation system runs at night to limit evaporation.","exampleCN":"公园的灌溉系统在夜间运行以减少蒸发。","why":"the purpose shifts from yield to appearance, and the phrase follows the land it serves.","whyCN":"目的从产量转到外观，短语也随着它服务的土地而变。"},{"no":"07","title":"Historic waterworks","titleCN":"古代水利系统","definition":"an ancient network of tunnels, wells and channels, such as a qanat, that watered a settlement","definitionCN":"如坎儿井一类、为聚居地供水的古老隧洞、井与渠道网络","example":"The irrigation system under the oasis was dug centuries ago.","exampleCN":"绿洲之下的灌溉系统是几个世纪前挖成的。","why":"old works were systems too, and the phrase is the natural one for them in historical writing.","whyCN":"古代工程同样是系统，历史写作中自然就用这个短语指它们。"},{"no":"08","title":"Running and upkeep","titleCN":"运行与维护","definition":"the ongoing management, repair and scheduling that keeps the works delivering water","definitionCN":"让设施持续供水而进行的日常管理、修理与调度","example":"Training farmers to run the irrigation system matters as much as building it.","exampleCN":"教农民运行灌溉系统，与修建它同样重要。","why":"a system that is not operated delivers nothing, so the phrase also covers its running.","whyCN":"系统不运行就什么都送不到，因此短语也涵盖它的运转。"}],"etymology":{"intro":{"en":"Irrigation system joins irrigation, from Latin irrigatio, to system, from Greek systema 'an organised whole'. Dates are approximate.","cn":"irrigation system 把来自拉丁 irrigatio 的 irrigation 与来自希腊 systema「有组织的整体」的 system 组合起来。年代均为约数。"},"items":[{"era":"LATIN IRRIGATIO","en":"Irrigatio, the action noun of irrigare 'to water', named the supplying of water and the works that did it. The deeper origin of rigare is not established.","cn":"irrigatio 是 irrigare「浇水」的动作名词，指供水以及做这件事的设施。rigare 的更早来源尚无定论。"},{"era":"GREEK SYSTEMA","en":"Systema meant 'a whole made of parts', generally derived from syn- 'together' and histanai 'to stand, set up'.","cn":"systema 意为「由各部分合成的整体」，一般认为是 syn-「一起」与 histanai「立起、安置」的合成。"},{"era":"LATIN SYSTEMA","en":"Latin borrowed systema as a learned noun for an organised body or scheme; it is a loan, not an inherited Latin relative.","cn":"拉丁语借入 systema，作为指有组织的整体或方案的学术名词；它是借词，而非拉丁固有同族词。"},{"era":"FRENCH AND ENGLISH","en":"French système passed into English as system in the seventeenth century, first for an ordered whole and later for technical assemblies.","cn":"法语 système 在十七世纪进入英语成为 system，先指有秩序的整体，后指技术性装置。"},{"era":"MODERN COMPOUND","en":"Engineers of the nineteenth century joined the two nouns into irrigation system for the whole apparatus of water delivery.","cn":"十九世纪的工程师把这两个名词组合成 irrigation system，指输水的整套装置。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the pre-Latin origin of rigare is unsettled and the first date of the compound is not recorded, so earlier forms quoted for the root are reconstructed rather than attested.","cn":"来源不确定：rigare 在拉丁语之前的来源无定论，这个复合词首见的年代也没有记录，因此为词根引用的更早形式属重构形式而非书证。"}]},"similar":{"note":{"en":"Group one separates the phrase from its parts and from the look-alikes systematic and ecosystem; group two separates it from other water facilities.","cn":"第一组把这个短语与它的组成部分以及形近的 systematic、ecosystem 分开；第二组把它与别的水利设施分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"irrigation","ipa":"/ˌɪrɪˈɡeɪʃn/","tag":"the practice","definition":"The practice or the water, without reference to the built whole.","definitionCN":"指做法或水本身，不指建成的整体。"},{"word":"irrigate","ipa":"/ˈɪrɪɡeɪt/","tag":"the verb","definition":"The action of giving water; the system is what carries it out.","definitionCN":"给水的动作；系统是执行它的东西。"},{"word":"systematic","ipa":"/ˌsɪstəˈmætɪk/","tag":"adjective","definition":"Means orderly and methodical; it describes method, not a waterworks.","definitionCN":"意为有条理、成体系；描述方法，而非水利设施。"},{"word":"ecosystem","ipa":"/ˈiːkəʊsɪstəm/","tag":"different whole","definition":"A community of organisms and their setting; it shares system but not water delivery.","definitionCN":"生物群落及其环境；共享 system 一词，却不含输水。"}]},{"heading":"NEAR MEANING","entries":[{"word":"waterworks","ipa":"/ˈwɔːtəwɜːks/","tag":"facilities","definition":"The buildings and works that supply or treat water for a town; broader than farm delivery.","definitionCN":"为城镇供水和处理水的建筑与工程；比农田输水更宽。"},{"word":"canal network","ipa":"/kəˈnæl ˈnetwɜːk/","tag":"open channels only","definition":"Names only the dug channels, not pumps, pipes or emitters.","definitionCN":"只指挖成的渠道，不含水泵、管道与出水器。"},{"word":"drainage system","ipa":"/ˈdreɪnɪdʒ ˌsɪstəm/","tag":"opposite flow","definition":"Removes water from land; an irrigation system brings it in.","definitionCN":"把水从土地排走；灌溉系统则把水送进来。"},{"word":"sprinkler system","ipa":"/ˈsprɪŋklə ˌsɪstəm/","tag":"one type","definition":"Names only the spray-head type, one member of the larger class.","definitionCN":"只指喷头类型，是更大类别中的一种。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real source words, the actual parts of such a system, and the fixed phrases built on it.","cn":"正常联想：两个真实的来源词、这类系统的实际部件，以及由它构成的固定搭配。"},"normal":[{"en":"Irrigation from Latin rigare 'to water', system from Greek systema 'organised whole': a whole organised to water.","cn":"irrigation 来自拉丁 rigare「浇水」，system 来自希腊 systema「有组织的整体」：为浇水而组织起来的整体。"},{"en":"The parts run source, headworks, canal, pipes, emitters, root zone, in that order.","cn":"部件依次是水源、首部工程、渠道、管道、出水器、根区。"},{"en":"Fixed phrases name it in use: drip irrigation system, sprinkler irrigation system, irrigation system maintenance.","cn":"固定搭配标出它的用法：滴灌系统、喷灌系统、灌溉系统维护。"},{"en":"The two great types are told apart by their emitters: a tube that drips, or a head that sprays.","cn":"两大类型靠出水部件区分：滴水的是管，喷雾的是喷头。"},{"en":"Its counterpart is the drainage system, which takes away what this one brings in.","cn":"与之对应的是排水系统，本系统送进来的水由它排走。"}],"abstract":[{"en":"Picture a pump house by a river and a fan of thin lines opening across a hillside.","cn":"想象河边一座泵房，一把细管像扇面一样在山坡上展开。"},{"en":"Picture one drop hanging at a tube end, then falling exactly on a root.","cn":"想象管口挂着一滴水，然后正好落在一条根上。"},{"en":"Picture a map of the whole valley reduced to lines and gates, readable at a glance.","cn":"想象整条山谷的地图被简化成线条与闸口，一眼就能读懂。"}]},"examples":[{"en":"A well-designed irrigation system loses less water than an open ditch.","cn":"设计良好的灌溉系统比明渠损失的水少。"},{"en":"The irrigation system of the valley was repaired after the earthquake.","cn":"地震后，这条山谷的灌溉系统得到修复。"},{"en":"Engineers map every pipe before extending the irrigation system.","cn":"工程师在扩建灌溉系统之前先测绘每一根管道。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「irrigation（灌溉）+ system（系统）」——把水送到田里的整套装置 → 灌溉系统","word":"irrigation system"},"root":"拉丁 irrigatio（in-「进入」+ rigare「浇水」）＋希腊 systema（syn-「一起」+ histanai「立起」）→ 英语复合词 irrigation system；rigare 更早来源不确定。","sensesIntro":{"en":"Eight senses move from the whole to its parts and uses: the complete installation, the open channels, the two great emitter types, the two kinds of site, an ancient waterwork, and finally the running of the system.","cn":"八个义项从整体走向部件与用途：完整设施、明渠、两种主要出水方式、两类场地、一种古代工程，最后是系统的运行。"},"semanticMap":{"core":{"en":"CORE IMAGE: a single pump feeding a branching net of pipes that ends at the roots of a crop.","cn":"核心意象：一台水泵喂给一张分叉的管网，末端落在作物的根部。"},"chain":["WATER SOURCE","HEADWORKS","MAIN CANAL","DISTRIBUTION LINES","EMITTERS","ROOT ZONE"],"branches":[{"senses":"01 · 08","en":"THE WHOLE AND ITS UPKEEP: one organised machine, and the labour that keeps it working.","cn":"整体及其维护：一台有组织的机器，以及让它持续运转的劳动。"},{"senses":"02","en":"OPEN CHANNELS: the dug network that carries water across fields.","cn":"明渠：横跨田间输水的挖成网络。"},{"senses":"03 · 04","en":"EMITTERS: drip tubes and spray heads, the parts that decide how water leaves the system.","cn":"出水部件：滴管与喷头，决定水以何种方式离开系统。"},{"senses":"05 · 06","en":"SITES: one farm's plots, or a park's turf, each with its own boundary.","cn":"场地：一户农场的田块，或公园的草坪，各有边界。"},{"senses":"07","en":"OLD WORKS: tunnels and wells from earlier centuries, still systems in the same sense.","cn":"古老工程：几百年前的隧洞与井，仍是同一意义上的系统。"}]},"affixes":{"intro":{"en":"Irrigation system reads as two words: a Latin-derived noun of watering and a Greek-derived noun for an organised whole.","cn":"irrigation system 可读作两个词：一个源自拉丁的「浇水」名词，与一个源自希腊的「有组织整体」名词。"},"latinIntro":{"en":"The Latin side has a real family: irrigare, irrigatio, irrigator, irrigabilis. The system side is Greek, borrowed into Latin as systema, so it has no inherited Latin relatives.","cn":"拉丁一侧有真实词族：irrigare、irrigatio、irrigator、irrigabilis。system 一侧属希腊语，以 systema 借入拉丁语，因此没有拉丁固有同族词。"},"items":[{"word":"ir-","structure":"Latin in- 'into', assimilated to ir- before r","meaning":"into","meaningCN":"进入","example":"The prefix points the water inward.","exampleCN":"这个前缀把水指向内部。"},{"word":"rig-","structure":"Latin rigare 'to water, moisten'","meaning":"to water","meaningCN":"浇水","example":"Rig- is the watering root of the first word.","exampleCN":"rig- 是第一个词的浇水词根。"},{"word":"-ation","structure":"Latin -atio, action-noun suffix","meaning":"the act or process","meaningCN":"行为或过程","example":"The suffix turns the verb into a noun.","exampleCN":"这个后缀把动词变成名词。"},{"word":"system-","structure":"Greek systema 'organised whole'","meaning":"an organised whole","meaningCN":"有组织的整体","example":"System- names the arrangement, not the water.","exampleCN":"system- 指有组织的安排，而非水本身。"},{"word":"-atic","structure":"-atikos, Greek adjective suffix","meaning":"arranged as a system","meaningCN":"成体系的","example":"The suffix yields systematic.","exampleCN":"这个后缀构成 systematic。"},{"word":"irrigate","structure":"ir- + rig- + -ate","meaning":"to supply water","meaningCN":"供水、浇灌","example":"Farmers irrigate before the dry month.","exampleCN":"农民在干旱月之前浇灌。"},{"word":"irrigator","structure":"irrigate + -or","meaning":"one who or that which irrigates","meaningCN":"进行灌溉的人或器具","example":"The irrigator opens the head gate.","exampleCN":"灌溉者打开首部闸门。"},{"word":"irrigable","structure":"irrigate + -able","meaning":"able to be irrigated","meaningCN":"可以灌溉的","example":"The flat land is irrigable.","exampleCN":"平坦的土地可以灌溉。"},{"word":"systematic","structure":"system + -atic","meaning":"orderly, done by system","meaningCN":"有条理的、按系统的","example":"The repairs follow a systematic plan.","exampleCN":"修理按一套有条理的计划进行。"},{"word":"systematize","structure":"system + -atize","meaning":"to arrange into a system","meaningCN":"使系统化","example":"Engineers systematize the records of every gate.","exampleCN":"工程师把每座闸口的记录系统化。"}],"latinEntries":[{"word":"irrigatio","structure":"Latin noun of action from irrigare","meaning":"a watering, a supplying of water","meaningCN":"浇水、供水"},{"word":"irrigare","structure":"Latin verb: in- + rigare","meaning":"to lead water in, to water","meaningCN":"引水入、浇灌"},{"word":"rigare","structure":"Latin verb","meaning":"to water, moisten","meaningCN":"浇水、润湿"},{"word":"systema","structure":"Latin noun borrowed from Greek systema","meaning":"an organised whole","meaningCN":"有组织的整体"}]}}]);
